#!/bin/bash
#
# =============================================================================
#  GNSS Caster — NTRIP caster (RTK base station) installer for Raspberry Pi
# =============================================================================
#
#  Self-contained installer: a single Bash script that unpacks and configures a
#  complete NTRIP caster on a Raspberry Pi (Ubuntu 24.04/26.04 LTS, Raspberry
#  Pi OS or Debian). It deploys a
#  Flask/waitress web application, a SQLite database, systemd services and an
#  nginx reverse proxy; drives a Unicore UM980 base receiver over Bluetooth
#  (BlueZ/D-Bus); and streams RTCM3 corrections to rovers over NTRIP (port 2101).
#
#  Requirements : root privileges; Raspberry Pi / Ubuntu 24.04 or 26.04 LTS /
#                 Debian; Python 3.11+ (tested on 3.12 and 3.14).
#  Usage        : sudo ./<script>.sh [install|--uninstall|--repair|...]
#                 Run "./<script>.sh --help" for the full list of modes and the
#                 environment-variable options (TLS, ports, fail2ban, ...).
#
#  Version      : see CASTER_VERSION below (single source of truth).
#  Copyright    : (c) 2026 rslpro. All rights reserved.
#  License      : proprietary - not licensed for redistribution.
# =============================================================================

# This installer is written in bash and uses bash-only features (indirect
# expansion, "printf -v", [[ ]], $EUID). Running it as "sh script.sh" would
# execute it under dash on Debian/Ubuntu and fail with confusing errors, so
# re-exec under bash instead. This block is deliberately POSIX-compatible so
# that dash can parse it before handing over.
if [ -z "${BASH_VERSION:-}" ]; then
    if command -v bash >/dev/null 2>&1; then
        exec bash "$0" "$@"
    fi
    echo "ERROR: this installer requires bash, which was not found." >&2
    echo "Install it (apt install bash) and re-run: bash $0" >&2
    exit 1
fi

set -eE

# Product version. This is the single source of truth for the startup banner,
# the --version flag and the runtime "Server: GNSS-Caster/<version>" NTRIP
# header (the latter via the generated app/version.py). Bump on every release.
CASTER_VERSION="3.2.0"

# Basename of this script as invoked, so --help / usage text stays correct even
# if the file is renamed for distribution.
SCRIPT_NAME="$(basename "$0")"

# Answer --version/-v early and quietly, before the install machinery and the
# startup banner run, so the output stays script-friendly.
case "${1:-}" in
    -v|--version)
        echo "gnss-caster $CASTER_VERSION"
        exit 0
        ;;
esac

echo "=== GNSS Caster install/uninstall script v$CASTER_VERSION ==="
echo ""

# ----------------- CONFIGURATION -----------------
# Global paths, service identity and install-time tunables (ports, TLS,
# fail2ban, Bluetooth pairing). Values marked below are overridable via
# environment variables; CASTER_VERSION above is the single version source.
BASE=/opt/gnss-caster
APP=$BASE/app
VENV=$BASE/venv
INST=$BASE/instance
BACKUP_DIR=$BASE/backups
LOG_DIR=/var/log/gnss-caster
SERVICE_USER=gnss-caster
SERVICE_GROUP=gnss-caster
SERVICE=/etc/systemd/system/gnss-caster.service
NGINX_AVAILABLE=/etc/nginx/sites-available/gnss-caster
NGINX_ENABLED=/etc/nginx/sites-enabled/gnss-caster
NGINX_SECURITY_CONF=/etc/nginx/conf.d/gnss-caster-security.conf
FAIL2BAN_FILTER=/etc/fail2ban/filter.d/gnss-caster-auth.conf
FAIL2BAN_JAIL=/etc/fail2ban/jail.d/gnss-caster-auth.local
UFW_APP_PROFILE=/etc/ufw/applications.d/gnss-caster
PRIVILEGED_HELPER=$BASE/gnss-caster-privileged-helper.sh
SUDOERS_FILE=/etc/sudoers.d/gnss-caster
POLKIT_RULE=/etc/polkit-1/rules.d/49-gnss-caster-bluetooth.rules
MAINTENANCE_CRON=/etc/cron.d/gnss-caster-maintenance
BACKUP_CRON=/etc/cron.d/gnss-caster-backup
SECRET_KEY=""
SECRET_DIR="/etc/gnss-caster/secrets"
SECRET_KEY_ENV_FILE="$SECRET_DIR/secret.env"
LEGACY_SECRET_KEY_ENV_FILE="$INST/secret.env"
OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE=/etc/gnss-caster/initial-admin-password
BOOTSTRAP_ADMIN_PASSWORD_FILE=$INST/initial-admin-password
INSTALL_REPORT=$INST/install-report.txt

# TLS configuration
# TLS_MODE: none | selfsigned | letsencrypt
# Examples:
#   TLS_MODE=selfsigned TLS_DOMAIN=caster.local ./<script>.sh
#   TLS_MODE=letsencrypt TLS_DOMAIN=caster.example.com TLS_EMAIL=admin@example.com ./<script>.sh
TLS_MODE_RAW="${TLS_MODE:-}"
if [ -n "$TLS_MODE_RAW" ]; then
    TLS_MODE_SET_BY_USER=1
else
    TLS_MODE_SET_BY_USER=0
fi
TLS_MODE=$(echo "${TLS_MODE_RAW:-none}" | tr '[:upper:]' '[:lower:]')
TLS_DOMAIN="${TLS_DOMAIN:-}"
TLS_EMAIL="${TLS_EMAIL:-}"
TLS_SELF_SIGNED_DAYS="${TLS_SELF_SIGNED_DAYS:-3650}"
# Paths to an already-issued certificate, used when TLS_MODE=existing. The cert
# should be the full chain (leaf + intermediates); the key must match it.
TLS_CERT_FILE="${TLS_CERT_FILE:-}"
TLS_KEY_FILE="${TLS_KEY_FILE:-}"
LE_WEBROOT="/var/www/certbot"
SELF_SIGNED_CERT="/etc/ssl/certs/gnss-caster.crt"
SELF_SIGNED_KEY="/etc/ssl/private/gnss-caster.key"
SSL_CERT_PATH=""
SSL_KEY_PATH=""
NGINX_SERVER_NAME="_"
INSTALL_WEB_PORT="${GNSS_CASTER_WEB_PORT:-8080}"
INSTALL_NTRIP_PORT="${GNSS_CASTER_NTRIP_PORT:-2101}"
ENABLE_FAIL2BAN="${GNSS_CASTER_ENABLE_FAIL2BAN:-0}"
ENABLE_AUTO_UPDATE="${GNSS_CASTER_ENABLE_AUTO_UPDATE:-0}"
FORCE_PORT_KILL="${GNSS_CASTER_FORCE_PORT_KILL:-0}"
ENABLE_WATCHDOG="${GNSS_CASTER_ENABLE_WATCHDOG:-0}"
# Bluetooth pairing controls (stored in secret.env, mode 600, not in the unit).
BT_DEFAULT_PIN="${GNSS_CASTER_BT_DEFAULT_PIN:-0000}"
BT_FALLBACK_PINS="${GNSS_CASTER_BT_FALLBACK_PINS:-1234,1111}"
# BT_AUTO_ACCEPT=1 keeps backward-compatible open pairing; set to 0 to only
# accept devices listed in GNSS_CASTER_BT_ALLOWED_DEVICES (comma separated MACs).
BT_AUTO_ACCEPT="${GNSS_CASTER_BT_AUTO_ACCEPT:-1}"
BT_ALLOWED_DEVICES="${GNSS_CASTER_BT_ALLOWED_DEVICES:-}"
FAIL2BAN_WAS_PRESENT=0
FAIL2BAN_WAS_ACTIVE=0
FAIL2BAN_GNSS_JAIL_WAS_PRESENT=0
FAIL2BAN_DISABLED_BY_INSTALLER=0
BACKUP_CRON_STATUS="default enabled"
LOGROTATE_STATUS="default rotate 30 days"
WATCHDOG_CRON_STATUS="disabled"
ROLLBACK_DIR=""
ROLLBACK_ACTIVE=0
ROLLBACK_ROOT="/var/backups/gnss-caster"
INSTALL_STATE_CAPTURED=0
INSTALL_COMMITTED=0
INSTALL_CASTER_WAS_ACTIVE=0
INSTALL_NGINX_WAS_ACTIVE=0
INSTALL_CASTER_ENABLED="not-found"
INSTALL_HEALTH_WAS_OK=0
INSTALL_HEALTH_URL=""
INSTALL_FAILED_LINE="unknown"

SCRIPT_MODE="${1:-}"

# Purge flag for uninstall: keep data by default, delete everything only when
# explicitly requested via --purge or GNSS_CASTER_PURGE=1.
PURGE_DATA=0
case "${GNSS_CASTER_PURGE:-0}" in
    1|true|yes|on|TRUE|YES|ON)
        PURGE_DATA=1
        ;;
esac
for cli_arg in "$@"; do
    if [ "$cli_arg" = "--purge" ]; then
        PURGE_DATA=1
    fi
done

show_usage() {
cat << EOF
Usage:
  ./$SCRIPT_NAME [install|--uninstall|--reset-admin-password|--diagnose|--status|--repair|--self-test]

Modes:
  install                 Run full installation (default)
  --uninstall             Remove GNSS Caster files and configuration (data preserved by default)
  --reset-admin-password  Reset built-in admin password and rewrite bootstrap credentials
  --diagnose              Collect service, network, and log diagnostics
  --status                Show quick runtime status without changing services
  --repair                Repair permissions, systemd, nginx, cron, logrotate, and DB schema
  --self-test             Run installer/runtime consistency checks without changing services
  --rotate-secrets        Rotate SECRET_KEY (and optionally Bluetooth PIN) and restart the service
  --panic                 Revoke API tokens and web sessions; reset 2FA for ALL admins
  --version, -v           Print the caster version and exit
  --help, -h              Show this help and exit

TLS examples for install mode:
  TLS_MODE=selfsigned TLS_DOMAIN=caster.local ./$SCRIPT_NAME
  TLS_MODE=letsencrypt TLS_DOMAIN=example.com TLS_EMAIL=admin@example.com ./$SCRIPT_NAME
  TLS_MODE=existing TLS_CERT_FILE=/etc/ssl/mycert/fullchain.pem TLS_KEY_FILE=/etc/ssl/mycert/privkey.pem ./$SCRIPT_NAME

Port override example for install mode:
  GNSS_CASTER_WEB_PORT=8081 GNSS_CASTER_NTRIP_PORT=2201 ./$SCRIPT_NAME

Optional fail2ban hardening for install mode:
  GNSS_CASTER_ENABLE_FAIL2BAN=1 ./$SCRIPT_NAME

Optional weekly auto-update for install mode:
  GNSS_CASTER_ENABLE_AUTO_UPDATE=1 ./$SCRIPT_NAME

Optional force-kill occupied runtime port for install mode:
  GNSS_CASTER_FORCE_PORT_KILL=1 ./$SCRIPT_NAME

Optional safe health watchdog cron for install mode:
  GNSS_CASTER_ENABLE_WATCHDOG=1 ./$SCRIPT_NAME

Interactive install uses a whiptail/dialog menu when available on a terminal.
Force plain text prompts with:
  GNSS_CASTER_NO_TUI=1 ./$SCRIPT_NAME

Uninstall examples:
  ./$SCRIPT_NAME --uninstall            # remove /opt/gnss-caster, keep safety backup in /var/backups/gnss-caster
  ./$SCRIPT_NAME --uninstall --purge    # delete everything, including data (no safety backup)

Recovery example:
  ./$SCRIPT_NAME --reset-admin-password

Diagnostics example:
  ./$SCRIPT_NAME --diagnose

Status example:
  ./$SCRIPT_NAME --status

Repair example:
  ./$SCRIPT_NAME --repair

Self-test example:
  sudo ./$SCRIPT_NAME --self-test
EOF
}

# ----------------- INTERACTIVE UI (TUI) -----------------
# Optional ncurses-style front-end for the interactive prompts. Prefers whiptail
# (shipped by default on Raspberry Pi OS / Debian / Ubuntu), then dialog, and
# otherwise falls back to plain text prompts. Only the *configuration questions*
# are dialog-driven; the install itself still streams its log to the terminal so
# errors stay visible. Force plain prompts with GNSS_CASTER_NO_TUI=1.
UI_BIN=""
detect_ui_backend() {
    UI_BIN=""
    [ "${GNSS_CASTER_NO_TUI:-0}" = "1" ] && return
    [ -t 0 ] && [ -t 1 ] || return
    if command -v whiptail >/dev/null 2>&1; then UI_BIN="whiptail"; return; fi
    if command -v dialog >/dev/null 2>&1; then UI_BIN="dialog"; return; fi
}

ui_enabled() { [ -n "$UI_BIN" ]; }

# ui_menu TITLE TEXT tag1 label1 [tag2 label2 ...] -> prints the chosen tag
ui_menu() {
    local title="$1" text="$2"; shift 2
    "$UI_BIN" --title "$title" --menu "$text" 20 76 11 "$@" 3>&1 1>&2 2>&3
}

# ui_input TITLE TEXT [DEFAULT] -> prints the entered text
ui_input() {
    "$UI_BIN" --title "$1" --inputbox "$2" 10 76 "${3:-}" 3>&1 1>&2 2>&3
}

# ui_yesno TITLE TEXT [defaultno] -> exit status 0=yes, 1=no
ui_yesno() {
    local extra=""; [ "${3:-}" = "defaultno" ] && extra="--defaultno"
    "$UI_BIN" --title "$1" $extra --yesno "$2" 12 76
}

# ui_msgbox TITLE TEXT
ui_msgbox() { "$UI_BIN" --title "$1" --msgbox "$2" 16 76; }

# ui_checklist TITLE TEXT tag1 label1 on/off [...] -> prints chosen tags (space-separated)
ui_checklist() {
    local title="$1" text="$2"; shift 2
    "$UI_BIN" --title "$title" --checklist "$text" 18 76 8 "$@" 3>&1 1>&2 2>&3 | tr -d '"'
}

prompt_script_mode() {
    if [ -n "$SCRIPT_MODE" ]; then
        return
    fi

    if [ ! -t 0 ]; then
        SCRIPT_MODE="install"
        return
    fi

    detect_ui_backend

    if ui_enabled; then
        local choice
        choice=$(ui_menu "GNSS Caster $CASTER_VERSION" "Select an operation:" \
            install              "Install or upgrade GNSS Caster" \
            uninstall            "Remove GNSS Caster (data preserved)" \
            reset-admin-password "Reset the admin password" \
            diagnose             "Collect diagnostics" \
            status               "Show runtime status" \
            repair               "Repair an existing installation" \
            self-test            "Run consistency checks" \
            rotate-secrets       "Rotate SECRET_KEY / Bluetooth PIN" \
            panic                "Revoke all API tokens + web sessions + disable 2FA")
        SCRIPT_MODE="${choice:-install}"
        return
    fi

    echo "Select operation mode:"
    echo "  1) install"
    echo "  2) uninstall"
    echo "  3) reset admin password"
    echo "  4) diagnose"
    echo "  5) status"
    echo "  6) repair"
    echo "  7) self-test"
    echo "  8) rotate secrets"
    echo "  9) panic (revoke all API tokens + web sessions + disable all 2FA)"
    echo -n "Enter choice [1-9] (default: 1): "
    read -r mode_choice

    case "$mode_choice" in
        ""|1)
            SCRIPT_MODE="install"
            ;;
        2)
            SCRIPT_MODE="uninstall"
            ;;
        3)
            SCRIPT_MODE="reset-admin-password"
            ;;
        4)
            SCRIPT_MODE="diagnose"
            ;;
        5)
            SCRIPT_MODE="status"
            ;;
        6)
            SCRIPT_MODE="repair"
            ;;
        7)
            SCRIPT_MODE="self-test"
            ;;
        8)
            SCRIPT_MODE="rotate-secrets"
            ;;
        9)
            SCRIPT_MODE="panic"
            ;;
        *)
            echo "ERROR: Invalid choice '$mode_choice'"
            exit 1
            ;;
    esac
}

prompt_tls_mode() {
    if [ "$SCRIPT_MODE" != "install" ]; then
        return
    fi

    if [ "$TLS_MODE_SET_BY_USER" -eq 1 ]; then
        return
    fi

    if [ ! -t 0 ]; then
        return
    fi

    detect_ui_backend
    if ui_enabled; then
        local tls_sel
        tls_sel=$(ui_menu "TLS / HTTPS" "How should the web interface be served?" \
            none        "HTTP only (no TLS)" \
            selfsigned  "HTTPS with a self-signed certificate" \
            letsencrypt "HTTPS with a Let's Encrypt certificate" \
            existing    "HTTPS with a certificate you already have")
        TLS_MODE="${tls_sel:-none}"

        if [ "$TLS_MODE" = "selfsigned" ] && [ -z "$TLS_DOMAIN" ]; then
            TLS_DOMAIN=$(ui_input "Self-signed certificate" "Domain / CN (optional; leave blank to use the hostname):" "")
        fi
        if [ "$TLS_MODE" = "letsencrypt" ]; then
            while [ -z "$TLS_DOMAIN" ]; do
                TLS_DOMAIN=$(ui_input "Let's Encrypt" "Domain (required; must resolve to this host):" "")
            done
            while [ -z "$TLS_EMAIL" ]; do
                TLS_EMAIL=$(ui_input "Let's Encrypt" "Email for the ACME account (required):" "")
            done
        fi
        if [ "$TLS_MODE" = "existing" ]; then
            while [ -z "$TLS_CERT_FILE" ]; do
                TLS_CERT_FILE=$(ui_input "Existing certificate" "Path to the full-chain PEM certificate:" "")
            done
            while [ -z "$TLS_KEY_FILE" ]; do
                TLS_KEY_FILE=$(ui_input "Existing certificate" "Path to the matching private key (PEM):" "")
            done
            if [ -z "$TLS_DOMAIN" ]; then
                TLS_DOMAIN=$(ui_input "Existing certificate" "Server name for nginx (optional):" "")
            fi
        fi
        return
    fi

    echo ""
    echo "Select TLS mode:"
    echo "  1) none (HTTP)"
    echo "  2) selfsigned (HTTPS with self-signed certificate)"
    echo "  3) letsencrypt (HTTPS with trusted certificate)"
    echo "  4) existing (HTTPS with a certificate you already have)"
    echo -n "Enter choice [1-4] (default: 1): "
    read -r tls_choice

    case "$tls_choice" in
        ""|1)
            TLS_MODE="none"
            ;;
        2)
            TLS_MODE="selfsigned"
            ;;
        3)
            TLS_MODE="letsencrypt"
            ;;
        4)
            TLS_MODE="existing"
            ;;
        *)
            echo "ERROR: Invalid TLS choice '$tls_choice'"
            exit 1
            ;;
    esac

    if [ "$TLS_MODE" = "selfsigned" ] && [ -z "$TLS_DOMAIN" ]; then
        echo -n "Enter TLS domain/CN (optional, press Enter to use hostname): "
        read -r TLS_DOMAIN
    fi

    if [ "$TLS_MODE" = "letsencrypt" ]; then
        while [ -z "$TLS_DOMAIN" ]; do
            echo -n "Enter TLS domain (required): "
            read -r TLS_DOMAIN
        done

        while [ -z "$TLS_EMAIL" ]; do
            echo -n "Enter TLS email (required): "
            read -r TLS_EMAIL
        done
    fi

    if [ "$TLS_MODE" = "existing" ]; then
        while [ -z "$TLS_CERT_FILE" ]; do
            echo -n "Enter path to certificate (full-chain PEM): "
            read -r TLS_CERT_FILE
        done
        while [ -z "$TLS_KEY_FILE" ]; do
            echo -n "Enter path to private key (PEM): "
            read -r TLS_KEY_FILE
        done
        if [ -z "$TLS_DOMAIN" ]; then
            echo -n "Enter server name/domain for nginx (optional, press Enter for any): "
            read -r TLS_DOMAIN
        fi
    fi
}

prompt_script_mode

case "$SCRIPT_MODE" in
    install|"")
        SCRIPT_MODE="install"
        ;;
    --uninstall|uninstall)
        SCRIPT_MODE="uninstall"
        ;;
    --purge|purge)
        SCRIPT_MODE="uninstall"
        PURGE_DATA=1
        ;;
    --reset-admin-password|reset-admin-password)
        SCRIPT_MODE="reset-admin-password"
        ;;
    --diagnose|diagnose)
        SCRIPT_MODE="diagnose"
        ;;
    --status|status)
        SCRIPT_MODE="status"
        ;;
    --repair|repair)
        SCRIPT_MODE="repair"
        ;;
    --self-test|self-test)
        SCRIPT_MODE="self-test"
        ;;
    --rotate-secrets|rotate-secrets)
        SCRIPT_MODE="rotate-secrets"
        ;;
    --panic|--revoke-access|panic)
        SCRIPT_MODE="panic"
        ;;
    -h|--help)
        show_usage
        exit 0
        ;;
    *)
        echo "ERROR: Unsupported argument '$SCRIPT_MODE'"
        show_usage
        exit 1
        ;;
esac

strip_crlf() {
    local target="$1"
    if [ -f "$target" ]; then
        sed -i 's/\r$//' "$target" || true
    fi
}

# normalize_bool VAR_NAME ENV_VAR_LABEL
# Accepts 1/true/yes/on -> sets VAR_NAME=1; 0/false/no/off/"" -> sets VAR_NAME=0; else exits.
normalize_bool() {
    local var_name="$1"
    local env_label="$2"
    local val
    val=$(printf '%s' "${!var_name}" | tr '[:upper:]' '[:lower:]')
    case "$val" in
        1|true|yes|on)
            printf -v "$var_name" '%s' "1"
            ;;
        0|false|no|off|"")
            printf -v "$var_name" '%s' "0"
            ;;
        *)
            echo "ERROR: $env_label must be 0/1, true/false, yes/no, or on/off"
            exit 1
            ;;
    esac
}

# ----------------- PRE-FLIGHT CHECKS -----------------
# Validate the host before changing anything: root privileges, OS/arch,
# required commands, port availability, an existing installation and free
# disk space. Fails early with a clear message instead of halfway through.
if [ "$EUID" -ne 0 ]; then 
    echo "ERROR: Please run as root"
    exit 1
fi

# Prevent concurrent installer runs
INSTALL_LOCK_FILE="/run/gnss-caster-installer.lock"
exec 9>"$INSTALL_LOCK_FILE"
if ! flock -n 9; then
    echo "ERROR: Another instance of the GNSS Caster installer is already running (lock: $INSTALL_LOCK_FILE)"
    exit 1
fi
# Leave the lock inode in place. Closing the descriptor on exit releases it;
# unlinking it would let another process lock a different inode at the same path.

EXPECT_BOOTSTRAP_ADMIN_PASSWORD=0
if [ "$SCRIPT_MODE" = "install" ] && [ ! -f "$INST/db.sqlite" ]; then
    EXPECT_BOOTSTRAP_ADMIN_PASSWORD=1
fi

if [ "$SCRIPT_MODE" = "install" ]; then
    normalize_bool ENABLE_FAIL2BAN   "GNSS_CASTER_ENABLE_FAIL2BAN"
    normalize_bool ENABLE_AUTO_UPDATE "GNSS_CASTER_ENABLE_AUTO_UPDATE"
    normalize_bool FORCE_PORT_KILL    "GNSS_CASTER_FORCE_PORT_KILL"
    normalize_bool ENABLE_WATCHDOG    "GNSS_CASTER_ENABLE_WATCHDOG"

    if command -v fail2ban-client >/dev/null 2>&1; then
        FAIL2BAN_WAS_PRESENT=1
    fi

    if [ -f "$FAIL2BAN_JAIL" ]; then
        FAIL2BAN_GNSS_JAIL_WAS_PRESENT=1
    fi

    if command -v systemctl >/dev/null 2>&1 && systemctl is-active --quiet fail2ban; then
        FAIL2BAN_WAS_ACTIVE=1
    fi
fi

backup_and_clear_unit_override() {
    local override_dir="/etc/systemd/system/gnss-caster.service.d"
    if [ -d "$override_dir" ]; then
        local ts
        ts=$(date +%Y%m%d_%H%M%S)
        mkdir -p "$BACKUP_DIR"
        cp -a "$override_dir" "$BACKUP_DIR/systemd-override-$ts" || true
        rm -rf "$override_dir"
    fi
}

acquire_maintenance_lock() {
    local lock_path="/run/gnss-caster-maintenance.lock"
    # Nested update -> backup/restore calls inherit fd 8 and the same lock.
    # Verify the descriptor itself; never trust an environment-variable bypass.
    if [ "$(readlink "/proc/$$/fd/8" 2>/dev/null || true)" != "$lock_path" ]; then
        exec 8>"$lock_path"
    fi
    if ! flock -n 8; then
        echo "ERROR: Another GNSS Caster maintenance operation is running." >&2
        return 1
    fi
    # Do not explicitly unlock: a nested child must not release its parent's lock.
}

sqlite_database_tool() {
    # Stdlib only, so this also works before the application/venv is upgraded.
    python3 -I - "$@" << 'PY_SQLITE_TOOL'
from contextlib import closing
import os
from pathlib import Path
import sqlite3
import stat
import sys
import tempfile
import time


def sqlite_database_tool(mode, source_path, destination_path=None):
    if mode not in ('check', 'snapshot', 'restore'):
        raise ValueError('Unknown database operation')
    source = Path(source_path).resolve(strict=True)
    with closing(sqlite3.connect(source.as_uri() + '?mode=ro', uri=True, timeout=1)) as reader:
        if mode == 'check':
            if reader.execute('PRAGMA integrity_check').fetchall() != [('ok',)]:
                raise ValueError('SQLite integrity check failed')
            return
        destination = Path(destination_path).absolute()
        if destination.is_symlink() or destination.resolve() == source:
            raise ValueError('Database destination must be a separate regular path')
        deadline = time.monotonic() + 30
        def progress(status, remaining, total):
            if time.monotonic() >= deadline:
                raise TimeoutError('SQLite snapshot exceeded 30 seconds')
        descriptor, temporary_name = tempfile.mkstemp(prefix='.gnss-db-', dir=destination.parent)
        os.close(descriptor)
        temporary = Path(temporary_name)
        try:
            with closing(sqlite3.connect(temporary, timeout=1)) as writer:
                reader.backup(writer, pages=256, progress=progress, sleep=0.05)
                # The result must be independently usable without any sidecar.
                writer.execute('PRAGMA journal_mode=DELETE')
                if writer.execute('PRAGMA integrity_check').fetchall() != [('ok',)]:
                    raise ValueError('SQLite snapshot integrity check failed')
            source_stat = source.stat()
            with temporary.open('r+b') as handle:
                os.fsync(handle.fileno())
            os.chmod(temporary, stat.S_IMODE(source_stat.st_mode))
            if os.name == 'posix':
                os.chown(temporary, source_stat.st_uid, source_stat.st_gid)
            if mode == 'restore':
                # Caller MUST have stopped all writers and hold the maintenance
                # lock. Never attach old WAL/journal files to the restored DB.
                for suffix in ('-shm', '-journal', '-wal'):
                    Path(str(destination) + suffix).unlink(missing_ok=True)
            os.replace(temporary, destination)
            if os.name == 'posix':
                directory_fd = os.open(destination.parent, os.O_RDONLY | os.O_DIRECTORY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
        finally:
            for suffix in ('', '-wal', '-shm', '-journal'):
                Path(str(temporary) + suffix).unlink(missing_ok=True)


if __name__ == '__main__':
    try:
        sqlite_database_tool(*sys.argv[1:])
    except Exception as exc:
        print(f'ERROR: SQLite operation failed: {exc}', file=sys.stderr)
        sys.exit(1)
PY_SQLITE_TOOL
}

rollback_backup_path() {
    local source_path="$1"
    printf '%s/files%s\n' "$ROLLBACK_DIR" "$source_path"
}

backup_path_for_rollback() {
    local source_path="$1"
    local dest_path

    if [ -z "$ROLLBACK_DIR" ]; then
        return 0
    fi

    dest_path=$(rollback_backup_path "$source_path")
    mkdir -p "$(dirname "$dest_path")"

    if [ -e "$source_path" ] || [ -L "$source_path" ]; then
        # A rollback snapshot is only useful if it is complete. Never record an
        # object as backed up after a failed copy: doing so could make rollback
        # delete the live object and replace it with a partial snapshot.
        if { [ "$source_path" = "$INST/db.sqlite" ] &&
                sqlite_database_tool snapshot "$source_path" "$dest_path"; } ||
           { [ "$source_path" != "$INST/db.sqlite" ] && cp -a "$source_path" "$dest_path"; }; then
            printf '%s\n' "$source_path" >> "$ROLLBACK_DIR/existed.list"
        else
            echo "ERROR: Failed to snapshot $source_path for rollback" >&2
            rm -rf "$dest_path" 2>/dev/null || true
            return 1
        fi
    else
        printf '%s\n' "$source_path" >> "$ROLLBACK_DIR/missing.list"
    fi
}

print_install_rollback_paths() {
    printf '%s\n' \
        "$SERVICE" \
        "/etc/systemd/system/gnss-caster.service.d" \
        "$NGINX_AVAILABLE" \
        "$NGINX_ENABLED" \
        "/etc/nginx/sites-enabled/default" \
        "$NGINX_SECURITY_CONF" \
        "$FAIL2BAN_FILTER" \
        "$FAIL2BAN_JAIL" \
        "$UFW_APP_PROFILE" \
        "$MAINTENANCE_CRON" \
        "$BACKUP_CRON" \
        "/etc/cron.d/gnss-caster-cert-renew" \
        "/etc/logrotate.d/gnss-caster" \
        "$SUDOERS_FILE" \
        "$POLKIT_RULE" \
        "$PRIVILEGED_HELPER" \
        "$BASE/main.py" \
        "$BASE/requirements.txt" \
        "$BASE/sqlite-functions.sh" \
        "$BASE/backup.sh" \
        "$BASE/restore.sh" \
        "$BASE/monitor.sh" \
        "$BASE/watchdog.sh" \
        "$BASE/update.sh" \
        "$BASE/diagnose.sh" \
        "$BASE/status.sh" \
        "$BASE/repair.sh" \
        "$BASE/gnss-caster-installer.sh" \
        "$APP" \
        "$VENV" \
        "$INST/config.yaml" \
        "$INST/config.py" \
        "$INST/db.sqlite" \
        "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" \
        "$BOOTSTRAP_ADMIN_PASSWORD_FILE" \
        "$SECRET_DIR" \
        "$LEGACY_SECRET_KEY_ENV_FILE" \
        "$SELF_SIGNED_CERT" \
        "$SELF_SIGNED_KEY"
    local legacy_backup
    for legacy_backup in "$INST"/secret.env.bak-*; do
        [ -e "$legacy_backup" ] || [ -L "$legacy_backup" ] || continue
        printf '%s\n' "$legacy_backup"
    done
    if [ "$SCRIPT_MODE" = repair ]; then
        printf '%s\n' /etc/ufw/user.rules /etc/ufw/user6.rules
    fi
}

create_install_rollback_snapshot() {
    local ts
    local path
    local existing_state_found=0

    systemctl is-active --quiet gnss-caster && INSTALL_CASTER_WAS_ACTIVE=1 || INSTALL_CASTER_WAS_ACTIVE=0
    systemctl is-active --quiet nginx && INSTALL_NGINX_WAS_ACTIVE=1 || INSTALL_NGINX_WAS_ACTIVE=0
    INSTALL_CASTER_ENABLED=$(systemctl is-enabled gnss-caster 2>/dev/null || true)
    INSTALL_CASTER_ENABLED="${INSTALL_CASTER_ENABLED:-not-found}"
    INSTALL_STATE_CAPTURED=1
    if [ "$INSTALL_CASTER_WAS_ACTIVE" -eq 1 ]; then
        INSTALL_HEALTH_URL="http://127.0.0.1:$(get_config_value web_port 8080)/api/health"
        curl -fsS --max-time 3 "$INSTALL_HEALTH_URL" >/dev/null 2>&1 && INSTALL_HEALTH_WAS_OK=1 || INSTALL_HEALTH_WAS_OK=0
        # Freeze config and database together before copying any runtime files.
        # EXIT recovery resumes this service even if snapshot creation fails.
        systemctl stop gnss-caster || return 1
    fi
    if systemctl is-active --quiet gnss-caster; then
        echo "ERROR: GNSS Caster is still running; refusing to snapshot." >&2
        return 1
    fi

    # Treat installation as "existing" only when core runtime/config artifacts
    # are present. An empty /opt/gnss-caster directory alone should not trigger
    # rollback snapshot creation during a clean install.
    for path in \
        "$SERVICE" \
        "$NGINX_AVAILABLE" \
        "$APP" \
        "$VENV" \
        "$INST/config.yaml" \
        "$INST/db.sqlite" \
        "$PRIVILEGED_HELPER" \
        "$SUDOERS_FILE" \
        "$POLKIT_RULE"; do
        if [ -e "$path" ] || [ -L "$path" ]; then
            existing_state_found=1
            break
        fi
    done

    if [ "$existing_state_found" -ne 1 ]; then
        ROLLBACK_DIR=""
        ROLLBACK_ACTIVE=0
        echo "Clean install detected; no existing GNSS Caster state to snapshot."
        return 0
    fi

    ts=$(date +%Y%m%d_%H%M%S)
    mkdir -p "$ROLLBACK_ROOT" || return 1
    chown root:root "$ROLLBACK_ROOT" || return 1
    chmod 700 "$ROLLBACK_ROOT" || return 1
    ROLLBACK_DIR=$(mktemp -d "$ROLLBACK_ROOT/rollback-$ts-XXXXXX") || return 1
    : > "$ROLLBACK_DIR/existed.list"
    : > "$ROLLBACK_DIR/missing.list"

    while IFS= read -r path; do
        [ -n "$path" ] || continue
        backup_path_for_rollback "$path" || return 1
    done << EOF
$(print_install_rollback_paths)
EOF

    ROLLBACK_ACTIVE=1
    echo "Rollback snapshot created: $ROLLBACK_DIR"
}

restore_install_service_state() {
    local failed=0
    local attempt
    # Repair updates UFW application rules as well as its profile file.
    if [ "$SCRIPT_MODE" = repair ] && [ "${REPAIR_UFW_WAS_ACTIVE:-0}" -eq 1 ]; then
        ufw reload || return 1
    fi
    case "$INSTALL_CASTER_ENABLED" in
        enabled) systemctl enable gnss-caster >/dev/null 2>&1 || failed=1 ;;
        enabled-runtime) systemctl enable --runtime gnss-caster >/dev/null 2>&1 || failed=1 ;;
        disabled|not-found)
            if [ -f "$SERVICE" ]; then
                systemctl disable gnss-caster >/dev/null 2>&1 || failed=1
            fi
            ;;
    esac
    if [ "$INSTALL_NGINX_WAS_ACTIVE" -eq 1 ]; then
        if nginx -t; then
            if systemctl is-active --quiet nginx; then
                systemctl reload nginx || failed=1
            else
                systemctl start nginx || failed=1
            fi
        else
            failed=1
        fi
    elif systemctl is-active --quiet nginx; then
        systemctl stop nginx || failed=1
    fi
    if [ "$INSTALL_CASTER_WAS_ACTIVE" -eq 1 ]; then
        systemctl start gnss-caster || return 1
        systemctl is-active --quiet gnss-caster || return 1
        if [ "$INSTALL_HEALTH_WAS_OK" -eq 1 ]; then
            for attempt in {1..10}; do
                if curl -fsS --max-time 3 "$INSTALL_HEALTH_URL" >/dev/null 2>&1; then
                    return "$failed"
                fi
                sleep 1
            done
            echo "ERROR: Restored caster did not recover its previous web health." >&2
            return 1
        fi
    elif systemctl is-active --quiet gnss-caster; then
        systemctl stop gnss-caster || failed=1
    fi
    return "$failed"
}

validate_install_rollback_snapshot() {
    local source_path backup_path expected_path allowed
    [ -f "$ROLLBACK_DIR/existed.list" ] && [ -f "$ROLLBACK_DIR/missing.list" ] || return 1
    while IFS= read -r source_path; do
        allowed=0
        while IFS= read -r expected_path; do
            [ "$source_path" = "$expected_path" ] && allowed=1
        done < <(print_install_rollback_paths)
        [ "$allowed" -eq 1 ] || return 1
    done < <(cat "$ROLLBACK_DIR/existed.list" "$ROLLBACK_DIR/missing.list")
    while IFS= read -r source_path; do
        if grep -Fxq -- "$source_path" "$ROLLBACK_DIR/existed.list"; then
            if grep -Fxq -- "$source_path" "$ROLLBACK_DIR/missing.list"; then return 1; fi
            backup_path=$(rollback_backup_path "$source_path")
            [ -e "$backup_path" ] || [ -L "$backup_path" ] || return 1
            if [ "$source_path" = "$INST/db.sqlite" ]; then
                sqlite_database_tool check "$backup_path" || return 1
            fi
        else
            grep -Fxq -- "$source_path" "$ROLLBACK_DIR/missing.list" || return 1
        fi
    done < <(print_install_rollback_paths)
}

restore_install_rollback_snapshot() {
    local source_path backup_path
    local failed=0
    [ "$ROLLBACK_ACTIVE" -eq 1 ] && [ -d "$ROLLBACK_DIR" ] || return 1
    if ! systemctl stop gnss-caster; then
        if systemctl is-active --quiet gnss-caster; then return 1; fi
    fi
    if systemctl is-active --quiet gnss-caster; then return 1; fi
    # Validate every snapshot component before deleting any live file.
    if ! validate_install_rollback_snapshot; then
        echo "ERROR: Rollback snapshot is incomplete or invalid: $ROLLBACK_DIR" >&2
        return 1
    fi
    echo "Restoring GNSS Caster from $ROLLBACK_DIR"
    while IFS= read -r source_path; do
        if [ "$source_path" = "$INST/db.sqlite" ]; then
            rm -f -- "$source_path-wal" "$source_path-shm" "$source_path-journal" || failed=1
        fi
        rm -rf -- "$source_path" || failed=1
    done < "$ROLLBACK_DIR/missing.list"
    while IFS= read -r source_path; do
        backup_path=$(rollback_backup_path "$source_path")
        if ! mkdir -p "$(dirname "$source_path")"; then failed=1; continue; fi
        if [ "$source_path" = "$INST/db.sqlite" ]; then
            sqlite_database_tool restore "$backup_path" "$source_path" || failed=1
        elif rm -rf -- "$source_path"; then
            cp -a "$backup_path" "$source_path" || failed=1
        else
            failed=1
        fi
    done < "$ROLLBACK_DIR/existed.list"
    if [ "$failed" -ne 0 ]; then
        echo "ERROR: File rollback was incomplete; caster remains stopped. Snapshot: $ROLLBACK_DIR" >&2
        return 1
    fi
    systemctl daemon-reload || return 1
    restore_install_service_state || return 1
    ROLLBACK_ACTIVE=0
    echo "Rollback completed; previous service state restored."
}

handle_install_exit() {
    local exit_code=$?
    # ERR is inherited by command substitutions; only the main shell restores.
    [ "$BASHPID" = "$INSTALL_OWNER_BASHPID" ] || return "$exit_code"
    trap - EXIT ERR
    trap '' INT TERM HUP
    set +e
    if { [ "$SCRIPT_MODE" = "install" ] || [ "$SCRIPT_MODE" = "repair" ]; } && [ "$INSTALL_COMMITTED" -ne 1 ] && [ "$INSTALL_STATE_CAPTURED" -eq 1 ]; then
        [ "$exit_code" -ne 0 ] || exit_code=1
        echo "ERROR: $SCRIPT_MODE did not complete (near line $INSTALL_FAILED_LINE)."
        if [ "$ROLLBACK_ACTIVE" -eq 1 ]; then
            if ! restore_install_rollback_snapshot; then
                echo "ERROR: Automatic rollback failed. Inspect snapshot: $ROLLBACK_DIR" >&2
            fi
        else
            # No installation files have been changed during a failed snapshot.
            # On a clean install, there is no previous runtime to restore.
            if ! restore_install_service_state; then
                echo "ERROR: Could not restore the previous service state." >&2
            fi
        fi
        [ -z "$ROLLBACK_DIR" ] || echo "Snapshot retained: $ROLLBACK_DIR"
    fi
    exit "$exit_code"
}

begin_runtime_transaction() {
    if [ "$SCRIPT_MODE" = repair ] && command -v ufw >/dev/null 2>&1; then
        local firewall_status
        firewall_status=$(ufw status) || return 1
        REPAIR_UFW_WAS_ACTIVE=0
        if printf '%s\n' "$firewall_status" | grep -qi '^Status: active'; then
            REPAIR_UFW_WAS_ACTIVE=1
        fi
    fi
    INSTALL_OWNER_BASHPID=$BASHPID
    trap handle_install_exit EXIT
    trap 'INSTALL_FAILED_LINE=$LINENO' ERR
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 130' INT
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 143' TERM
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 129' HUP
    create_install_rollback_snapshot
}

finish_repair_transaction() {
    if ! run_install_smoke_tests; then
        echo "ERROR: Post-repair health gate failed; rolling back." >&2
        return 1
    fi
    # Repair temporarily starts the service to validate it, then preserves
    # the original activity and enablement settings (including nginx).
    restore_install_service_state || return 1
    INSTALL_COMMITTED=1
    ROLLBACK_ACTIVE=0
    trap - ERR INT TERM HUP
    # Legacy secret cleanup must follow commit: deleting these paths earlier
    # would change the manifest used by snapshot validation.
    manage_secret_files cleanup
}

validate_tls_config() {
    case "$TLS_MODE" in
        none|selfsigned|letsencrypt|existing)
            ;;
        *)
            echo "ERROR: Unsupported TLS_MODE='$TLS_MODE'"
            echo "Use one of: none, selfsigned, letsencrypt, existing"
            exit 1
            ;;
    esac

    if [ "$TLS_MODE" = "letsencrypt" ]; then
        if [ -z "$TLS_DOMAIN" ] || [ -z "$TLS_EMAIL" ]; then
            echo "ERROR: TLS_MODE=letsencrypt requires TLS_DOMAIN and TLS_EMAIL"
            echo "Example:"
            echo "  TLS_MODE=letsencrypt TLS_DOMAIN=example.com TLS_EMAIL=admin@example.com ./$SCRIPT_NAME"
            exit 1
        fi
        if ! [[ "$TLS_EMAIL" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]]; then
            echo "ERROR: TLS_EMAIL '$TLS_EMAIL' is not a valid email address."
            exit 1
        fi
    fi

    if [ "$TLS_MODE" = "existing" ]; then
        if [ -z "$TLS_CERT_FILE" ] || [ -z "$TLS_KEY_FILE" ]; then
            echo "ERROR: TLS_MODE=existing requires TLS_CERT_FILE and TLS_KEY_FILE"
            echo "Example:"
            echo "  TLS_MODE=existing TLS_CERT_FILE=/etc/ssl/mycert/fullchain.pem TLS_KEY_FILE=/etc/ssl/mycert/privkey.pem ./$SCRIPT_NAME"
            exit 1
        fi
        if [ ! -r "$TLS_CERT_FILE" ]; then
            echo "ERROR: certificate file not found or not readable: $TLS_CERT_FILE"
            exit 1
        fi
        if [ ! -r "$TLS_KEY_FILE" ]; then
            echo "ERROR: private key file not found or not readable: $TLS_KEY_FILE"
            exit 1
        fi
        if ! openssl x509 -in "$TLS_CERT_FILE" -noout >/dev/null 2>&1; then
            echo "ERROR: $TLS_CERT_FILE is not a valid PEM X.509 certificate"
            exit 1
        fi
        if ! openssl pkey -in "$TLS_KEY_FILE" -noout >/dev/null 2>&1; then
            echo "ERROR: $TLS_KEY_FILE is not a valid PEM private key"
            exit 1
        fi
        # Confirm the key actually matches the certificate by comparing public
        # keys (works for both RSA and EC, unlike a modulus-only check).
        local _cert_pub _key_pub
        _cert_pub=$(openssl x509 -in "$TLS_CERT_FILE" -noout -pubkey 2>/dev/null)
        _key_pub=$(openssl pkey -in "$TLS_KEY_FILE" -pubout 2>/dev/null)
        if [ -z "$_cert_pub" ] || [ "$_cert_pub" != "$_key_pub" ]; then
            echo "ERROR: the private key does not match the certificate"
            echo "  cert: $TLS_CERT_FILE"
            echo "  key : $TLS_KEY_FILE"
            exit 1
        fi
        # Non-fatal expiry warning: nginx will still start, but clients will
        # reject an expired certificate.
        if ! openssl x509 -in "$TLS_CERT_FILE" -checkend 0 >/dev/null 2>&1; then
            echo "WARNING: certificate $TLS_CERT_FILE is expired or unreadable dates; proceeding anyway."
        fi
    fi

    if [ -n "$TLS_DOMAIN" ]; then
        # TLS_DOMAIN reaches nginx "server_name", the certbot "-d" argument, the
        # self-signed cert CN, and the /etc/letsencrypt/live/<domain> path.
        # Restrict it to hostname characters so a crafted value cannot inject
        # nginx directives (";", newlines, "{}"), certbot flags (leading "-"),
        # extra subject-DN fields ("/"), or traverse paths.
        if ! [[ "$TLS_DOMAIN" =~ ^[A-Za-z0-9]([A-Za-z0-9.-]{0,253})$ ]]; then
            echo "ERROR: TLS_DOMAIN '$TLS_DOMAIN' is not a valid hostname."
            echo "Use letters, digits, dots and hyphens only, starting with a letter or digit (e.g. caster.example.com)."
            exit 1
        fi
        NGINX_SERVER_NAME="$TLS_DOMAIN"
    fi
}

validate_tcp_port() {
    local port_label="$1"
    local port_value="$2"

    case "$port_value" in
        ''|*[!0-9]*)
            echo "ERROR: $port_label must be a numeric TCP port, got '$port_value'"
            exit 1
            ;;
    esac

    if [ "$port_value" -lt 1 ] || [ "$port_value" -gt 65535 ]; then
        echo "ERROR: $port_label must be between 1 and 65535, got '$port_value'"
        exit 1
    fi
}

validate_install_ports() {
    validate_tcp_port "WEB_PORT" "$INSTALL_WEB_PORT"
    validate_tcp_port "NTRIP_PORT" "$INSTALL_NTRIP_PORT"

    # The application runs as an unprivileged service account and the unit
    # grants no CAP_NET_BIND_SERVICE, so it cannot bind ports below 1024 - the
    # process would die with "PermissionError: [Errno 13]" on startup. Public
    # HTTP/HTTPS is served by nginx on 80/443, which proxies to WEB_PORT.
    for _port_check in "WEB_PORT:$INSTALL_WEB_PORT" "NTRIP_PORT:$INSTALL_NTRIP_PORT"; do
        _port_label="${_port_check%%:*}"
        _port_number="${_port_check##*:}"
        if [ "$_port_number" -lt 1024 ]; then
            echo "ERROR: $_port_label must be 1024 or higher, got '$_port_number'."
            echo "  The caster runs unprivileged and cannot bind privileged ports."
            if [ "$_port_label" = "WEB_PORT" ]; then
                echo "  This is the internal backend port behind nginx - not the public one."
                echo "  nginx already serves 80/443; keep the backend on e.g. 8080 and"
                echo "  enable HTTPS with TLS_MODE instead."
            fi
            exit 1
        fi
    done

    if [ "$INSTALL_WEB_PORT" -eq "$INSTALL_NTRIP_PORT" ]; then
        echo "ERROR: WEB_PORT and NTRIP_PORT must be different"
        exit 1
    fi
}

validate_python_version() {
    local python_version

    if ! command -v python3 >/dev/null 2>&1; then
        return 1
    fi

    if ! python3 - <<'PYTHON_VERSION_CHECK'
import sys
raise SystemExit(0 if sys.version_info >= (3, 11) else 1)
PYTHON_VERSION_CHECK
    then
        python_version=$(python3 -c 'import sys; print(".".join(map(str, sys.version_info[:3])))' 2>/dev/null || echo unknown)
        echo "ERROR: Python 3.11 or newer is required; found Python ${python_version}." >&2
        return 1
    fi

    return 0
}

run_preflight_checks() {
    local free_kb
    local free_mb
    local os_name="unknown"
    local os_id="unknown"

    echo "Running pre-flight checks..."

    if ! command -v apt >/dev/null 2>&1; then
        echo "ERROR: apt is required. This installer targets Debian/Raspberry Pi OS/Ubuntu systems."
        exit 1
    fi

    if ! command -v systemctl >/dev/null 2>&1; then
        echo "ERROR: systemctl is required. This installer expects a systemd-based system."
        exit 1
    fi

    if command -v python3 >/dev/null 2>&1; then
        validate_python_version || exit 1
    else
        echo "Python 3 is not installed yet; the installer will install it and verify Python >= 3.11 afterward."
    fi

    if [ ! -d /run/systemd/system ]; then
        echo "ERROR: systemd does not appear to be PID 1 on this system."
        exit 1
    fi

    free_kb=$(df -Pk / 2>/dev/null | awk 'NR==2 {print $4}')
    case "$free_kb" in
        ''|*[!0-9]*)
            free_kb=0
            ;;
    esac
    free_mb=$((free_kb / 1024))
    if [ "$free_mb" -lt 1024 ]; then
        echo "ERROR: At least 1024 MB free disk space is required on /. Found: ${free_mb} MB"
        exit 1
    fi

    if [ -r /etc/os-release ]; then
        os_name=$(awk -F= '$1=="PRETTY_NAME" {gsub(/^"|"$/, "", $2); print $2}' /etc/os-release)
        os_id=$(awk -F= '$1=="ID" {gsub(/^"|"$/, "", $2); print $2}' /etc/os-release)
    fi

    case "$os_id" in
        debian|raspbian|ubuntu)
            echo "OS check: ${os_name:-$os_id}"
            ;;
        *)
            echo "WARNING: Untested OS '${os_name:-$os_id}'. Supported targets are Debian, Raspberry Pi OS, and Ubuntu."
            ;;
    esac

    for path in /opt /etc /var/log; do
        if [ ! -d "$path" ] || [ ! -w "$path" ]; then
            echo "ERROR: Required writable directory is not available: $path"
            exit 1
        fi
    done

    if [ "$TLS_MODE" = "letsencrypt" ]; then
        if [ "$TLS_DOMAIN" = "_" ] || [ -z "$TLS_DOMAIN" ]; then
            echo "ERROR: Let's Encrypt requires a real TLS_DOMAIN"
            exit 1
        fi
    fi

    echo "Pre-flight checks passed."
}

ensure_service_account() {
    echo "Ensuring dedicated service account..."

    if ! getent group "$SERVICE_GROUP" >/dev/null 2>&1; then
        groupadd --system "$SERVICE_GROUP"
    fi

    if ! id "$SERVICE_USER" >/dev/null 2>&1; then
        useradd \
            --system \
            --gid "$SERVICE_GROUP" \
            --home-dir "$BASE" \
            --shell /usr/sbin/nologin \
            --comment "GNSS Caster service account" \
            "$SERVICE_USER"
    fi

    for supplemental_group in dialout tty bluetooth; do
        if ! getent group "$supplemental_group" >/dev/null 2>&1; then
            groupadd --system "$supplemental_group" 2>/dev/null || true
        fi
        if getent group "$supplemental_group" >/dev/null 2>&1; then
            usermod -a -G "$supplemental_group" "$SERVICE_USER" 2>/dev/null || true
        fi
    done
}

write_privileged_helper() {
    # Privilege-separation core. The application runs as an unprivileged account
    # and must never hold blanket sudo. Instead it may run exactly one root
    # binary - this helper - whose every subcommand strictly validates its
    # arguments (systemd unit name, RFCOMM channel, Bluetooth MAC, backup name)
    # before acting, so a compromised web process cannot escalate beyond the
    # narrow, audited operations defined below. The matching sudoers entry
    # further down whitelists only these subcommands NOPASSWD; nothing else.
    mkdir -p "$BASE"

cat > "$PRIVILEGED_HELPER" << 'EOF'
#!/bin/bash
set -euo pipefail

export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
SERVICE_GROUP="gnss-caster"

die() {
    echo "ERROR: $*" >&2
    exit 1
}

need_root() {
    if [ "${EUID:-$(id -u)}" -ne 0 ]; then
        die "privileged helper must run as root"
    fi
}

validate_unit_name() {
    local unit_name="$1"
    [[ "$unit_name" =~ ^gnss-caster-[a-z0-9-]+\.service$ ]] || die "invalid unit name"
}

validate_channel() {
    local channel="$1"
    [[ "$channel" =~ ^[0-9]+$ ]] || die "invalid RFCOMM channel"
    [ "$channel" -ge 1 ] && [ "$channel" -le 30 ] || die "RFCOMM channel must be 1..30"
}

validate_mac() {
    local mac="$1"
    [[ "$mac" =~ ^([0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}$ ]] || die "invalid Bluetooth MAC"
}

validate_backup_name() {
    local safe_name="$1"
    [ "$(basename -- "$safe_name")" = "$safe_name" ] || die "backup name must not contain paths"
    if [[ "$safe_name" != backup_*.tar.gz ]] && [[ "$safe_name" != backup_*.tar.gz.enc ]]; then
        die "invalid backup name"
    fi
}

backup_interval_to_cron_expression() {
    local interval_seconds="$1"
    local interval_minutes
    local interval_hours
    local interval_days

    [[ "$interval_seconds" =~ ^[0-9]+$ ]] || interval_seconds=86400
    [ "$interval_seconds" -ge 3600 ] || interval_seconds=3600
    [ "$interval_seconds" -le 604800 ] || interval_seconds=604800

    interval_minutes=$(( (interval_seconds + 30) / 60 ))
    [ "$interval_minutes" -ge 60 ] || interval_minutes=60

    if [ "$interval_minutes" -lt 1440 ] && [ $((interval_minutes % 60)) -eq 0 ]; then
        interval_hours=$((interval_minutes / 60))
        [ "$interval_hours" -ge 1 ] || interval_hours=1
        if [ "$interval_hours" -eq 24 ]; then
            printf '0 2 * * *\n'
            return
        fi
        printf '0 */%s * * *\n' "$interval_hours"
        return
    fi

    if [ $((interval_minutes % 1440)) -eq 0 ]; then
        interval_days=$((interval_minutes / 1440))
        [ "$interval_days" -ge 1 ] || interval_days=1
        if [ "$interval_days" -le 28 ]; then
            printf '0 2 */%s * *\n' "$interval_days"
            return
        fi
    fi

    printf '0 2 * * *\n'
}

need_root
action="${1:-}"

# Audit every privileged invocation. Arguments here are non-secret control
# values (unit names, channels, MACs), so logging them aids incident review.
audit_privileged_call() {
    local audit_log="/var/log/gnss-caster/privileged-helper.log"
    local caller_uid="${SUDO_UID:-unknown}"
    local caller_user="${SUDO_USER:-unknown}"
    local ts

    ts=$(date -Is 2>/dev/null || date)
    mkdir -p /var/log/gnss-caster 2>/dev/null || true
    printf '%s uid=%s user=%s action=%s args=%s\n' \
        "$ts" "$caller_uid" "$caller_user" "$action" "$*" \
        >> "$audit_log" 2>/dev/null || true
    chmod 640 "$audit_log" 2>/dev/null || true
}

audit_privileged_call "$@"

case "$action" in
    rfkill-unblock-bluetooth)
        exec rfkill unblock bluetooth
        ;;

    systemctl-is-active)
        unit_name="${2:-}"
        case "$unit_name" in
            bluetooth|gnss-caster|nginx|fail2ban|cron|ssh|sshd)
                exec systemctl is-active --quiet "$unit_name"
                ;;
            *)
                die "unsupported systemctl status unit"
                ;;
        esac
        ;;

    systemctl-start)
        unit_name="${2:-}"
        [ "$unit_name" = "bluetooth" ] || die "only bluetooth can be started by this helper"
        exec systemctl start bluetooth
        ;;

    rfcomm-bind)
        bind_channel="${2:-}"
        mac_address="${3:-}"
        target_channel="${4:-}"
        validate_channel "$bind_channel"
        validate_channel "$target_channel"
        validate_mac "$mac_address"
        exec rfcomm bind "$bind_channel" "$mac_address" "$target_channel"
        ;;

    rfcomm-release)
        release_channel="${2:-}"
        validate_channel "$release_channel"
        exec rfcomm release "$release_channel"
        ;;

    set-system-clock)
        # GNSS-derived time for a host with no RTC and no internet. Strictly
        # validated: this runs as root and the argument comes from a parsed
        # NMEA sentence.
        clock_value="${2:-}"
        case "$clock_value" in
            [0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]\ [0-2][0-9]:[0-5][0-9]:[0-5][0-9]) ;;
            *) die "invalid timestamp" ;;
        esac
        # Stop NTP from fighting us, then set the clock in UTC.
        timedatectl set-ntp false >/dev/null 2>&1 || true
        exec timedatectl set-time "$clock_value"
        ;;

    reboot-host)
        # Deliberately delayed and detached: the caller needs to return so the
        # confirmation can reach the operator before the machine goes down.
        exec systemd-run \
            --unit "gnss-caster-reboot.service" \
            --description "GNSS Caster requested reboot" \
            --on-active=8 \
            --timer-property=AccuracySec=1s \
            systemctl reboot
        ;;

    restart-service)
        # The gentler option: restarting the caster clears most stuck states
        # without losing the host. Detached for the same reason - this command
        # would otherwise kill the process that asked for it.
        exec systemd-run \
            --unit "gnss-caster-restart.service" \
            --description "GNSS Caster requested service restart" \
            --on-active=4 \
            --timer-property=AccuracySec=1s \
            systemctl restart gnss-caster
        ;;

    recover-bluetooth-deep)
        # Preserve pairing keys: removing a device can prevent unattended
        # reconnection. A controller reset is not proof of restored data flow.
        deep_mac="${2:-}"
        [ -n "$deep_mac" ] && validate_mac "$deep_mac"

        systemctl stop bluetooth >/dev/null 2>&1 || true
        rfkill block bluetooth >/dev/null 2>&1 || true
        sleep 2
        rfkill unblock bluetooth >/dev/null 2>&1 || true
        sleep 2
        systemctl start bluetooth >/dev/null 2>&1 || true
        sleep 3
        hciconfig hci0 up >/dev/null 2>&1 || true
        exec hciconfig hci0
        ;;

    recover-bluetooth)
        # The Pi's controller occasionally reaches a state where scanning still
        # works but no classic connection can be made ("Host is down"), and only
        # a reboot clears it. This is a limited recovery attempt; it does not
        # reinitialize every driver/firmware state like a reboot does.
        hciconfig hci0 down >/dev/null 2>&1 || true
        sleep 1
        hciconfig hci0 up >/dev/null 2>&1 || true
        sleep 1
        systemctl restart bluetooth >/dev/null 2>&1 || true
        sleep 2
        hciconfig hci0 up >/dev/null 2>&1 || true
        exec hciconfig hci0
        ;;

    read-rssi)
        # Live signal strength of an *established* link. BlueZ only exposes
        # RSSI over D-Bus while scanning, so a connected receiver otherwise
        # shows "no recent scan". hcitool reads it straight from the HCI
        # connection, which needs privileges - hence this subcommand.
        rssi_mac="${2:-}"
        validate_mac "$rssi_mac"
        exec hcitool rssi "$rssi_mac"
        ;;

    systemd-job)
        job_type="${2:-}"
        unit_name="${3:-}"
        validate_unit_name "$unit_name"

        case "$job_type" in
            backup)
                exec systemd-run \
                    --unit "$unit_name" \
                    --description "GNSS Caster backup job" \
                    --property=Type=oneshot \
                    --property=RemainAfterExit=yes \
                    --property=WorkingDirectory=/opt/gnss-caster \
                    /opt/gnss-caster/backup.sh
                ;;
            restore)
                backup_name="${4:-}"
                validate_backup_name "$backup_name"
                # Optional passphrase file for an encrypted archive. A path is
                # passed rather than the secret itself: command lines are world
                # readable through /proc, a 0600 file is not. restore.sh deletes
                # it after reading.
                passphrase_file="${5:-}"
                if [ -n "$passphrase_file" ]; then
                    case "$passphrase_file" in
                        /run/gnss-caster/restore-*.key) ;;
                        *) die "unexpected passphrase file path" ;;
                    esac
                    [[ "$passphrase_file" =~ ^/run/gnss-caster/restore-[0-9a-f]{16}\.key$ ]] || die "invalid passphrase filename"
                    [ -f "$passphrase_file" ] && [ ! -L "$passphrase_file" ] || die "invalid passphrase file"
                    exec systemd-run \
                        --unit "$unit_name" \
                        --description "GNSS Caster restore job" \
                        --property=Type=oneshot \
                        --property=RemainAfterExit=yes \
                        --property=WorkingDirectory=/opt/gnss-caster \
                        /opt/gnss-caster/restore.sh "$backup_name" "$passphrase_file"
                fi
                exec systemd-run \
                    --unit "$unit_name" \
                    --description "GNSS Caster restore job" \
                    --property=Type=oneshot \
                    --property=RemainAfterExit=yes \
                    --property=WorkingDirectory=/opt/gnss-caster \
                    /opt/gnss-caster/restore.sh "$backup_name"
                ;;
            *)
                die "unsupported systemd job type"
                ;;
        esac
        ;;

    write-logrotate)
        rotation_days="${2:-30}"
        [[ "$rotation_days" =~ ^[0-9]+$ ]] || die "invalid log retention"
        [ "$rotation_days" -ge 1 ] && [ "$rotation_days" -le 3650 ] || die "log retention must be 1..3650"
        cat > /etc/logrotate.d/gnss-caster << LOGROTATE
/var/log/gnss-caster/*.log {
    daily
    missingok
    rotate $rotation_days
    compress
    delaycompress
    notifempty
    create 660 root $SERVICE_GROUP
    sharedscripts
    postrotate
        systemctl reload gnss-caster > /dev/null 2>&1 || true
    endscript
}
LOGROTATE
        chmod 644 /etc/logrotate.d/gnss-caster
        ;;

    write-backup-cron)
        enabled="${2:-0}"
        interval_seconds="${3:-86400}"
        cron_path="/etc/cron.d/gnss-caster-backup"
        mkdir -p /etc/cron.d
        case "$enabled" in
            1|true|yes|on)
                cron_expression=$(backup_interval_to_cron_expression "$interval_seconds")
                cat > "$cron_path" << CRON
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
$cron_expression root /opt/gnss-caster/backup.sh >> /var/log/gnss-caster/backup-cron.log 2>&1
CRON
                chmod 644 "$cron_path"
                printf '%s\n' "$cron_expression"
                ;;
            0|false|no|off|"")
                rm -f "$cron_path"
                ;;
            *)
                die "invalid backup cron enabled flag"
                ;;
        esac
        ;;

    certificate-info)
        cert_path="${2:-}"
        [ -n "$cert_path" ] || die "certificate path is required"

        real_cert_path=$(readlink -f -- "$cert_path" 2>/dev/null || true)
        [ -n "$real_cert_path" ] || die "certificate path not found"

        case "$real_cert_path" in
            /etc/letsencrypt/archive/*/fullchain*.pem|/etc/letsencrypt/live/*/fullchain.pem|/etc/ssl/certs/gnss-caster.crt)
                ;;
            *)
                die "unsupported certificate path"
                ;;
        esac

        [ -f "$real_cert_path" ] || die "certificate file not found"

        python3 - "$real_cert_path" << 'PYTHON_CERT_INFO'
import json
import os
import ssl
import sys
import tempfile

cert_path = sys.argv[1]
temp_cert_path = ''

try:
    with open(cert_path, 'r', encoding='utf-8', errors='ignore') as cert_file:
        pem_text = cert_file.read()

    begin_marker = '-----BEGIN CERTIFICATE-----'
    end_marker = '-----END CERTIFICATE-----'
    decode_path = cert_path

    if pem_text.count(begin_marker) > 1 and end_marker in pem_text:
        first_certificate = pem_text.split(end_marker, 1)[0] + end_marker + '\n'
        fd, temp_cert_path = tempfile.mkstemp(prefix='gnss-caster-cert-', suffix='.pem')
        with os.fdopen(fd, 'w', encoding='utf-8') as temp_cert_file:
            temp_cert_file.write(first_certificate)
        decode_path = temp_cert_path

    print(json.dumps(ssl._ssl._test_decode_cert(decode_path), ensure_ascii=True, sort_keys=True))
finally:
    if temp_cert_path:
        try:
            os.unlink(temp_cert_path)
        except Exception:
            pass
PYTHON_CERT_INFO
        ;;

    certbot-renew)
        force="${2:-0}"
        certbot_args=(certbot renew --non-interactive)
        case "$force" in
            1|true|yes|on)
                certbot_args+=(--force-renewal)
                ;;
            0|false|no|off|"")
                ;;
            *)
                die "invalid certbot force flag"
                ;;
        esac
        "${certbot_args[@]}"
        systemctl reload nginx
        ;;

    power)
        power_action="${2:-}"
        unit_name="${3:-}"
        delay_seconds="${4:-5}"
        validate_unit_name "$unit_name"
        [[ "$delay_seconds" =~ ^[0-9]+$ ]] || die "invalid delay"
        [ "$delay_seconds" -ge 1 ] && [ "$delay_seconds" -le 60 ] || die "delay must be 1..60 seconds"

        case "$power_action" in
            reboot)
                systemctl_action=reboot
                ;;
            shutdown)
                systemctl_action=poweroff
                ;;
            *)
                die "unsupported power action"
                ;;
        esac

        exec systemd-run \
            --unit "$unit_name" \
            --description "GNSS Caster host $power_action" \
            --on-active "${delay_seconds}s" \
            --property=Type=oneshot \
            systemctl "$systemctl_action"
        ;;

    *)
        die "unsupported helper action"
        ;;
esac
EOF

    chown root:root "$PRIVILEGED_HELPER"
    chmod 750 "$PRIVILEGED_HELPER"

# Least-privilege sudoers. Two forms are emitted depending on which sudo
# implementation is active:
#
#   * classic sudo - every helper subcommand is listed individually, with "*"
#     standing in for the variable arguments.
#   * sudo-rs - the default on Ubuntu 26.04 (selected over classic sudo by
#     update-alternatives). It restricts wildcards in command arguments, so the
#     rule grants the helper path itself instead. Security is unchanged in
#     practice: the helper is the real whitelist - it rejects unknown
#     subcommands and validates every argument (unit name, RFCOMM channel,
#     Bluetooth MAC, backup name) before acting.
#
# Either way the file is root:root 0440 and validated with visudo, so a
# malformed entry can never lock out sudo system-wide.
    if sudo --version 2>/dev/null | head -n 1 | grep -qi 'sudo-rs'; then
        echo "Detected sudo-rs; writing a wildcard-free sudoers rule."
        _write_sudoers_portable
    else
        _write_sudoers_restrictive
    fi

    chown root:root "$SUDOERS_FILE"
    chmod 440 "$SUDOERS_FILE"

    if ! _sudoers_file_is_valid; then
        # Belt and braces: if the stricter syntax is rejected by the installed
        # sudo implementation, fall back to the portable rule.
        echo "sudoers validation failed; falling back to the wildcard-free rule."
        _write_sudoers_portable
        chown root:root "$SUDOERS_FILE"
        chmod 440 "$SUDOERS_FILE"
        if ! _sudoers_file_is_valid; then
            echo "ERROR: generated sudoers file is invalid; removing it."
            rm -f "$SUDOERS_FILE"
            exit 1
        fi
    fi
}

_write_sudoers_restrictive() {
cat > "$SUDOERS_FILE" << EOF
Defaults:$SERVICE_USER !requiretty
$SERVICE_USER ALL=(root) NOPASSWD: \
    $PRIVILEGED_HELPER rfkill-unblock-bluetooth, \
    $PRIVILEGED_HELPER systemctl-is-active *, \
    $PRIVILEGED_HELPER systemctl-start bluetooth, \
    $PRIVILEGED_HELPER rfcomm-bind *, \
    $PRIVILEGED_HELPER rfcomm-release *, \
    $PRIVILEGED_HELPER read-rssi *, \
    $PRIVILEGED_HELPER recover-bluetooth, \
    $PRIVILEGED_HELPER recover-bluetooth-deep *, \
    $PRIVILEGED_HELPER reboot-host, \
    $PRIVILEGED_HELPER restart-service, \
    $PRIVILEGED_HELPER set-system-clock *, \
    $PRIVILEGED_HELPER systemd-job *, \
    $PRIVILEGED_HELPER write-logrotate *, \
    $PRIVILEGED_HELPER write-backup-cron *, \
    $PRIVILEGED_HELPER certificate-info *, \
    $PRIVILEGED_HELPER certbot-renew *, \
    $PRIVILEGED_HELPER power *
EOF
}

_write_sudoers_portable() {
cat > "$SUDOERS_FILE" << EOF
$SERVICE_USER ALL=(root) NOPASSWD: $PRIVILEGED_HELPER
EOF
}

_sudoers_file_is_valid() {
    command -v visudo >/dev/null 2>&1 || return 0
    visudo -cf "$SUDOERS_FILE" >/dev/null 2>&1
}

write_polkit_bluetooth_rule() {
    # Let the service account manage BlueZ over D-Bus without being root. The
    # rule is scoped twice: by subject (only the service user) and by action-id
    # prefix (only the BlueZ adapter/device/agent/profile interfaces), so it
    # cannot be used to touch any unrelated system policy.
    if [ ! -d /etc/polkit-1/rules.d ]; then
        echo "Polkit rules directory not found; skipping Bluetooth D-Bus policy rule."
        return 0
    fi

cat > "$POLKIT_RULE" << EOF
// Allow the GNSS Caster service account to manage BlueZ over D-Bus.
polkit.addRule(function(action, subject) {
    if (subject.user == "$SERVICE_USER") {
        var allowedPrefixes = [
            "org.bluez.adapter.",
            "org.bluez.device1.",
            "org.bluez.agent-manager.",
            "org.bluez.profile-manager."
        ];

        for (var i = 0; i < allowedPrefixes.length; i++) {
            if (action.id.indexOf(allowedPrefixes[i]) === 0) {
                return polkit.Result.YES;
            }
        }
    }
});
EOF
    chown root:root "$POLKIT_RULE"
    chmod 644 "$POLKIT_RULE"
}

get_nginx_backend_url() {
    local backend_port
    backend_port=$(get_config_value "web_port" "8080")
    printf 'http://127.0.0.1:%s\n' "$backend_port"
}

write_nginx_security_config() {
cat > "$NGINX_SECURITY_CONF" << 'EOF'
# GNSS Caster Nginx Security Controls
limit_req_zone $binary_remote_addr zone=gnss_login:10m rate=20r/m;
limit_req_zone $binary_remote_addr zone=gnss_api:10m   rate=120r/m;
limit_conn_zone $binary_remote_addr zone=gnss_conn_per_ip:10m;
limit_req_status 429;
EOF
}

write_nginx_http_config() {
    local backend_url
    backend_url=$(get_nginx_backend_url)
cat > "$NGINX_AVAILABLE" << EOF
# GNSS Caster Nginx Configuration (HTTP)
server {
    # default_server so requests by IP address (no matching server_name) reach
    # the caster instead of falling through to another vhost.
    listen 80 default_server;
    server_name $NGINX_SERVER_NAME;
    server_tokens off;
    client_max_body_size 2m;
    limit_conn gnss_conn_per_ip 30;

    location = /login {
        limit_req zone=gnss_login burst=10 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    # Throttle 2FA code submission to blunt TOTP brute-force (shares the login
    # rate-limit bucket per client IP; not covered by the exact "= /login" match).
    location = /login/2fa {
        limit_req zone=gnss_login burst=5 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    location / {
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;

        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
    }

    location /api/ {
        limit_req zone=gnss_api burst=30 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    location /health {
        access_log off;
        proxy_pass $backend_url/api/health;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
    }
}
EOF
}

write_nginx_letsencrypt_bootstrap_config() {
    local backend_url
    backend_url=$(get_nginx_backend_url)
cat > "$NGINX_AVAILABLE" << EOF
# GNSS Caster Nginx Configuration (Let's Encrypt bootstrap)
server {
    # default_server so requests by IP address (no matching server_name) reach
    # the caster instead of falling through to another vhost.
    listen 80 default_server;
    server_name $NGINX_SERVER_NAME;
    server_tokens off;
    client_max_body_size 2m;
    limit_conn gnss_conn_per_ip 30;

    location /.well-known/acme-challenge/ {
        root $LE_WEBROOT;
    }

    location = /login {
        limit_req zone=gnss_login burst=10 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    # Throttle 2FA code submission to blunt TOTP brute-force (shares the login
    # rate-limit bucket per client IP; not covered by the exact "= /login" match).
    location = /login/2fa {
        limit_req zone=gnss_login burst=5 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    location / {
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;

        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
    }

    location /api/ {
        limit_req zone=gnss_api burst=30 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    location /health {
        access_log off;
        proxy_pass $backend_url/api/health;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
    }
}
EOF
}

nginx_https_listen_directives() {
    # nginx >= 1.25 deprecates "listen ... http2" in favour of a separate
    # "http2 on;" directive; older builds do not know "http2" as a directive at
    # all and refuse to start. Pick the form the installed nginx understands.
    local version_string major minor
    version_string=$(nginx -v 2>&1 | sed -n 's|.*nginx/\([0-9]*\.[0-9]*\).*|\1|p')
    major="${version_string%%.*}"
    minor="${version_string##*.}"

    if [ -n "$major" ] && [ -n "$minor" ] && { [ "$major" -gt 1 ] || { [ "$major" -eq 1 ] && [ "$minor" -ge 25 ]; }; }; then
        printf '    listen 443 ssl default_server;\n    http2 on;'
    else
        printf '    listen 443 ssl http2 default_server;'
    fi
}

write_nginx_https_config() {
    local backend_url
    backend_url=$(get_nginx_backend_url)
    local https_listen
    https_listen=$(nginx_https_listen_directives)
cat > "$NGINX_AVAILABLE" << EOF
# GNSS Caster Nginx Configuration (HTTPS)
server {
    # default_server so requests by IP address (no matching server_name) reach
    # the caster instead of falling through to another vhost.
    listen 80 default_server;
    server_name $NGINX_SERVER_NAME;
    server_tokens off;

    location /.well-known/acme-challenge/ {
        root $LE_WEBROOT;
    }

    location / {
        return 301 https://\$host\$request_uri;
    }
}

server {
$https_listen
    server_name $NGINX_SERVER_NAME;
    server_tokens off;
    client_max_body_size 2m;
    limit_conn gnss_conn_per_ip 30;

    ssl_certificate $SSL_CERT_PATH;
    ssl_certificate_key $SSL_KEY_PATH;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    ssl_prefer_server_ciphers on;

    location = /login {
        limit_req zone=gnss_login burst=10 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    # Throttle 2FA code submission to blunt TOTP brute-force (shares the login
    # rate-limit bucket per client IP; not covered by the exact "= /login" match).
    location = /login/2fa {
        limit_req zone=gnss_login burst=5 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    location / {
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;

        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
    }

    location /api/ {
        limit_req zone=gnss_api burst=30 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    location /health {
        access_log off;
        proxy_pass $backend_url/api/health;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
    }
}
EOF
}

nginx_site_contains_server_name() {
    local site_file="$1"
    local desired_name="$2"

    awk -v desired="$desired_name" '
        /^[[:space:]]*server_name[[:space:]]+/ {
            for (i = 2; i <= NF; i++) {
                gsub(/;/, "", $i)
                if ($i == desired) {
                    found = 1
                }
            }
        }
        END { exit found ? 0 : 1 }
    ' "$site_file" 2>/dev/null
}

check_nginx_config_conflicts() {
    local desired_name="$NGINX_SERVER_NAME"
    local site_file
    local site_target
    local gnss_target
    local conflict_found=0

    if [ -z "$desired_name" ] || [ "$desired_name" = "_" ]; then
        return 0
    fi

    gnss_target=$(readlink -f "$NGINX_AVAILABLE" 2>/dev/null || printf '%s' "$NGINX_AVAILABLE")

    for site_file in /etc/nginx/sites-enabled/* /etc/nginx/conf.d/*.conf; do
        [ -e "$site_file" ] || [ -L "$site_file" ] || continue

        site_target=$(readlink -f "$site_file" 2>/dev/null || printf '%s' "$site_file")
        if [ "$site_target" = "$gnss_target" ] || [ "$site_file" = "$NGINX_ENABLED" ] || [ "$site_file" = "$NGINX_SECURITY_CONF" ]; then
            continue
        fi

        if nginx_site_contains_server_name "$site_file" "$desired_name"; then
            echo "ERROR: Nginx server_name '$desired_name' is already configured in $site_file"
            conflict_found=1
        fi
    done

    if [ "$conflict_found" -ne 0 ]; then
        echo "Choose a different TLS_DOMAIN/server_name or disable the conflicting nginx site before installing."
        exit 1
    fi
}

check_nginx_public_port_conflicts() {
    local port
    local listeners
    local non_nginx_listeners

    if ! command -v ss >/dev/null 2>&1; then
        return 0
    fi

    for port in 80 443; do
        if [ "$port" = "443" ] && ! grep -Eq 'listen[[:space:]]+443[[:space:]]+ssl' "$NGINX_AVAILABLE" 2>/dev/null; then
            continue
        fi

        listeners=$(ss -ltnp 2>/dev/null | grep -E "[:.]${port}[[:space:]]" || true)
        [ -n "$listeners" ] || continue

        non_nginx_listeners=$(printf '%s\n' "$listeners" | grep -vi 'nginx' || true)
        if [ -n "$non_nginx_listeners" ]; then
            echo "ERROR: Public HTTP(S) port $port is already held by a non-nginx process:"
            printf '%s\n' "$non_nginx_listeners" | sed 's/^/  /'
            echo "Stop the conflicting service or move GNSS Caster behind the existing reverse proxy."
            exit 1
        fi
    done
}

disable_default_nginx_site() {
    # Debian/Ubuntu ship /etc/nginx/sites-enabled/default listening on port 80
    # as "default_server". A request by IP address (no matching server_name)
    # therefore lands on the nginx welcome page instead of the caster - or on
    # its HTTP->HTTPS redirect. Disable it, remembering that we did so, so the
    # uninstaller can put it back exactly as it was.
    local default_site="/etc/nginx/sites-enabled/default"

    [ -e "$default_site" ] || return 0

    echo "Disabling the default nginx site (it would shadow GNSS Caster on port 80)."
    if [ -L "$default_site" ]; then
        rm -f "$default_site"
        touch "$BASE/.nginx-default-was-symlink" 2>/dev/null || true
    else
        mv -f "$default_site" "$default_site.gnss-caster.disabled"
        touch "$BASE/.nginx-default-was-file" 2>/dev/null || true
    fi
}

apply_nginx_config() {
    check_nginx_config_conflicts
    check_nginx_public_port_conflicts
    write_nginx_security_config
    strip_crlf "$NGINX_AVAILABLE"
    strip_crlf "$NGINX_SECURITY_CONF"
    ensure_backup_upload_nginx_location
    ln -sf "$NGINX_AVAILABLE" "$NGINX_ENABLED" 2>/dev/null || true
    disable_default_nginx_site
    nginx -t
    systemctl reload nginx || systemctl restart nginx
}

ensure_backup_upload_nginx_location() {
    python3 - "$NGINX_AVAILABLE" << 'PY_UPLOAD_NGINX'
import re
import sys
from pathlib import Path
path = Path(sys.argv[1])
source = path.read_text()
if 'location = /api/system/backups/upload' not in source:
    pattern = r'(?m)^([ \t]*)location /api/\s*\{([^{}]*)\}'
    def add_upload(match):
        indent, body = match.groups()
        if 'proxy_pass ' not in body:
            raise SystemExit('API nginx location has no upstream')
        upload = (indent + 'location = /api/system/backups/upload {\n' +
                  indent + '    client_max_body_size 129m;\n' +
                  indent + '    client_body_timeout 120s;\n' +
                  body + '\n' + indent + '}\n\n')
        return upload + match.group(0)
    source, count = re.subn(pattern, add_upload, source)
    if not count:
        raise SystemExit('Cannot configure backup upload: nginx API location missing')
    path.write_text(source)
PY_UPLOAD_NGINX
}

setup_selfsigned_tls() {
    # Generate a 4096-bit self-signed certificate for HTTPS with no external CA.
    # Intended for LAN or closed deployments (browsers will warn about trust).
    # The private key is written mode 0600; TLS_SELF_SIGNED_DAYS sets validity.
    mkdir -p /etc/ssl/private /etc/ssl/certs "$LE_WEBROOT"

    local cert_cn
    cert_cn="${TLS_DOMAIN:-$(hostname -f 2>/dev/null || hostname || echo gnss-caster.local)}"

    # Use only O= and CN= to avoid hardcoded country/state/city placeholders
    # that are meaningless or confusing for non-US deployments.
    openssl req -x509 -nodes -days "$TLS_SELF_SIGNED_DAYS" -newkey rsa:4096 \
        -keyout "$SELF_SIGNED_KEY" \
        -out "$SELF_SIGNED_CERT" \
        -subj "/O=GNSS Caster/CN=$cert_cn" 2>/dev/null

    chmod 600 "$SELF_SIGNED_KEY" 2>/dev/null || true
    chmod 644 "$SELF_SIGNED_CERT" 2>/dev/null || true

    SSL_CERT_PATH="$SELF_SIGNED_CERT"
    SSL_KEY_PATH="$SELF_SIGNED_KEY"
}

setup_existing_tls() {
    # Use a certificate the operator already has (their own CA, a wildcard, a
    # corporate PKI, or an externally-managed ACME cert). Files are validated in
    # validate_tls_config; nginx is pointed at the operator's canonical paths
    # rather than copies, so certificate renewals they perform are picked up on
    # the next "systemctl reload nginx" with no reinstall.
    if [ ! -r "$TLS_CERT_FILE" ] || [ ! -r "$TLS_KEY_FILE" ]; then
        echo "ERROR: certificate or key became unreadable: $TLS_CERT_FILE / $TLS_KEY_FILE"
        exit 1
    fi

    SSL_CERT_PATH="$TLS_CERT_FILE"
    SSL_KEY_PATH="$TLS_KEY_FILE"
    echo "Using existing certificate: $SSL_CERT_PATH"
}

setup_letsencrypt_tls() {
    # Obtain a trusted certificate from Let's Encrypt via the webroot (HTTP-01)
    # challenge: a temporary nginx config serves the challenge files under
    # LE_WEBROOT, certbot issues the cert for TLS_DOMAIN, and a cron job plus
    # certbot.timer renew it automatically (reloading nginx on deploy). Requires
    # TLS_DOMAIN to resolve publicly to this host and TLS_EMAIL for the account.
    mkdir -p "$LE_WEBROOT"
    chown -R www-data:www-data "$LE_WEBROOT" 2>/dev/null || true

    write_nginx_letsencrypt_bootstrap_config
    apply_nginx_config

    certbot certonly \
        --webroot -w "$LE_WEBROOT" \
        --agree-tos \
        --non-interactive \
        --email "$TLS_EMAIL" \
        --keep-until-expiring \
        -d "$TLS_DOMAIN"

    SSL_CERT_PATH="/etc/letsencrypt/live/$TLS_DOMAIN/fullchain.pem"
    SSL_KEY_PATH="/etc/letsencrypt/live/$TLS_DOMAIN/privkey.pem"

    if [ ! -f "$SSL_CERT_PATH" ] || [ ! -f "$SSL_KEY_PATH" ]; then
        echo "ERROR: Let's Encrypt certificate files not found in /etc/letsencrypt/live/$TLS_DOMAIN"
        exit 1
    fi

    cat > /etc/cron.d/gnss-caster-cert-renew << EOF
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
17 3 * * * root certbot renew --quiet --deploy-hook "systemctl reload nginx"
EOF
    chmod 644 /etc/cron.d/gnss-caster-cert-renew
    systemctl enable certbot.timer --now >/dev/null 2>&1 || true
}

remove_gnss_cron_jobs() {
    rm -f "$MAINTENANCE_CRON" "$BACKUP_CRON"

    if ! command -v crontab >/dev/null 2>&1; then
        return
    fi

    local tmp_cron
    tmp_cron=$(mktemp)

    crontab -l 2>/dev/null | \
        grep -v '/opt/gnss-caster/monitor.sh' | \
        grep -v '/opt/gnss-caster/watchdog.sh' | \
        grep -v '/opt/gnss-caster/backup.sh' | \
        grep -v '/opt/gnss-caster/update.sh' > "$tmp_cron" || true

    if [ -s "$tmp_cron" ]; then
        crontab "$tmp_cron" || true
    else
        crontab -r 2>/dev/null || true
    fi

    rm -f "$tmp_cron"
}

write_ufw_application_profile() {
    mkdir -p /etc/ufw/applications.d

cat > "$UFW_APP_PROFILE" << EOF
[GNSS Caster Web]
title=GNSS Caster Web Interface
description=GNSS Caster web UI via nginx reverse proxy
ports=80,443/tcp

[GNSS Caster NTRIP]
title=GNSS Caster NTRIP Service
description=GNSS Caster rover correction stream service
ports=${INSTALL_NTRIP_PORT}/tcp

[GNSS Caster Full]
title=GNSS Caster Full Service
description=GNSS Caster web UI and NTRIP service
ports=80,443,${INSTALL_NTRIP_PORT}/tcp
EOF

    chmod 644 "$UFW_APP_PROFILE" 2>/dev/null || true

    if command -v ufw >/dev/null 2>&1; then
        ufw app update "GNSS Caster Web" >/dev/null 2>&1 || true
        ufw app update "GNSS Caster NTRIP" >/dev/null 2>&1 || true
        ufw app update "GNSS Caster Full" >/dev/null 2>&1 || true

        # The web backend (Waitress) must only be reachable through nginx.
        # When the firewall is active, explicitly deny external access to the
        # backend port so it cannot be hit directly even if it ever binds wider
        # than 127.0.0.1. This is a no-op when ufw is inactive.
        if ufw status 2>/dev/null | grep -qi '^Status: active'; then
            ufw deny "${INSTALL_WEB_PORT}/tcp" >/dev/null 2>&1 || true
            echo "Firewall: denied external access to web backend port ${INSTALL_WEB_PORT}/tcp (use nginx)."
        else
            echo "Firewall inactive: skipping deny rule for web backend port ${INSTALL_WEB_PORT}/tcp."
            echo "If you enable ufw later, run: ufw deny ${INSTALL_WEB_PORT}/tcp"
        fi
    fi
}

setup_fail2ban() {
    local fail2ban_jail_enabled="false"

    if [ "$ENABLE_FAIL2BAN" = "1" ]; then
        fail2ban_jail_enabled="true"
    fi

    mkdir -p /etc/fail2ban/filter.d /etc/fail2ban/jail.d

cat > "$FAIL2BAN_FILTER" << 'EOF'
[Definition]
failregex = ^.*Failed login attempt for user .* from <HOST>.*$
ignoreregex =
EOF

cat > "$FAIL2BAN_JAIL" << EOF
[gnss-caster-auth]
enabled = $fail2ban_jail_enabled
filter = gnss-caster-auth
logpath = /var/log/gnss-caster/app.log
backend = auto
findtime = 10m
bantime = 1h
maxretry = 8
port = http,https
EOF

    chmod 644 "$FAIL2BAN_FILTER" "$FAIL2BAN_JAIL" 2>/dev/null || true

    if [ "$ENABLE_FAIL2BAN" = "1" ]; then
        systemctl enable fail2ban --now >/dev/null 2>&1 || true
        systemctl restart fail2ban >/dev/null 2>&1 || true
        echo "Fail2ban enabled with GNSS Caster auth jail."
        return
    fi

    if [ "$FAIL2BAN_WAS_ACTIVE" -eq 1 ]; then
        fail2ban-client reload >/dev/null 2>&1 || systemctl restart fail2ban >/dev/null 2>&1 || true
        echo "Fail2ban was already active; GNSS Caster auth jail is disabled by default and configuration was reloaded."
        echo "If SSH drops persist, review existing fail2ban SSH jails with: fail2ban-client status"
        return
    fi

    if [ "$FAIL2BAN_DISABLED_BY_INSTALLER" -eq 1 ]; then
        echo "Fail2ban service was left unchanged; GNSS Caster jail is disabled because GNSS_CASTER_ENABLE_FAIL2BAN is not set."
    elif [ "$FAIL2BAN_WAS_PRESENT" -eq 1 ]; then
        echo "Fail2ban was present but inactive; GNSS Caster auth jail is disabled and service was left inactive."
    else
        echo "Fail2ban configuration installed with GNSS Caster auth jail disabled; package/service was not enabled."
    fi
    echo "Set GNSS_CASTER_ENABLE_FAIL2BAN=1 before install to enable fail2ban hardening."
}

get_config_value() {
    local config_key="$1"
    local default_value="$2"
    local config_file="$INST/config.yaml"
    local config_value=""

    if [ -f "$config_file" ]; then
        config_value=$(awk -F': *' -v lookup_key="$config_key" '
            $0 ~ "^[[:space:]]*" lookup_key ":[[:space:]]*" {
                value = $2
                sub(/[[:space:]]+#.*$/, "", value)
                gsub(/[[:space:]]+$/, "", value)
                print value
                exit
            }
        ' "$config_file" 2>/dev/null)
    fi

    if [ -n "$config_value" ]; then
        printf '%s\n' "$config_value"
    else
        printf '%s\n' "$default_value"
    fi
}

get_system_setting_from_db() {
    local setting_key="$1"
    local default_value="$2"
    local db_file="$INST/db.sqlite"
    local setting_value=""

    # Whitelist: only allow known safe keys to prevent SQL injection.
    case "$setting_key" in
        ntrip_enabled|bluetooth_enabled|bluetooth_discoverable|\
        auto_backup|backup_interval|log_retention|data_retention|\
        max_connections|watchdog_enabled|auto_update_enabled)
            ;;
        *)
            echo "ERROR: get_system_setting_from_db: unknown key '$setting_key'" >&2
            printf '%s\n' "$default_value"
            return 0
            ;;
    esac

    if [ -f "$db_file" ] && command -v sqlite3 >/dev/null 2>&1; then
        setting_value=$(sqlite3 "$db_file" \
            "SELECT value FROM system_setting WHERE key='$setting_key' LIMIT 1;" \
            2>/dev/null || true)
    fi

    if [ -n "$setting_value" ]; then
        printf '%s\n' "$setting_value"
    else
        printf '%s\n' "$default_value"
    fi
}

backup_interval_to_cron_expression() {
    local interval_seconds="$1"
    local interval_minutes
    local interval_hours
    local interval_days

    case "$interval_seconds" in
        ''|*[!0-9]*)
            interval_seconds=86400
            ;;
    esac

    if [ "$interval_seconds" -lt 3600 ]; then
        interval_seconds=3600
    fi

    interval_minutes=$(( (interval_seconds + 30) / 60 ))
    if [ "$interval_minutes" -lt 60 ]; then
        interval_minutes=60
    fi

    if [ "$interval_minutes" -lt 60 ]; then
        printf '*/%s * * * *\n' "$interval_minutes"
        return
    fi

    if [ "$interval_minutes" -lt 1440 ] && [ $((interval_minutes % 60)) -eq 0 ]; then
        interval_hours=$((interval_minutes / 60))
        if [ "$interval_hours" -lt 1 ]; then
            interval_hours=1
        fi
        if [ "$interval_hours" -eq 24 ]; then
            printf '0 2 * * *\n'
            return
        fi
        printf '0 */%s * * *\n' "$interval_hours"
        return
    fi

    if [ $((interval_minutes % 1440)) -eq 0 ]; then
        interval_days=$((interval_minutes / 1440))
        if [ "$interval_days" -lt 1 ]; then
            interval_days=1
        fi
        if [ "$interval_days" -le 28 ]; then
            printf '0 2 */%s * *\n' "$interval_days"
            return
        fi
    fi

    printf '0 2 * * *\n'
}

migrate_bootstrap_admin_password_location() {
    local config_file="$INST/config.yaml"
    local python_config_file="$INST/config.py"
    local tmp_config

    mkdir -p "$INST"

    if [ -f "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" ] && [ ! -f "$BOOTSTRAP_ADMIN_PASSWORD_FILE" ]; then
        echo "Migrating bootstrap credentials to $BOOTSTRAP_ADMIN_PASSWORD_FILE"
        cp -a "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" "$BOOTSTRAP_ADMIN_PASSWORD_FILE" 2>/dev/null || \
            cp "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" "$BOOTSTRAP_ADMIN_PASSWORD_FILE"
    fi

    if [ -f "$config_file" ]; then
        if grep -Eq '^[[:space:]]*bootstrap_admin_password_file:' "$config_file"; then
            sed -i "s|^[[:space:]]*bootstrap_admin_password_file:.*|  bootstrap_admin_password_file: $BOOTSTRAP_ADMIN_PASSWORD_FILE|" "$config_file"
        elif grep -Eq '^security:[[:space:]]*$' "$config_file"; then
            tmp_config=$(mktemp)
            awk -v bootstrap_path="$BOOTSTRAP_ADMIN_PASSWORD_FILE" '
                /^security:[[:space:]]*$/ {
                    print
                    print "  bootstrap_admin_password_file: " bootstrap_path
                    next
                }
                { print }
            ' "$config_file" > "$tmp_config"
            cat "$tmp_config" > "$config_file"
            rm -f "$tmp_config"
        fi
    fi

    if [ -f "$python_config_file" ]; then
        sed -i "s|/etc/gnss-caster/initial-admin-password|$BOOTSTRAP_ADMIN_PASSWORD_FILE|g" "$python_config_file"
    fi

    if [ -f "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" ] && [ -f "$BOOTSTRAP_ADMIN_PASSWORD_FILE" ]; then
        rm -f "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" 2>/dev/null || true
        rmdir /etc/gnss-caster 2>/dev/null || true
    fi
}

set_runtime_permissions() {
    echo "Setting permissions..."

    migrate_bootstrap_admin_password_location

    chown root:"$SERVICE_GROUP" "$BASE"
    chmod 755 "$BASE"

    chown -R root:root "$APP" "$VENV" 2>/dev/null || true
    find "$APP" -type d -exec chmod 755 {} + 2>/dev/null || true
    find "$APP" -type f -exec chmod 644 {} + 2>/dev/null || true
    find "$VENV" -type d -exec chmod 755 {} + 2>/dev/null || true
    find "$VENV" -type f -exec chmod u+rw,go+r {} + 2>/dev/null || true
    find "$VENV/bin" -type f -exec chmod u+rw,go+rx {} + 2>/dev/null || true

    chmod 755 \
        "$BASE/backup.sh" \
        "$BASE/restore.sh" \
        "$BASE/monitor.sh" \
        "$BASE/watchdog.sh" \
        "$BASE/update.sh" \
        "$BASE/diagnose.sh" \
        "$BASE/repair.sh" \
        "$BASE/status.sh" 2>/dev/null || true
    chown root:root "$PRIVILEGED_HELPER" 2>/dev/null || true
    chmod 750 "$PRIVILEGED_HELPER" 2>/dev/null || true
    chmod 700 "$BASE/gnss-caster-installer.sh" 2>/dev/null || true
    chmod 644 \
        "$BASE/main.py" \
        "$BASE/requirements.txt" 2>/dev/null || true

    chown -R root:"$SERVICE_GROUP" "$INST" 2>/dev/null || true
    find "$INST" -type d -exec chmod 770 {} + 2>/dev/null || true
    chmod 640 "$INST/config.yaml" "$INST/config.py" 2>/dev/null || true
    chmod 660 "$INST/db.sqlite" "$INST/db.sqlite-wal" "$INST/db.sqlite-shm" 2>/dev/null || true
    chmod 600 "$INSTALL_REPORT" 2>/dev/null || true
    chown -R root:"$SERVICE_GROUP" "$BACKUP_DIR" 2>/dev/null || true
    chmod 770 "$BACKUP_DIR" 2>/dev/null || true
    chmod 640 "$BOOTSTRAP_ADMIN_PASSWORD_FILE" 2>/dev/null || true
    # secret.env must be root:root 600 — not readable by service user via filesystem,
    # but loaded by systemd (which reads it as root before dropping privileges).
    chown root:root "$SECRET_KEY_ENV_FILE" 2>/dev/null || true
    chmod 600 "$SECRET_KEY_ENV_FILE" 2>/dev/null || true
    find "$INST" -maxdepth 1 -type f -name 'secret.env.bak-*' \
        -exec chown root:root {} + -exec chmod 600 {} +
    chmod 600 /etc/ssl/private/gnss-caster.key 2>/dev/null || true

    touch \
        "$LOG_DIR/app.log" \
        "$LOG_DIR/error.log" \
        "$LOG_DIR/access.log" \
        "$LOG_DIR/backup.log" \
        "$LOG_DIR/restore.log" \
        "$LOG_DIR/update.log" \
        "$LOG_DIR/watchdog.log"
    chown -R root:"$SERVICE_GROUP" "$LOG_DIR"
    chmod 770 "$LOG_DIR"
    chmod 660 "$LOG_DIR"/*.log 2>/dev/null || true
}

run_install_smoke_tests() {
    local web_port
    local ntrip_port
    local health_url
    local attempt=1
    local max_attempts=15
    # Each flag: 0 = check not yet passed, 1 = check passed
    local service_pass=0
    local web_pass=0
    local ntrip_pass=0
    local bootstrap_pass=0

    web_port=$(get_config_value "web_port" "8080")
    ntrip_port=$(get_config_value "ntrip_port" "2101")
    health_url="http://127.0.0.1:${web_port}/api/health"

    while [ "$attempt" -le "$max_attempts" ]; do
        service_pass=0
        web_pass=0
        ntrip_pass=0
        bootstrap_pass=0

        systemctl is-active --quiet gnss-caster  && service_pass=1
        curl -sS --max-time 5 -f "$health_url" >/dev/null 2>&1 && web_pass=1
        ss -ltn | grep -Eq ":${ntrip_port}[[:space:]]" && ntrip_pass=1

        if [ "$EXPECT_BOOTSTRAP_ADMIN_PASSWORD" -eq 0 ] || [ -f "$BOOTSTRAP_ADMIN_PASSWORD_FILE" ]; then
            bootstrap_pass=1
        fi

        if [ $service_pass -eq 1 ] && [ $web_pass -eq 1 ] && [ $ntrip_pass -eq 1 ] && [ $bootstrap_pass -eq 1 ]; then
            echo "Smoke test passed: service active, API healthy, NTRIP port ${ntrip_port} listening."
            return 0
        fi

        if [ "$attempt" -lt "$max_attempts" ]; then
            sleep 2
        fi
        attempt=$((attempt + 1))
    done

    echo "Smoke test failed."
    [ $service_pass -eq 0 ]   && echo " - systemd service is not active"
    [ $web_pass -eq 0 ]       && echo " - backend health check failed: $health_url"
    [ $ntrip_pass -eq 0 ]     && echo " - NTRIP port is not listening: $ntrip_port"
    if [ $bootstrap_pass -eq 0 ]; then
        echo " - bootstrap credentials file not found: $BOOTSTRAP_ADMIN_PASSWORD_FILE"
    fi

    echo ""
    echo "Recent service status:"
    systemctl --no-pager --full status gnss-caster 2>/dev/null | tail -n 20 || true
    echo ""
    echo "Recent application log:"
    tail -n 20 "$LOG_DIR/app.log" 2>/dev/null || true

    return 1
}

uninstall_safety_backup() {
    # Create a safety backup of the database, instance data, and existing
    # backups before they are deleted, unless the operator opted into a purge.
    local safety_root="/var/backups/gnss-caster"
    local ts
    local safety_dir

    if [ ! -d "$INST" ] && [ ! -d "$BACKUP_DIR" ]; then
        echo "No instance data found; skipping safety backup."
        return 0
    fi

    ts=$(date +%Y%m%d_%H%M%S)
    safety_dir="$safety_root/uninstall-$ts"

    mkdir -p "$safety_dir" 2>/dev/null || {
        echo "WARNING: Unable to create safety backup directory $safety_dir; continuing without it."
        return 0
    }
    chmod 700 "$safety_root" "$safety_dir" 2>/dev/null || true

    if [ -d "$INST" ]; then
        cp -a "$INST" "$safety_dir/instance" 2>/dev/null || \
            echo "WARNING: Unable to copy instance data into safety backup."
    fi

    if [ -d "$BACKUP_DIR" ]; then
        cp -a "$BACKUP_DIR" "$safety_dir/backups" 2>/dev/null || \
            echo "WARNING: Unable to copy backups into safety backup."
    fi

    echo "Safety backup created before uninstall: $safety_dir"
    echo "Remove it manually once you have confirmed it is no longer needed."
}

run_uninstall() {
    echo "=== GNSS CASTER UNINSTALL MODE ==="

    if [ "$PURGE_DATA" = "1" ]; then
        echo "Purge mode enabled: instance data, database, and backups WILL be deleted."
    else
        echo "Safe mode: /opt/gnss-caster is removed, and data is copied to a safety backup first."
        echo "Use --purge (or GNSS_CASTER_PURGE=1) to remove all data permanently."
    fi
    echo "Removing GNSS Caster service and files..."

    echo "Stopping and disabling systemd service..."
    systemctl stop gnss-caster >/dev/null 2>&1 || true
    systemctl disable gnss-caster >/dev/null 2>&1 || true
    systemctl reset-failed gnss-caster >/dev/null 2>&1 || true

    echo "Removing systemd unit..."
    rm -f "$SERVICE"
    rm -rf /etc/systemd/system/gnss-caster.service.d
    systemctl daemon-reload >/dev/null 2>&1 || true

    echo "Removing Nginx site config..."
    rm -f "$NGINX_ENABLED" "$NGINX_AVAILABLE" "$NGINX_SECURITY_CONF"
    # Restore the distribution's default site if the installer disabled it.
    if [ -f "$BASE/.nginx-default-was-symlink" ] && [ -e /etc/nginx/sites-available/default ]; then
        ln -sf /etc/nginx/sites-available/default /etc/nginx/sites-enabled/default 2>/dev/null || true
    fi
    if [ -f "$BASE/.nginx-default-was-file" ] && [ -e /etc/nginx/sites-enabled/default.gnss-caster.disabled ]; then
        mv -f /etc/nginx/sites-enabled/default.gnss-caster.disabled /etc/nginx/sites-enabled/default 2>/dev/null || true
    fi
    nginx -t >/dev/null 2>&1 && (systemctl reload nginx >/dev/null 2>&1 || systemctl restart nginx >/dev/null 2>&1) || true

    echo "Removing UFW application profile..."
    rm -f "$UFW_APP_PROFILE"

    echo "Removing fail2ban hardening rules..."
    rm -f "$FAIL2BAN_FILTER" "$FAIL2BAN_JAIL"
    systemctl restart fail2ban >/dev/null 2>&1 || true

    echo "Removing cron jobs and cert renew task..."
    remove_gnss_cron_jobs
    rm -f /etc/cron.d/gnss-caster-cert-renew

    echo "Removing logrotate configuration..."
    rm -f /etc/logrotate.d/gnss-caster

    if [ "$PURGE_DATA" != "1" ]; then
        uninstall_safety_backup
    fi

    echo "Removing application files and logs..."
    rm -rf "$BASE" "$LOG_DIR" /etc/gnss-caster
    rm -f "$SELF_SIGNED_CERT" "$SELF_SIGNED_KEY"
    rm -f "$SUDOERS_FILE"
    rm -f "$POLKIT_RULE"
    # The dedicated secret directory was removed with /etc/gnss-caster above,
    # but also remove explicitly in case path was customised.
    rm -f "$SECRET_KEY_ENV_FILE" 2>/dev/null || true
    userdel "$SERVICE_USER" >/dev/null 2>&1 || true
    groupdel "$SERVICE_GROUP" >/dev/null 2>&1 || true

    echo ""
    echo "Uninstall completed."
    echo "Removed: service, app code, logs, nginx site, cron tasks, logrotate, nginx hardening, fail2ban rules, UFW profile."
    if [ "$PURGE_DATA" = "1" ]; then
        echo "Removed: instance data, database, and backups (purge mode)."
    else
        echo "Removed: /opt/gnss-caster."
        echo "Data safety backup saved under /var/backups/gnss-caster (safe mode)."
    fi
    echo "Note: system packages were NOT removed."
}

# Read a KEY="value" or KEY=value line from secret.env, returning the value.
read_secret_env_value() {
    local key="$1"
    local file="$2"
    local raw=""

    [ -f "$file" ] || return 0

    raw=$(sed -n "s/^${key}=//p" "$file" | head -n 1)
    # Strip optional surrounding double quotes.
    raw="${raw%\"}"
    raw="${raw#\"}"
    printf '%s' "$raw"
}

manage_secret_files() {
    python3 -I - "$1" "$SECRET_DIR" "$LEGACY_SECRET_KEY_ENV_FILE" << 'PY_SECRET_MIGRATION'
import os
from pathlib import Path
import stat
import sys
import tempfile

def migrate_secrets(mode, secure_path, legacy_path):
    if mode not in ('migrate', 'cleanup'):
        raise ValueError('Invalid secret operation')
    secure = Path(secure_path)
    legacy = Path(legacy_path)
    def read_private(path):
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1:
                raise ValueError('Unsafe secret file')
            with os.fdopen(fd, 'rb') as handle:
                fd = -1
                data = handle.read(65537)
            if len(data) > 65536:
                raise ValueError('Secret file too large')
            return data
        finally:
            if fd >= 0:
                os.close(fd)
    def publish(path, data):
        if path.exists() or path.is_symlink():
            if read_private(path) != data:
                raise ValueError('Conflicting secret backup; original preserved')
            os.chmod(path, 0o600)
            return
        fd, temporary = tempfile.mkstemp(prefix='.secret-', dir=secure)
        try:
            with os.fdopen(fd, 'wb') as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)
    # /etc/gnss-caster and its secrets child must not be service-controlled.
    for directory in (secure.parent, secure):
        directory.mkdir(mode=0o700, parents=False, exist_ok=True)
        info = directory.lstat()
        if not stat.S_ISDIR(info.st_mode) or info.st_uid != 0:
            raise ValueError('Unsafe secret directory')
        os.chmod(directory, 0o700)
    sources = sorted(legacy.parent.glob('secret.env.bak-*'))
    if legacy.exists() or legacy.is_symlink():
        sources.insert(0, legacy)
    for source in sources:
        destination = secure / ('legacy-secret.env' if source == legacy else source.name)
        data = read_private(source)
        if mode == 'migrate':
            publish(destination, data)
            if source == legacy and not (secure / 'secret.env').exists():
                publish(secure / 'secret.env', data)
        else:
            if read_private(destination) != data:
                raise ValueError('Legacy secret changed; refusing deletion')
            source.unlink()
    current = secure / 'secret.env'
    if current.exists() or current.is_symlink():
        read_private(current)
        os.chmod(current, 0o600)

if __name__ == '__main__':
    try:
        migrate_secrets(*sys.argv[1:])
    except Exception:
        print('ERROR: Secret migration failed; original files preserved where possible', file=sys.stderr)
        sys.exit(1)
PY_SECRET_MIGRATION
}

run_rotate_secrets() {
    # Rotate the Flask SECRET_KEY (and optionally the Bluetooth pairing PIN)
    # without reinstalling. Generates a fresh 256-bit key, rewrites the
    # secret.env EnvironmentFile (kept mode 0600, outside the systemd unit) and
    # restarts the service. Rotating SECRET_KEY invalidates existing sessions by
    # design, so all users must log in again afterwards.
    echo "=== GNSS CASTER SECRET ROTATION MODE ==="

    if [ ! -d "$INST" ]; then
        echo "ERROR: Instance directory not found: $INST"
        echo "Run installation first."
        exit 1
    fi

    if ! command -v openssl >/dev/null 2>&1; then
        echo "ERROR: openssl is required to rotate the secret key."
        exit 1
    fi

    manage_secret_files migrate

    local new_secret_key
    local current_bt_default_pin
    local current_bt_fallback_pins
    local current_bt_auto_accept
    local current_bt_allowed_devices
    local rotate_bt_pin=0
    local backup_secret_file

    new_secret_key=$(openssl rand -hex 32)

    # Preserve existing Bluetooth settings unless explicitly overridden via env.
    current_bt_default_pin=$(read_secret_env_value "BT_DEFAULT_PIN" "$SECRET_KEY_ENV_FILE")
    current_bt_fallback_pins=$(read_secret_env_value "BT_FALLBACK_PINS" "$SECRET_KEY_ENV_FILE")
    current_bt_auto_accept=$(read_secret_env_value "BT_AUTO_ACCEPT" "$SECRET_KEY_ENV_FILE")
    current_bt_allowed_devices=$(read_secret_env_value "BT_ALLOWED_DEVICES" "$SECRET_KEY_ENV_FILE")

    [ -n "$current_bt_default_pin" ] || current_bt_default_pin="$BT_DEFAULT_PIN"
    [ -n "$current_bt_fallback_pins" ] || current_bt_fallback_pins="$BT_FALLBACK_PINS"
    [ -n "$current_bt_auto_accept" ] || current_bt_auto_accept="$BT_AUTO_ACCEPT"
    if [ -z "$current_bt_allowed_devices" ]; then
        current_bt_allowed_devices="$BT_ALLOWED_DEVICES"
    fi

    # Optional Bluetooth PIN rotation when a new PIN is provided.
    if [ -n "${GNSS_CASTER_BT_DEFAULT_PIN:-}" ]; then
        current_bt_default_pin="$GNSS_CASTER_BT_DEFAULT_PIN"
        rotate_bt_pin=1
    fi
    if [ -n "${GNSS_CASTER_BT_FALLBACK_PINS:-}" ]; then
        current_bt_fallback_pins="$GNSS_CASTER_BT_FALLBACK_PINS"
        rotate_bt_pin=1
    fi

    # Keep a one-time backup of the previous secret file for emergency recovery.
    if [ -f "$SECRET_KEY_ENV_FILE" ]; then
        backup_secret_file="${SECRET_KEY_ENV_FILE}.bak-$(date +%Y%m%d_%H%M%S)"
        cp -a "$SECRET_KEY_ENV_FILE" "$backup_secret_file" 2>/dev/null || true
        chmod 600 "$backup_secret_file" 2>/dev/null || true
    fi

    mkdir -p "$INST"
    {
        printf 'SECRET_KEY=%s\n' "$new_secret_key"
        printf 'BT_DEFAULT_PIN="%s"\n' "$current_bt_default_pin"
        printf 'BT_FALLBACK_PINS="%s"\n' "$current_bt_fallback_pins"
        printf 'BT_AUTO_ACCEPT="%s"\n' "$current_bt_auto_accept"
        printf 'BT_ALLOWED_DEVICES="%s"\n' "$current_bt_allowed_devices"
    } > "$SECRET_KEY_ENV_FILE"
    chmod 600 "$SECRET_KEY_ENV_FILE"
    chown root:root "$SECRET_KEY_ENV_FILE" 2>/dev/null || true

    # Ensure no stale plaintext secret remains in config.yaml.
    if [ -f "$INST/config.yaml" ]; then
        sed -i 's|^\([[:space:]]*secret_key:\).*|\1 ""|' "$INST/config.yaml" 2>/dev/null || true
    fi

    if [ -f "$SERVICE" ]; then
        sed -i "s|^EnvironmentFile=$LEGACY_SECRET_KEY_ENV_FILE$|EnvironmentFile=$SECRET_KEY_ENV_FILE|" "$SERVICE"
        systemctl daemon-reload
    fi
    local service_restart_status="not attempted"
    if [ -f "$SERVICE" ] && command -v systemctl >/dev/null 2>&1; then
        if systemctl restart gnss-caster >/dev/null 2>&1; then
            service_restart_status="ok"
            manage_secret_files cleanup
        else
            service_restart_status="failed"
        fi
    fi

    echo ""
    echo "Secret rotation completed."
    echo "SECRET_KEY: rotated"
    if [ "$rotate_bt_pin" -eq 1 ]; then
        echo "Bluetooth PIN: rotated"
    else
        echo "Bluetooth PIN: unchanged (set GNSS_CASTER_BT_DEFAULT_PIN to rotate)"
    fi
    echo "Secret file: $SECRET_KEY_ENV_FILE (mode 600)"
    if [ -n "${backup_secret_file:-}" ]; then
        echo "Previous secret backup: $backup_secret_file"
        echo "Remove the backup once the new secret is confirmed working."
    fi
    echo "Service restart: $service_restart_status"
    echo "Note: all active web sessions are invalidated by the new SECRET_KEY."
}

run_reset_admin_password() {
    echo "=== GNSS CASTER ADMIN PASSWORD RESET MODE ==="
    echo "Resetting built-in admin password..."

    if [ ! -x "$VENV/bin/python" ]; then
        echo "ERROR: Installed Python runtime not found: $VENV/bin/python"
        echo "Run installation first."
        exit 1
    fi

    if [ ! -f "$INST/config.yaml" ] || [ ! -f "$APP/web/factory.py" ]; then
        echo "ERROR: GNSS Caster installation not found under $BASE"
        echo "Run installation first."
        exit 1
    fi

    migrate_bootstrap_admin_password_location

    local reset_admin_py
    local reset_output
    local reset_admin_username
    local reset_admin_password_file
    local reset_admin_status
    local service_restart_status="not attempted"

    reset_admin_py=$(mktemp /tmp/gnss-caster-reset-admin.XXXXXX.py)

cat > "$reset_admin_py" << 'EOF'
import os
import sys
import time
import secrets
import yaml

sys.path.insert(0, '/opt/gnss-caster')

from app.web.factory import create_app, bcrypt
from app.db.models import db, Admin, write_private_text

CONFIG_PATH = '/opt/gnss-caster/instance/config.yaml'

def load_default_admin_username():
    try:
        with open(CONFIG_PATH, 'r', encoding='utf-8') as config_file:
            config = yaml.safe_load(config_file) or {}
    except Exception:
        config = {}

    return str(
        os.environ.get('GNSS_CASTER_RESET_ADMIN_USERNAME')
        or config.get('security', {}).get('admin_default_user')
        or 'admin'
    ).strip() or 'admin'

def write_bootstrap_file(path, username, password):
    write_private_text(path,
        '# GNSS Caster bootstrap admin credentials\n'
        f'username={username}\n'
        f'password={password}\n'
        'reason=reset\n'
        f'generated_at={int(time.time())}\n'
    )

app = create_app()

with app.app_context():
    db.create_all()

    username = load_default_admin_username()
    password = secrets.token_urlsafe(18)
    password_file_path = str(
        os.environ.get('GNSS_CASTER_BOOTSTRAP_PASSWORD_FILE')
        or app.config.get('BOOTSTRAP_ADMIN_PASSWORD_FILE')
        or '/opt/gnss-caster/instance/initial-admin-password'
    ).strip() or '/opt/gnss-caster/instance/initial-admin-password'

    admin_user = Admin.query.filter_by(username=username).first()
    status = 'updated'
    password_hash = bcrypt.generate_password_hash(password).decode()
    now_ts = int(time.time())

    if admin_user is None:
        admin_user = Admin(
            username=username,
            password=password_hash,
            role='admin',
            email='admin@gnss-caster.local',
            last_login=0,
            login_attempts=0,
            locked_until=0,
            must_change_password=True,
            created_at=now_ts,
            updated_at=now_ts,
        )
        db.session.add(admin_user)
        status = 'created'
    else:
        admin_user.set_password_hash(password_hash)
        admin_user.login_attempts = 0
        admin_user.locked_until = 0
        admin_user.must_change_password = True
        admin_user.updated_at = now_ts

    db.session.commit()
    write_bootstrap_file(password_file_path, username, password)

    print(f'RESET_ADMIN_STATUS={status}')
    print(f'RESET_ADMIN_USERNAME={username}')
    print(f'RESET_ADMIN_PASSWORD_FILE={password_file_path}')
EOF

    if ! reset_output=$(
        GNSS_CASTER_BOOTSTRAP_PASSWORD_FILE="$BOOTSTRAP_ADMIN_PASSWORD_FILE" \
        "$VENV/bin/python" "$reset_admin_py"
    ); then
        rm -f "$reset_admin_py"
        echo "ERROR: Unable to reset admin password"
        exit 1
    fi

    rm -f "$reset_admin_py"

    reset_admin_status=$(printf '%s\n' "$reset_output" | sed -n 's/^RESET_ADMIN_STATUS=//p' | head -n1)
    reset_admin_username=$(printf '%s\n' "$reset_output" | sed -n 's/^RESET_ADMIN_USERNAME=//p' | head -n1)
    reset_admin_password_file=$(printf '%s\n' "$reset_output" | sed -n 's/^RESET_ADMIN_PASSWORD_FILE=//p' | head -n1)

    if [ -n "${reset_admin_password_file:-}" ] && [ -f "$reset_admin_password_file" ]; then
        chown root:"$SERVICE_GROUP" "$reset_admin_password_file" 2>/dev/null || true
        chmod 640 "$reset_admin_password_file" 2>/dev/null || true
    fi

    if [ -f "$SERVICE" ] && command -v systemctl >/dev/null 2>&1; then
        if systemctl restart gnss-caster >/dev/null 2>&1; then
            service_restart_status="ok"
        else
            service_restart_status="failed"
        fi
    fi

    echo ""
    echo "Admin password reset completed."
    echo "Account status: ${reset_admin_status:-updated}"
    echo "Default credentials: ${reset_admin_username:-admin} / <see file>"
    echo "Credentials file: ${reset_admin_password_file:-$BOOTSTRAP_ADMIN_PASSWORD_FILE}"
    echo "Show password: sudo cat ${reset_admin_password_file:-$BOOTSTRAP_ADMIN_PASSWORD_FILE}"
    echo "Service restart: $service_restart_status"
}

capture_diagnostic_shell() {
    local output_file="$1"
    shift
    local command_text="$*"
    local command_status

    {
        echo "$ $command_text"
        echo ""
    } > "$output_file" 2>&1

    # Use a non-login, non-interactive shell with a fixed PATH. The command
    # strings are built by this installer (not from external input), and
    # avoiding a login shell prevents profile side effects from altering output.
    set +e
    PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin" \
        /bin/bash --noprofile --norc -c "$command_text" >> "$output_file" 2>&1
    command_status=$?
    set -e

    {
        echo ""
        echo "[exit_status=$command_status]"
    } >> "$output_file" 2>&1
}

print_service_status() {
    local unit_name="$1"
    local active_state="unavailable"
    local enabled_state="unavailable"

    if command -v systemctl >/dev/null 2>&1; then
        active_state=$(systemctl is-active "$unit_name" 2>/dev/null || true)
        enabled_state=$(systemctl is-enabled "$unit_name" 2>/dev/null || true)
    fi

    printf '  %-22s active=%-12s enabled=%s\n' "$unit_name" "$active_state" "$enabled_state"
}

print_cron_file_status() {
    local cron_file="$1"
    local label="$2"

    if [ ! -f "$cron_file" ]; then
        echo "  $label: absent"
        return
    fi

    echo "  $label: present ($cron_file)"
    sed -n '/^[[:space:]]*#/d;/^[[:space:]]*$/d;p' "$cron_file" 2>/dev/null | sed 's/^/    /' || true
}

is_tcp_port_listening() {
    local tcp_port="$1"
    if ! command -v ss >/dev/null 2>&1; then
        return 1
    fi
    ss -ltn 2>/dev/null | grep -Eq "[:.]${tcp_port}[[:space:]]"
}

show_tcp_port_listeners() {
    local tcp_port="$1"
    if ! command -v ss >/dev/null 2>&1; then
        return 0
    fi
    ss -ltnp 2>/dev/null | grep -E "[:.]${tcp_port}[[:space:]]" || true
}

show_tcp_port_process_names() {
    local tcp_port="$1"
    if ! command -v ss >/dev/null 2>&1; then
        return 0
    fi

    ss -ltnp 2>/dev/null | grep -E "[:.]${tcp_port}[[:space:]]" | \
        grep -oE '"[^"]+"' | tr -d '"' | sort -u
}

print_network_status() {
    echo ""
    echo "Network:"

    if command -v hostname >/dev/null 2>&1; then
        echo "  host_ips=$(hostname -I 2>/dev/null | xargs echo || true)"
    fi

    if command -v ip >/dev/null 2>&1; then
        echo "  default_route:"
        ip route show default 2>/dev/null | sed 's/^/    /' || echo "    unavailable"

        echo "  active_addresses:"
        ip -brief addr show scope global 2>/dev/null | sed 's/^/    /' || echo "    unavailable"
    else
        echo "  ip command unavailable"
    fi

    if [ -f /etc/resolv.conf ]; then
        echo "  dns:"
        grep -E '^[[:space:]]*nameserver[[:space:]]+' /etc/resolv.conf 2>/dev/null | sed 's/^/    /' || echo "    unavailable"
    fi

    if command -v iw >/dev/null 2>&1; then
        echo "  wifi_links:"
        local wifi_interfaces
        wifi_interfaces=$(iw dev 2>/dev/null | awk '$1=="Interface" {print $2}')
        if [ -n "$wifi_interfaces" ]; then
            for wifi_iface in $wifi_interfaces; do
                echo "    [$wifi_iface]"
                iw dev "$wifi_iface" link 2>/dev/null | sed 's/^/      /' || true
            done
        else
            echo "    no wireless interfaces reported by iw"
        fi
    fi

    if command -v rfkill >/dev/null 2>&1; then
        echo "  rfkill:"
        rfkill list 2>/dev/null | sed 's/^/    /' || true
    fi

    if command -v journalctl >/dev/null 2>&1; then
        echo "  recent network warnings:"
        journalctl \
            -u ssh -u sshd -u NetworkManager -u systemd-networkd -u dhcpcd -u wpa_supplicant \
            --since '30 minutes ago' --no-pager 2>/dev/null | \
            grep -Ei 'disconnect|deauth|carrier|timeout|failed|error|dhcp|wlan|ssh' | \
            tail -n 12 | sed 's/^/    /' || true
    fi
}

print_operational_profile() {
    local systemd_version="unknown"
    local bt_auto_accept
    local bt_allowlist
    local bt_mode="open (auto-accept)"
    local firewall_state="unknown"

    echo ""
    echo "Operational profile:"

    if command -v systemctl >/dev/null 2>&1; then
        systemd_version=$(systemctl --version 2>/dev/null | awk 'NR==1 {print $2}')
        [ -n "$systemd_version" ] || systemd_version="unknown"
    fi
    echo "  systemd_version=$systemd_version"

    if [ -f "$SERVICE" ]; then
        echo "  systemd_hardening:"
        grep -E '^(NoNewPrivileges|ProtectSystem|ProtectHome|ProtectProc|ProcSubset|ReadWritePaths|PrivateTmp|LockPersonality)=' "$SERVICE" 2>/dev/null \
            | sed 's/^/    /' || echo "    unavailable"
    else
        echo "  systemd_hardening=unit not installed"
    fi

    if [ -f "$SECRET_KEY_ENV_FILE" ]; then
        bt_auto_accept=$(read_secret_env_value "BT_AUTO_ACCEPT" "$SECRET_KEY_ENV_FILE")
        bt_allowlist=$(read_secret_env_value "BT_ALLOWED_DEVICES" "$SECRET_KEY_ENV_FILE")
        case "$(printf '%s' "$bt_auto_accept" | tr '[:upper:]' '[:lower:]')" in
            0|false|no|off)
                bt_mode="allowlist only"
                ;;
        esac
        echo "  bluetooth_pairing=$bt_mode"
        if [ -n "$bt_allowlist" ]; then
            echo "  bluetooth_allowlist=$bt_allowlist"
        else
            echo "  bluetooth_allowlist=(none)"
        fi
    else
        echo "  bluetooth_pairing=unknown (secret.env not found)"
    fi

    if command -v ufw >/dev/null 2>&1; then
        firewall_state=$(ufw status 2>/dev/null | awk 'NR==1 {print $2}')
        [ -n "$firewall_state" ] || firewall_state="unknown"
        echo "  firewall(ufw)=$firewall_state"
        if [ "$firewall_state" = "active" ]; then
            ufw status 2>/dev/null | grep -E "(^|[^0-9])$(get_config_value "web_port" "8080")(/| )" \
                | sed 's/^/    /' || true
        fi
    else
        echo "  firewall(ufw)=not installed"
    fi
}

run_status() {
    echo "=== GNSS CASTER STATUS ==="

    local web_port
    local ntrip_port
    local health_url
    local tls_mode_label="HTTP only"

    web_port=$(get_config_value "web_port" "8080")
    ntrip_port=$(get_config_value "ntrip_port" "2101")

    case "$web_port" in
        ''|*[!0-9]*)
            web_port="8080"
            ;;
    esac
    case "$ntrip_port" in
        ''|*[!0-9]*)
            ntrip_port="2101"
            ;;
    esac

    health_url="http://127.0.0.1:${web_port}/api/health"

    if [ -f "$NGINX_AVAILABLE" ] && grep -Eq 'listen[[:space:]]+443[[:space:]]+ssl' "$NGINX_AVAILABLE"; then
        tls_mode_label="HTTPS enabled"
    fi

    echo ""
    echo "Services:"
    print_service_status "gnss-caster"
    print_service_status "nginx"
    print_service_status "bluetooth"
    print_service_status "fail2ban"
    print_service_status "cron"

    echo ""
    echo "Ports and health:"
    echo "  web_port=$web_port"
    echo "  ntrip_port=$ntrip_port"
    echo "  tls=$tls_mode_label"

    if command -v curl >/dev/null 2>&1; then
        if curl -sS --max-time 5 -f "$health_url" >/dev/null 2>&1; then
            echo "  health=ok ($health_url)"
        else
            echo "  health=failed ($health_url)"
        fi
    else
        echo "  health=unknown (curl not installed)"
    fi

    if is_tcp_port_listening "80" || is_tcp_port_listening "443"; then
        echo "  nginx_public_listeners:"
        show_tcp_port_listeners "80" | sed 's/^/    /'
        show_tcp_port_listeners "443" | sed 's/^/    /'
    else
        echo "  nginx_public_listeners=absent"
    fi

    if is_tcp_port_listening "$web_port"; then
        echo "  web_backend_listener=present"
        show_tcp_port_listeners "$web_port" | sed 's/^/    /'
    else
        echo "  web_backend_listener=absent"
    fi

    if is_tcp_port_listening "$ntrip_port"; then
        echo "  ntrip_listener=present"
        show_tcp_port_listeners "$ntrip_port" | sed 's/^/    /'
    else
        echo "  ntrip_listener=absent"
    fi

    print_network_status

    echo ""
    echo "Web-managed settings:"
    if [ -f "$INST/db.sqlite" ] && command -v sqlite3 >/dev/null 2>&1; then
        sqlite3 "$INST/db.sqlite" \
            "SELECT key || '=' || value FROM system_setting WHERE key IN ('ntrip_enabled','bluetooth_enabled','bluetooth_discoverable','auto_backup','backup_interval','log_retention','data_retention','max_connections') ORDER BY key;" \
            2>/dev/null | sed 's/^/  /' || echo "  unavailable"
    else
        echo "  unavailable (database or sqlite3 not found)"
    fi

    echo ""
    echo "Cron:"
    print_cron_file_status "$MAINTENANCE_CRON" "maintenance"
    print_cron_file_status "$BACKUP_CRON" "backup"

    echo ""
    echo "Fail2ban:"
    if command -v fail2ban-client >/dev/null 2>&1; then
        fail2ban-client status 2>/dev/null | sed 's/^/  /' || echo "  unavailable"
    else
        echo "  fail2ban-client not installed"
    fi

    print_operational_profile

    echo ""
    echo "Recent app warnings/errors:"
    if [ -f "$LOG_DIR/app.log" ]; then
        grep -Ei 'error|warning|failed|traceback' "$LOG_DIR/app.log" 2>/dev/null | tail -n 10 | sed 's/^/  /' || true
    else
        echo "  app log not found"
    fi
}

write_install_report() {
    mkdir -p "$INST"

    cat > "$INSTALL_REPORT" << EOF
GNSS Caster installation report
Generated at: $(date -Is 2>/dev/null || date)
Host: $(hostname 2>/dev/null || echo unknown)

Access:
  Web Interface: ${WEB_SCHEME:-http}://${WEB_HOST:-127.0.0.1}/
  API Endpoint: ${WEB_SCHEME:-http}://${WEB_HOST:-127.0.0.1}/api/
  NTRIP Server: ${IP_ADDRESS:-127.0.0.1}:${INSTALL_NTRIP_PORT:-2101}

Runtime Profile:
  TLS mode: ${TLS_MODE:-none}
  TLS domain: ${TLS_DOMAIN:-}
  Web backend bind: 127.0.0.1:${INSTALL_WEB_PORT} (private, behind nginx)
  NTRIP bind: 0.0.0.0:${INSTALL_NTRIP_PORT} (public)
  Bluetooth pairing: $([ "$BT_AUTO_ACCEPT" = "1" ] && echo "open (auto-accept)" || echo "allowlist only")
  Fail2ban: $([ "$ENABLE_FAIL2BAN" = "1" ] && echo enabled || echo disabled)
  Monitor auto-recovery: disabled by default
  Health watchdog cron: ${WATCHDOG_CRON_STATUS:-disabled}
  Weekly auto-update cron: $([ "$ENABLE_AUTO_UPDATE" = "1" ] && echo enabled || echo disabled)
  Automatic backup cron: ${BACKUP_CRON_STATUS:-unknown}
  Log retention: ${LOGROTATE_STATUS:-unknown}

Files:
  Bootstrap credentials file: $BOOTSTRAP_ADMIN_PASSWORD_FILE
  Status command: sudo /opt/gnss-caster/status.sh
  Diagnostics command: sudo /opt/gnss-caster/diagnose.sh
  Repair command: sudo /opt/gnss-caster/repair.sh
  Watchdog command: sudo /opt/gnss-caster/watchdog.sh
  App log: /var/log/gnss-caster/app.log
EOF

    if [ -f "$INST/db.sqlite" ] && command -v sqlite3 >/dev/null 2>&1; then
        {
            echo ""
            echo "Web-managed settings:"
            sqlite3 "$INST/db.sqlite" \
                "SELECT '  ' || key || ': ' || value FROM system_setting WHERE key IN ('ntrip_enabled','bluetooth_enabled','bluetooth_discoverable','auto_backup','backup_interval','log_retention','data_retention','max_connections') ORDER BY key;" \
                2>/dev/null || true
        } >> "$INSTALL_REPORT"
    fi

    chmod 600 "$INSTALL_REPORT" 2>/dev/null || true
}

prepare_runtime_port() {
    local port_label="$1"
    local tcp_port="$2"

    echo "Checking for processes using $port_label port $tcp_port..."
    if ! is_tcp_port_listening "$tcp_port"; then
        return 0
    fi

    echo "WARNING: $port_label TCP port $tcp_port is already listening."
    show_tcp_port_listeners "$tcp_port" | sed 's/^/  /'

    if command -v systemctl >/dev/null 2>&1 && systemctl is-active --quiet gnss-caster; then
        echo "Stopping existing gnss-caster service to release $port_label port $tcp_port..."
        systemctl stop gnss-caster >/dev/null 2>&1 || true
        sleep 2

        if ! is_tcp_port_listening "$tcp_port"; then
            echo "$port_label port $tcp_port was released by stopping gnss-caster."
            return 0
        fi

        echo "$port_label port $tcp_port is still occupied after stopping gnss-caster."
        show_tcp_port_listeners "$tcp_port" | sed 's/^/  /'
    fi

    if [ "$FORCE_PORT_KILL" = "1" ]; then
        local listener_names
        local listener_name
        local kill_allowed=1

        listener_names=$(show_tcp_port_process_names "$tcp_port")
        if [ -n "$listener_names" ]; then
            while IFS= read -r listener_name; do
                [ -n "$listener_name" ] || continue
                case "$listener_name" in
                    python|python3|gnss-caster|waitress-serve|gunicorn)
                        ;;
                    *)
                        kill_allowed=0
                        ;;
                esac
            done << EOF
$listener_names
EOF
        fi

        if [ "$kill_allowed" -ne 1 ]; then
            echo "ERROR: Refusing to kill non-GNSS processes on $port_label port $tcp_port."
            echo "Current listeners:"
            show_tcp_port_listeners "$tcp_port" | sed 's/^/  /'
            echo "Use a different port or stop conflicting services manually."
            exit 1
        fi

        echo "GNSS_CASTER_FORCE_PORT_KILL=1 set; killing GNSS-related listeners on $port_label port $tcp_port."
        fuser -k "${tcp_port}/tcp" || true
        sleep 2

        if ! is_tcp_port_listening "$tcp_port"; then
            echo "$port_label port $tcp_port was released after forced kill."
            return 0
        fi

        echo "ERROR: $port_label port $tcp_port is still occupied after forced kill."
        show_tcp_port_listeners "$tcp_port" | sed 's/^/  /'
        exit 1
    fi

    echo "ERROR: $port_label port $tcp_port is occupied and will not be killed automatically."
    echo "Free the port manually, choose a different GNSS_CASTER_WEB_PORT/GNSS_CASTER_NTRIP_PORT, or rerun with GNSS_CASTER_FORCE_PORT_KILL=1."
    exit 1
}

write_systemd_service_unit() {
    local systemd_version=0
    local optional_hardening=""

    if command -v systemctl >/dev/null 2>&1; then
        systemd_version=$(systemctl --version 2>/dev/null | awk 'NR==1 {print $2}')
        case "$systemd_version" in
            ''|*[!0-9]*)
                systemd_version=0
                ;;
        esac
    fi

    # ProtectProc/ProcSubset require systemd >= 247 (Debian Bullseye+).
    # On older systemd they are unknown directives and break the unit, so
    # only emit them when supported.
    if [ "$systemd_version" -ge 247 ]; then
        optional_hardening=$'ProtectProc=invisible\nProcSubset=pid\n'
    fi

cat > "$SERVICE" << EOF
[Unit]
Description=GNSS Caster Service
After=network-online.target bluetooth.target nginx.target
Wants=network-online.target
StartLimitIntervalSec=300
StartLimitBurst=10

[Service]
Type=simple
User=$SERVICE_USER
Group=$SERVICE_GROUP
SupplementaryGroups=dialout tty bluetooth
WorkingDirectory=$BASE
RuntimeDirectory=gnss-caster
RuntimeDirectoryMode=0700
Environment="PATH=$VENV/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
Environment="PYTHONPATH=$BASE"
# SECRET_KEY and Bluetooth PINs are loaded from a mode-600 file so they are
# not exposed via `systemctl show gnss-caster`.
EnvironmentFile=$SECRET_KEY_ENV_FILE
Environment="PYTHONUNBUFFERED=1"
# Live Bluetooth RSSI, read over HCI from the established link. Set to 0 to
# disable if a particular adapter turns out to dislike being queried.
Environment="GNSS_CASTER_LIVE_RSSI=${ENABLE_LIVE_RSSI:-1}"
# How often station counters are persisted. Higher means fewer SD-card writes;
# lower means fresher totals in the UI. Minimum 5 seconds.
Environment="GNSS_CASTER_DB_FLUSH_SECONDS=${DB_FLUSH_SECONDS:-30}"
ExecStartPre=/usr/bin/test -x $VENV/bin/python
ExecStartPre=/usr/bin/test -f $BASE/main.py
ExecStart=$VENV/bin/python $BASE/main.py
Restart=on-failure
RestartSec=5
TimeoutStartSec=60
TimeoutStopSec=20
KillMode=mixed
LimitNOFILE=65535
TasksAccounting=yes
TasksMax=512
MemoryAccounting=yes
# sudo is limited to a fixed set of $PRIVILEGED_HELPER subcommands by
# /etc/sudoers.d/gnss-caster, and every call is audited in
# /var/log/gnss-caster/privileged-helper.log. NoNewPrivileges must stay 'no'
# so the service can invoke that helper; tightening this requires replacing
# sudo with a separate privileged socket service.
NoNewPrivileges=no
PrivateTmp=yes
# Use 'full' by default for broader compatibility across distros/packages.
# 'strict' can break runtime behavior in some environments where components
# still expect limited writable access outside explicit paths.
ProtectSystem=full
ProtectClock=yes
ProtectHostname=yes
${optional_hardening}ReadWritePaths=$INST $BACKUP_DIR $LOG_DIR
ProtectHome=yes
ProtectControlGroups=yes
ProtectKernelModules=yes
ProtectKernelTunables=yes
LockPersonality=yes
RestrictSUIDSGID=no
UMask=0077

# Logging
StandardOutput=append:$LOG_DIR/app.log
StandardError=append:$LOG_DIR/error.log
SyslogIdentifier=gnss-caster

[Install]
WantedBy=multi-user.target
EOF

    strip_crlf "$SERVICE"
}

