import re as _locale_re
_BOT_PATTERNS = []
for _english, _russian in TELEGRAM_RU.items():
    if '{0}' in _english:
        _pattern = _locale_re.escape(_english)
        _pattern = _locale_re.sub(r'\\\{\d+\\\}', '(.*?)', _pattern)
        _BOT_PATTERNS.append((_locale_re.compile(_pattern), _russian))


def translate_bot(text, language='en'):
    if language != 'ru' or not isinstance(text, str):
        return text
    if text in TELEGRAM_RU:
        return TELEGRAM_RU[text]
    translated = []
    for line in text.split('\n'):
        prefix = line[:len(line) - len(line.lstrip())]
        value = line.lstrip()
        if value.startswith('• '):
            prefix += '• '
            value = value[2:]
        result = TELEGRAM_RU.get(value)
        if result is None:
            for pattern, template in _BOT_PATTERNS:
                match = pattern.fullmatch(value)
                if match:
                    result = template.format(*match.groups())
                    break
        translated.append(prefix + (result if result is not None else value))
    return '\n'.join(translated)


def localize_keyboard(keyboard, language):
    return {'inline_keyboard': [[dict(button, text=translate_bot(button['text'], language))
                                for button in row] for row in keyboard['inline_keyboard']]}


def _handle_command(app, settings, text):
    reply = _handle_command_raw(app, settings, text)
    language = settings.get('language', 'en')
    if isinstance(reply, tuple):
        message, keyboard = reply
        return translate_bot(message, language), localize_keyboard(keyboard, language)
    return translate_bot(reply, language)


def start_command_poller(app):
    """Start the long-polling loop once. Safe to call repeatedly."""
    if _poller_started.is_set():
        return
    _poller_started.set()

    def _loop():
        offset = 0
        backoff = 5.0
        while True:
            try:
                settings = load_settings(app)
                if not (settings['commands_enabled'] and settings['token'] and settings['admin_id']):
                    time.sleep(20)
                    continue

                response = _call(
                    settings['token'],
                    'getUpdates',
                    {'offset': offset, 'timeout': 25},
                    timeout=40,
                )
                backoff = 5.0
                if not response.get('ok'):
                    time.sleep(backoff)
                    continue

                for update in response.get('result', []):
                    offset = max(offset, int(update.get('update_id', 0)) + 1)

                    # A tapped button arrives as a callback_query, a typed
                    # command as a message. Both end up in the same handler.
                    callback = update.get('callback_query')
                    if callback:
                        chat = (callback.get('message') or {}).get('chat') or {}
                        sender_id = str(chat.get('id', ''))
                        if sender_id != settings['admin_id']:
                            continue
                        # Acknowledge promptly or Telegram keeps the button spinning.
                        _call(settings['token'], 'answerCallbackQuery',
                              {'callback_query_id': callback.get('id', '')}, timeout=10)
                        reply = _handle_command(
                            app, settings, '/' + str(callback.get('data') or '')
                        )
                        if reply:
                            # A handler may ask for its own keyboard - a
                            # confirmation prompt, for instance.
                            text, keyboard = (
                                reply if isinstance(reply, tuple) else (reply, localize_keyboard(MAIN_KEYBOARD, settings.get('language', 'en')))
                            )
                            _post_message(settings['token'], sender_id, text, keyboard)
                        continue

                    message = update.get('message') or update.get('channel_post') or {}
                    chat = message.get('chat') or {}
                    sender_id = str(chat.get('id', ''))
                    # Only the configured administrator may issue commands.
                    if sender_id != settings['admin_id']:
                        continue
                    reply = _handle_command(app, settings, message.get('text', ''))
                    if reply:
                        text, keyboard = (
                            reply if isinstance(reply, tuple) else (reply, localize_keyboard(MAIN_KEYBOARD, settings.get('language', 'en')))
                        )
                        _post_message(settings['token'], sender_id, text, keyboard)
            except urllib.error.URLError:
                time.sleep(backoff)
                backoff = min(backoff * 2, 120.0)
            except Exception as poll_error:
                logger.debug(f'Telegram poller error: {poll_error}')
                time.sleep(backoff)
                backoff = min(backoff * 2, 120.0)

    threading.Thread(target=_loop, daemon=True, name='telegram-poller').start()
    logger.info('Telegram command poller started')
EOF

