from dbus_next import BusType, Variant, DBusError
from dbus_next.aio import MessageBus
from dbus_next.service import ServiceInterface, method
from app.db.models import BaseStation, MountPoint, RTCMSetting, db, LogEntry, CommandLog, SystemSetting
from app.rtcm.registry import (
    build_receiver_rtcm_commands,
