logger = logging.getLogger(__name__)

PRIVILEGED_HELPER_PATH = '/opt/gnss-caster/gnss-caster-privileged-helper.sh'
SYSTEM_COMMAND_PATH = '/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin'


def _build_subprocess_env():
    env = os.environ.copy()
    current_path = str(env.get('PATH') or '').strip()
    env['PATH'] = f'{current_path}:{SYSTEM_COMMAND_PATH}' if current_path else SYSTEM_COMMAND_PATH
    return env


def _run_privileged_helper(helper_args, timeout=30):
    command = ['sudo', '-n', PRIVILEGED_HELPER_PATH, *[str(arg) for arg in helper_args]]
    return subprocess.run(
        command,
        capture_output=True,
        text=True,
        timeout=timeout,
        env=_build_subprocess_env(),
    )


class PairingAgent(ServiceInterface):
    def __init__(self, pin_code='0000', auto_accept=True, allowed_devices=None):
        super().__init__('org.bluez.Agent1')
        self.pin_code = str(pin_code or '0000')
        # When auto_accept is False, only devices on the allowlist are
        # authorized automatically; everything else is rejected.
        self.auto_accept = bool(auto_accept)
        self.allowed_devices = set(
            str(mac or '').strip().upper()
            for mac in (allowed_devices or [])
            if str(mac or '').strip()
        )

    @staticmethod
    def _device_mac_from_path(device_path):
        # BlueZ device object paths look like
        # /org/bluez/hci0/dev_AA_BB_CC_DD_EE_FF
        raw = str(device_path or '')
        marker = 'dev_'
        index = raw.rfind(marker)
        if index < 0:
            return ''
        mac_part = raw[index + len(marker):]
        return mac_part.replace('_', ':').upper()

    def _is_device_allowed(self, device_path):
        if self.auto_accept:
            return True
        if not self.allowed_devices:
            return False
        return self._device_mac_from_path(device_path) in self.allowed_devices

    @method()
    def Release(self):
        return

    @method()
    def RequestPinCode(self, device: 'o') -> 's':
        if not self._is_device_allowed(device):
            logger.warning(f'BlueZ Agent RequestPinCode rejected for {device} (not allowlisted)')
            raise DBusError('org.bluez.Error.Rejected', 'device not allowlisted')
        logger.info(f'BlueZ Agent RequestPinCode for {device}, using configured PIN')
        return self.pin_code

    @method()
    def DisplayPinCode(self, device: 'o', pincode: 's'):
        logger.info(f'BlueZ Agent DisplayPinCode for {device}')
        return

    @method()
    def RequestPasskey(self, device: 'o') -> 'u':
        if not self._is_device_allowed(device):
            logger.warning(f'BlueZ Agent RequestPasskey rejected for {device} (not allowlisted)')
            raise DBusError('org.bluez.Error.Rejected', 'device not allowlisted')
        logger.info(f'BlueZ Agent RequestPasskey for {device}, using configured PIN')
        digits = ''.join(ch for ch in self.pin_code if ch.isdigit())
        if not digits:
            return 0
        return int(digits)

    @method()
    def DisplayPasskey(self, device: 'o', passkey: 'u', entered: 'q'):
        logger.info(f'BlueZ Agent DisplayPasskey for {device}')
        return

    @method()
    def RequestConfirmation(self, device: 'o', passkey: 'u'):
        if not self._is_device_allowed(device):
            logger.warning(f'BlueZ Agent RequestConfirmation rejected for {device} (not allowlisted)')
            raise DBusError('org.bluez.Error.Rejected', 'device not allowlisted')
        logger.info(f'BlueZ Agent RequestConfirmation for {device} (accepted)')
        return

    @method()
    def RequestAuthorization(self, device: 'o'):
        if not self._is_device_allowed(device):
            logger.warning(f'BlueZ Agent RequestAuthorization rejected for {device} (not allowlisted)')
            raise DBusError('org.bluez.Error.Rejected', 'device not allowlisted')
        logger.info(f'BlueZ Agent RequestAuthorization for {device} (accepted)')
        return

    @method()
    def AuthorizeService(self, device: 'o', uuid: 's'):
        if not self._is_device_allowed(device):
            logger.warning(
                f'BlueZ Agent AuthorizeService rejected for {device}, uuid={uuid} (not allowlisted)'
            )
            raise DBusError('org.bluez.Error.Rejected', 'device not allowlisted')
        logger.info(f'BlueZ Agent AuthorizeService for {device}, uuid={uuid} (accepted)')
        return

    @method()
    def Cancel(self):
        logger.info('BlueZ Agent Cancel called')
        return


class BlueZDBusClient:
    BLUEZ_SERVICE = 'org.bluez'
    OBJECT_MANAGER_IFACE = 'org.freedesktop.DBus.ObjectManager'
    PROPERTIES_IFACE = 'org.freedesktop.DBus.Properties'
    ADAPTER_IFACE = 'org.bluez.Adapter1'
    DEVICE_IFACE = 'org.bluez.Device1'
    GATT_SERVICE_IFACE = 'org.bluez.GattService1'
    GATT_CHAR_IFACE = 'org.bluez.GattCharacteristic1'
    AGENT_MANAGER_IFACE = 'org.bluez.AgentManager1'

    def __init__(self):
        self.default_adapter = None
        self.agent_path = '/org/gnss_caster/agent'
        self.default_pin_code = os.environ.get('BT_DEFAULT_PIN', '0000').strip()
        fallback_raw = os.environ.get('BT_FALLBACK_PINS', '1234,1111')
        self.fallback_pins = [
            pin.strip() for pin in fallback_raw.split(',') if pin.strip()
        ]
        # auto_accept: when enabled (default for backward compatibility) the
        # pairing agent accepts every pairing/authorization request. When
        # disabled, only devices listed in BT_ALLOWED_DEVICES are accepted.
        auto_accept_raw = str(os.environ.get('BT_AUTO_ACCEPT', '1') or '1').strip().lower()
        self.auto_accept = auto_accept_raw in ('1', 'true', 'yes', 'on')
        allowed_raw = os.environ.get('BT_ALLOWED_DEVICES', '')
        self.allowed_devices = [
            mac.strip().upper()
            for mac in str(allowed_raw or '').replace(';', ',').split(',')
            if mac.strip()
        ]
        self.pair_no_pin_capabilities = ['NoInputNoOutput', 'DisplayYesNo']
        self.pair_pin_capabilities = ['KeyboardDisplay', 'DisplayYesNo']

    def _run(self, coroutine):
        loop = asyncio.new_event_loop()
        try:
            asyncio.set_event_loop(loop)
            return loop.run_until_complete(coroutine)
        finally:
            asyncio.set_event_loop(None)
            loop.close()

    @staticmethod
    def _normalize_mac(mac_address):
        return mac_address.strip().upper()

    async def _connect_bus(self):
        return await MessageBus(bus_type=BusType.SYSTEM).connect()

    async def _get_managed_objects(self, bus):
        introspection = await bus.introspect(self.BLUEZ_SERVICE, '/')
        proxy_object = bus.get_proxy_object(self.BLUEZ_SERVICE, '/', introspection)
        object_manager = proxy_object.get_interface(self.OBJECT_MANAGER_IFACE)
        return await object_manager.call_get_managed_objects()

    def _select_adapter_path(self, managed_objects):
        if (
            self.default_adapter
            and self.default_adapter in managed_objects
            and self.ADAPTER_IFACE in managed_objects[self.default_adapter]
        ):
            return self.default_adapter

        for path, interfaces in managed_objects.items():
            if self.ADAPTER_IFACE in interfaces:
                self.default_adapter = path
                return path

        return None

    async def _get_adapter_interfaces(self, bus):
        managed_objects = await self._get_managed_objects(bus)
        adapter_path = self._select_adapter_path(managed_objects)

        if not adapter_path:
            raise RuntimeError('Bluetooth adapter not found in BlueZ D-Bus tree')

        introspection = await bus.introspect(self.BLUEZ_SERVICE, adapter_path)
        proxy_object = bus.get_proxy_object(self.BLUEZ_SERVICE, adapter_path, introspection)
        adapter_interface = proxy_object.get_interface(self.ADAPTER_IFACE)
        properties_interface = proxy_object.get_interface(self.PROPERTIES_IFACE)

        return adapter_path, adapter_interface, properties_interface

    async def _ensure_adapter_ready(self, bus):
        _, adapter_interface, properties_interface = await self._get_adapter_interfaces(bus)

        await properties_interface.call_set(self.ADAPTER_IFACE, 'Powered', Variant('b', True))

        try:
            await properties_interface.call_set(self.ADAPTER_IFACE, 'Pairable', Variant('b', True))
        except DBusError:
            pass

        return adapter_interface

    @staticmethod
    def _is_auth_error(error):
        text = str(error).lower()
        return (
            'authentication failed' in text
            or 'authenticationfailed' in text
            or 'authenticationrejected' in text
            or 'org.bluez.error.authentication' in text
        )

    async def _register_pairing_agent(self, bus, pin_code=None, capability='KeyboardDisplay'):
        pin_to_use = str(pin_code or self.default_pin_code or '0000')

        introspection = await bus.introspect(self.BLUEZ_SERVICE, '/org/bluez')
        proxy_object = bus.get_proxy_object(self.BLUEZ_SERVICE, '/org/bluez', introspection)
        agent_manager = proxy_object.get_interface(self.AGENT_MANAGER_IFACE)

        try:
            await agent_manager.call_unregister_agent(self.agent_path)
        except DBusError:
            pass

        try:
            bus.unexport(self.agent_path)
        except Exception:
            pass

        agent = PairingAgent(
            pin_to_use,
            auto_accept=self.auto_accept,
            allowed_devices=self.allowed_devices,
        )
        bus.export(self.agent_path, agent)

        await agent_manager.call_register_agent(self.agent_path, capability)

        try:
            await agent_manager.call_request_default_agent(self.agent_path)
        except DBusError as default_agent_error:
            logger.warning(f'Cannot request default BlueZ agent: {default_agent_error}')

        # Do not log the PIN itself to avoid leaking it into log files.
        logger.info(
            'BlueZ pairing agent registered '
            f'(capability={capability}, auto_accept={self.auto_accept}, '
            f'allowlist={len(self.allowed_devices)} device(s))'
        )
        return agent_manager

    async def _unregister_pairing_agent(self, bus, agent_manager):
        if agent_manager:
            try:
                await agent_manager.call_unregister_agent(self.agent_path)
            except DBusError:
                pass

        try:
            bus.unexport(self.agent_path)
        except Exception:
            pass

    async def _remove_device(self, bus, device_path):
        adapter_path, adapter_interface, _ = await self._get_adapter_interfaces(bus)
        if not device_path.startswith(adapter_path):
            return

        try:
            await adapter_interface.call_remove_device(device_path)
            logger.info(f'Removed stale device object {device_path} before pairing retry')
        except DBusError as remove_error:
            logger.warning(f'Unable to remove device {device_path}: {remove_error}')

    async def _is_device_paired(self, properties_interface):
        try:
            paired_variant = await properties_interface.call_get(self.DEVICE_IFACE, 'Paired')
            return bool(paired_variant.value)
        except Exception:
            return False

    async def _wait_until_paired(self, properties_interface, timeout=15):
        wait_seconds = max(1, min(int(timeout), 60))
        deadline = time.time() + wait_seconds
        while time.time() < deadline:
            if await self._is_device_paired(properties_interface):
                return True
            await asyncio.sleep(1)
        return await self._is_device_paired(properties_interface)

    async def _pair_with_retry(
        self,
        bus,
        device_interface,
        properties_interface,
        timeout,
        preferred_pin_code='',
    ):
        attempts = []

        preferred_pin = str(preferred_pin_code or '').strip()
        if preferred_pin:
            for capability in self.pair_pin_capabilities:
                attempts.append((capability, preferred_pin))

        # First try pairing modes that usually do not require PIN (Just Works).
        for capability in self.pair_no_pin_capabilities:
            attempts.append((capability, ''))

        # Then try known/default PIN variants.
        pin_candidates = []
        if self.default_pin_code:
            pin_candidates.append(self.default_pin_code)
        for pin in self.fallback_pins:
            if pin and pin not in pin_candidates:
                pin_candidates.append(pin)

        for pin in pin_candidates:
            if preferred_pin and pin == preferred_pin:
                continue
            for capability in self.pair_pin_capabilities:
                attempts.append((capability, pin))

        last_error = None

        for capability, pin_code in attempts:
            agent_manager = None
            try:
                if await self._is_device_paired(properties_interface):
                    logger.info('Device is already paired')
                    return

                agent_manager = await self._register_pairing_agent(
                    bus,
                    pin_code=pin_code,
                    capability=capability,
                )
                await asyncio.wait_for(device_interface.call_pair(), timeout=timeout)
                logger.info(
                    f'Pairing succeeded (capability={capability}, '
                    f'pin={"<empty>" if not pin_code else pin_code})'
                )
                return
            except DBusError as pair_error:
                last_error = pair_error
                error_text = str(pair_error).lower()

                if 'alreadyexists' in error_text or 'already exists' in error_text:
                    logger.info('Device is already paired')
                    return

                if 'inprogress' in error_text or 'in progress' in error_text:
                    logger.info('Pairing already in progress, waiting for completion')
                    if await self._wait_until_paired(properties_interface, timeout=min(timeout, 20)):
                        logger.info('Pairing completed while waiting')
                        return
                    logger.warning('Pairing remained in progress and did not complete in time')
                    continue

                logger.warning(
                    f'Pairing attempt failed (capability={capability}, '
                    f'pin={"<empty>" if not pin_code else pin_code}): {pair_error}'
                )
            except asyncio.TimeoutError as timeout_error:
                last_error = timeout_error
                logger.warning(
                    f'Pairing timeout (capability={capability}, '
                    f'pin={"<empty>" if not pin_code else pin_code})'
                )
            finally:
                await self._unregister_pairing_agent(bus, agent_manager)

        raise RuntimeError(
            'Bluetooth pairing failed. '
            f'Last error: {last_error}'
        )

    @staticmethod
    def _extract_devices(managed_objects):
        devices_by_mac = {}
        now = time.time()

        for _, interfaces in managed_objects.items():
            if 'org.bluez.Device1' not in interfaces:
                continue

            device_properties = interfaces['org.bluez.Device1']
            address_variant = device_properties.get('Address')
            if not address_variant:
                continue

            mac = str(address_variant.value).upper()
            name_variant = device_properties.get('Name')
            alias_variant = device_properties.get('Alias')
            paired_variant = device_properties.get('Paired')
            connected_variant = device_properties.get('Connected')
            rssi_variant = device_properties.get('RSSI')
            is_paired = bool(paired_variant.value) if paired_variant else False
            is_connected = bool(connected_variant.value) if connected_variant else False
            has_rssi = False

            name = None
            if name_variant and name_variant.value:
                name = str(name_variant.value)
            elif alias_variant and alias_variant.value:
                name = str(alias_variant.value)
            else:
                name = 'Unknown device'

            address_type_variant = device_properties.get('AddressType')
            uuids_variant = device_properties.get('UUIDs')

            advertised_uuids = []
            if uuids_variant is not None:
                try:
                    advertised_uuids = [str(u).lower() for u in uuids_variant.value]
                except (TypeError, ValueError):
                    advertised_uuids = []

            # Classic SPP (Serial Port Profile) means RFCOMM; a BLE UART service
            # means the GATT transport. AddressType 'random' can only be BLE.
            has_spp = any(u.startswith('00001101-') for u in advertised_uuids)
            ble_uart_prefixes = ('0000ffe0-', '6e400001-', '49535343-')
            has_ble_uart = any(
                u.startswith(prefix)
                for u in advertised_uuids
                for prefix in ble_uart_prefixes
            )
            address_type = str(address_type_variant.value).lower() if address_type_variant else ''

            # Prefer BLE when a BLE UART service is present: dual-mode receivers
            # often still advertise a cached classic SPP record that no longer
            # answers (classic radio disabled), while the BLE UART service is
            # the one actually serving data.
            if has_ble_uart or address_type == 'random':
                suggested_transport = 'ble'
            elif has_spp:
                suggested_transport = 'bluetooth'
            else:
                suggested_transport = ''

            device_data = {
                'mac': mac,
                'name': name,
                'paired': is_paired,
                'connected': is_connected,
                'timestamp': now,
                'address_type': address_type,
                'has_spp': has_spp,
                'has_ble_uart': has_ble_uart,
                'suggested_transport': suggested_transport,
            }

            if rssi_variant is not None:
                try:
                    device_data['rssi'] = int(rssi_variant.value)
                    has_rssi = True
                except (TypeError, ValueError):
                    pass

            # BlueZ only publishes RSSI while a device is actively being
            # discovered; once a device is paired it usually disappears from
            # advertisements, so a paired-but-not-connected device legitimately
            # has no RSSI. Hiding those made a freshly paired base station
            # vanish from the scan results and become impossible to add, so
            # keep them and flag whether they were seen in this scan instead.
            device_data['in_range'] = has_rssi or is_connected
            existing = devices_by_mac.get(mac)
            if not existing:
                devices_by_mac[mac] = device_data
                continue

            if device_data.get('connected') and not existing.get('connected'):
                devices_by_mac[mac] = device_data
                continue

            if 'rssi' in device_data and 'rssi' not in existing:
                devices_by_mac[mac] = device_data
                continue

            if 'rssi' in device_data and 'rssi' in existing:
                if device_data['rssi'] > existing['rssi']:
                    devices_by_mac[mac] = device_data

        devices = list(devices_by_mac.values())
        # Connected first, then paired (they are the ones the operator is most
        # likely acting on and they carry no RSSI to sort by), then the rest by
        # signal strength.
        devices.sort(
            key=lambda d: (
                0 if d.get('connected') else (1 if d.get('paired') else 2),
                -d.get('rssi', -9999),
            )
        )
        return devices

    async def _find_device_path(self, bus, mac_address, allow_scan=False, scan_timeout=8):
        normalized = self._normalize_mac(mac_address)

        def find_in_objects(managed_objects):
            for object_path, interfaces in managed_objects.items():
                if self.DEVICE_IFACE not in interfaces:
                    continue

                address_variant = interfaces[self.DEVICE_IFACE].get('Address')
                if not address_variant:
                    continue

                if str(address_variant.value).upper() == normalized:
                    return object_path
            return None

        managed_objects = await self._get_managed_objects(bus)
        object_path = find_in_objects(managed_objects)
        if object_path:
            return object_path

        if not allow_scan:
            return None

        adapter_interface = await self._ensure_adapter_ready(bus)

        try:
            await adapter_interface.call_set_discovery_filter({'Transport': Variant('s', 'auto')})
        except DBusError:
            pass

        try:
            await adapter_interface.call_start_discovery()
        except DBusError as e:
            if 'InProgress' not in str(e):
                raise

        try:
            await asyncio.sleep(max(2, min(int(scan_timeout), 60)))
        finally:
            try:
                await adapter_interface.call_stop_discovery()
            except DBusError:
                pass

        managed_objects = await self._get_managed_objects(bus)
        return find_in_objects(managed_objects)

    async def _get_device_interfaces(self, bus, object_path):
        introspection = await bus.introspect(self.BLUEZ_SERVICE, object_path)
        proxy_object = bus.get_proxy_object(self.BLUEZ_SERVICE, object_path, introspection)
        device_interface = proxy_object.get_interface(self.DEVICE_IFACE)
        properties_interface = proxy_object.get_interface(self.PROPERTIES_IFACE)
        return device_interface, properties_interface

    async def _pair_and_trust_internal(
        self,
        bus,
        mac_address,
        timeout=20,
        scan_timeout=8,
        pin_code=None,
    ):
        await self._ensure_adapter_ready(bus)
        object_path = await self._find_device_path(
            bus,
            mac_address,
            allow_scan=True,
            scan_timeout=scan_timeout,
        )

        if not object_path:
            raise RuntimeError(f'Device {mac_address} not found via D-Bus scan')

        device_interface, properties_interface = await self._get_device_interfaces(bus, object_path)

        is_paired = await self._is_device_paired(properties_interface)

        if not is_paired:
            await self._pair_with_retry(
                bus=bus,
                device_interface=device_interface,
                properties_interface=properties_interface,
                timeout=timeout,
                preferred_pin_code=pin_code,
            )

        try:
            await properties_interface.call_set(self.DEVICE_IFACE, 'Trusted', Variant('b', True))
        except DBusError as trust_error:
            logger.warning(f'Unable to set Trusted=true for {mac_address}: {trust_error}')

        return object_path, device_interface, properties_interface

    async def _scan_devices_async(self, timeout=10):
        bus = await self._connect_bus()
        try:
            adapter_interface = await self._ensure_adapter_ready(bus)

            try:
                await adapter_interface.call_set_discovery_filter({'Transport': Variant('s', 'auto')})
            except DBusError:
                pass

            try:
                await adapter_interface.call_start_discovery()
            except DBusError as e:
                if 'InProgress' not in str(e):
                    raise

            try:
                await asyncio.sleep(max(2, min(int(timeout), 60)))
            finally:
                try:
                    await adapter_interface.call_stop_discovery()
                except DBusError:
                    pass

            managed_objects = await self._get_managed_objects(bus)
            return self._extract_devices(managed_objects)
        finally:
            bus.disconnect()

    async def _pair_and_trust_async(self, mac_address, timeout=20, scan_timeout=8, pin_code=None):
        bus = await self._connect_bus()
        try:
            try:
                await self._pair_and_trust_internal(
                    bus,
                    mac_address,
                    timeout=timeout,
                    scan_timeout=scan_timeout,
                    pin_code=pin_code,
                )
                return True, 'Device paired and trusted via BlueZ D-Bus'
            except asyncio.TimeoutError:
                return False, 'Pairing timeout via D-Bus'
            except DBusError as e:
                if self._is_auth_error(e):
                    return False, (
                        'D-Bus pairing authentication failed. '
                        'Device may require PIN or explicit confirmation.'
                    )
                return False, f'D-Bus pairing error: {e}'
            except Exception as e:
                return False, str(e)
        finally:
            bus.disconnect()

    async def _connect_device_async(self, mac_address, timeout=20, scan_timeout=8, pin_code=None):
        bus = await self._connect_bus()
        try:
            try:
                _, device_interface, _ = await self._pair_and_trust_internal(
                    bus,
                    mac_address,
                    timeout=timeout,
                    scan_timeout=scan_timeout,
                    pin_code=pin_code,
                )

                try:
                    await asyncio.wait_for(device_interface.call_connect(), timeout=timeout)
                except DBusError as connect_error:
                    error_text = str(connect_error)
                    lowered = error_text.lower()
                    if 'alreadyconnected' in lowered.replace(' ', '') or 'already connected' in lowered:
                        pass
                    elif 'no more profiles' in lowered or 'profile unavailable' in lowered:
                        # Serial-port (SPP) GNSS receivers expose no profile that
                        # BlueZ can auto-connect, so Device1.Connect() legitimately
                        # fails this way even though the device is paired and
                        # reachable. RFCOMM is bound separately and does not need
                        # this call to have succeeded, so treat it as non-fatal.
                        return True, (
                            'Paired and reachable; no auto-connectable Bluetooth '
                            'profile (normal for serial/SPP receivers)'
                        )
                    else:
                        raise

                return True, 'Connected via BlueZ D-Bus'

            except asyncio.TimeoutError:
                return False, 'D-Bus connect timeout'
            except DBusError as e:
                if self._is_auth_error(e):
                    return False, (
                        'D-Bus connect authentication failed. '
                        'Device may require PIN or explicit confirmation.'
                    )
                return False, f'D-Bus connect error: {e}'
            except Exception as e:
                return False, str(e)
        finally:
            bus.disconnect()

    async def _disconnect_device_async(self, mac_address):
        bus = await self._connect_bus()
        try:
            object_path = await self._find_device_path(bus, mac_address, allow_scan=False)
            if not object_path:
                return True

            device_interface, _ = await self._get_device_interfaces(bus, object_path)
            try:
                await device_interface.call_disconnect()
            except DBusError as e:
                error_text = str(e).lower()
                if 'not connected' in error_text or 'failed' in error_text:
                    return True
                raise

            return True
        finally:
            bus.disconnect()

    async def _remove_device_async(self, mac_address):
        bus = await self._connect_bus()
        try:
            object_path = await self._find_device_path(bus, mac_address, allow_scan=False)
            if not object_path:
                return True, 'Device not found in BlueZ database'

            try:
                await self._remove_device(bus, object_path)
                return True, 'Device unpaired and removed from BlueZ'
            except DBusError as e:
                return False, f'D-Bus remove error: {e}'
            except Exception as e:
                return False, str(e)
        finally:
            bus.disconnect()

    async def _ensure_adapter_ready_async(self):
        bus = await self._connect_bus()
        try:
            await self._ensure_adapter_ready(bus)
            return True
        finally:
            bus.disconnect()

    async def _set_adapter_alias_async(self, alias):
        alias_value = str(alias or '').strip()
        if not alias_value:
            return False

        bus = await self._connect_bus()
        try:
            await self._ensure_adapter_ready(bus)
            _, _, properties_interface = await self._get_adapter_interfaces(bus)
            await properties_interface.call_set(
                self.ADAPTER_IFACE,
                'Alias',
                Variant('s', alias_value)
            )
            return True
        except DBusError as alias_error:
            logger.warning(f'Unable to set Bluetooth adapter alias "{alias_value}": {alias_error}')
            return False
        finally:
            bus.disconnect()

    async def _set_adapter_discoverable_async(self, enabled):
        discoverable = bool(enabled)
        bus = await self._connect_bus()
        try:
            await self._ensure_adapter_ready(bus)
            _, _, properties_interface = await self._get_adapter_interfaces(bus)

            try:
                timeout_value = 0 if discoverable else 180
                await properties_interface.call_set(
                    self.ADAPTER_IFACE,
                    'DiscoverableTimeout',
                    Variant('u', int(timeout_value))
                )
            except DBusError:
                pass

            try:
                await properties_interface.call_set(
                    self.ADAPTER_IFACE,
                    'Pairable',
                    Variant('b', discoverable)
                )
            except DBusError:
                pass

            await properties_interface.call_set(
                self.ADAPTER_IFACE,
                'Discoverable',
                Variant('b', discoverable)
            )
            return True
        except DBusError as discoverable_error:
            logger.warning(
                f'Unable to set Bluetooth discoverable={discoverable}: {discoverable_error}'
            )
            return False
        finally:
            bus.disconnect()

    def ensure_adapter_ready(self):
        return self._run(self._ensure_adapter_ready_async())

    def set_adapter_alias(self, alias):
        alias_value = str(alias or '').strip()
        if not alias_value:
            return False
        return self._run(self._set_adapter_alias_async(alias_value))

    def set_adapter_discoverable(self, enabled):
        return self._run(self._set_adapter_discoverable_async(bool(enabled)))

    def scan_devices(self, timeout=10):
        return self._run(self._scan_devices_async(timeout=timeout))

    def pair_and_trust(self, mac_address, timeout=20, scan_timeout=8, pin_code=None):
        return self._run(
            self._pair_and_trust_async(
                mac_address,
                timeout=timeout,
                scan_timeout=scan_timeout,
                pin_code=pin_code,
            )
        )

    def connect_device(self, mac_address, timeout=20, scan_timeout=8, pin_code=None):
        return self._run(
            self._connect_device_async(
                mac_address,
                timeout=timeout,
                scan_timeout=scan_timeout,
                pin_code=pin_code,
            )
        )

    def disconnect_device(self, mac_address):
        return self._run(self._disconnect_device_async(mac_address))

    def remove_device(self, mac_address):
        return self._run(self._remove_device_async(mac_address))


class RFCOMMSerialConnection:
    """Classic Bluetooth (SPP/RFCOMM) link opened as a direct socket.

    The older approach shelled out to `rfcomm bind` and opened /dev/rfcommN.
    That only works when something has registered an SPP profile with BlueZ -
    otherwise the connection attempt ends in "No more profiles to connect to".
    Phone apps do not do that; they open an RFCOMM socket straight to the
    device, which is what this class does. Same file-like surface as the BLE
    transport so the station loop does not care which one it is using.
    """

    def __init__(self, mac_address, channel=1, connect_timeout=20):
        self.mac_address = str(mac_address).upper()
        self.channel = int(channel or 1)
        self.connect_timeout = connect_timeout
        self._socket = None
        self._closed = False

    def connect(self):
        """Connect to the device. Returns (ok, message)."""
        if not hasattr(socket, 'AF_BLUETOOTH') or not hasattr(socket, 'BTPROTO_RFCOMM'):
            return False, 'This Python build has no Bluetooth socket support'

        try:
            sock = socket.socket(
                socket.AF_BLUETOOTH, socket.SOCK_STREAM, socket.BTPROTO_RFCOMM
            )
        except OSError as socket_error:
            return False, f'Could not create an RFCOMM socket: {socket_error}'

        sock.settimeout(self.connect_timeout)
        try:
            sock.connect((self.mac_address, self.channel))
        except OSError as connect_error:
            try:
                sock.close()
            except OSError:
                pass
            return False, (
                f'RFCOMM connect to {self.mac_address} channel {self.channel} '
                f'failed: {connect_error}. If the receiver advertises a different '
                'serial channel, change it in the station settings '
                f'(check with: sdptool browse {self.mac_address}).'
            )

        # Short timeout for reads so the station loop stays responsive.
        sock.settimeout(1.0)
        self._socket = sock
        return True, f'Connected over classic Bluetooth (RFCOMM channel {self.channel})'

    @property
    def is_connected(self):
        return bool(self._socket) and not self._closed

    def fileno(self):
        # Lets select() work on this object exactly like on a file handle.
        return self._socket.fileno() if self._socket else -1

    @property
    def in_waiting(self):
        return 0

    def read(self, size=1024, timeout=1.0):
        if self._closed or not self._socket:
            return b''
        try:
            self._socket.settimeout(timeout)
            return self._socket.recv(size)
        except socket.timeout:
            return b''
        except OSError as read_error:
            logger.warning(f'RFCOMM read failed for {self.mac_address}: {read_error}')
            self._closed = True
            return b''

    def write(self, payload):
        if self._closed or not self._socket:
            return 0
        data = bytes(payload)
        try:
            self._socket.sendall(data)
            return len(data)
        except OSError as write_error:
            logger.warning(f'RFCOMM write failed for {self.mac_address}: {write_error}')
            return 0

    def flush(self):
        return None

    def close(self):
        if self._closed:
            return
        self._closed = True
        if self._socket:
            try:
                self._socket.close()
            except OSError:
                pass
            self._socket = None


class BLESerialConnection:
    """A file-like wrapper around a BLE "serial" (UART-over-GATT) link.

    Many low-cost GNSS receivers expose their data stream over Bluetooth Low
    Energy instead of classic RFCOMM/SPP: a vendor service carries one
    characteristic that notifies incoming bytes and one that accepts writes.
    Classic tools (rfcomm, sdptool, l2ping) cannot reach those devices at all.

    This class hides that behind the same surface the RFCOMM path already uses -
    read(), write(), close() and a select()-friendly buffer - so the station
    loop does not need to care which transport it is talking to.

    Implemented on top of bleak rather than raw BlueZ D-Bus calls: driving
    org.bluez directly turned out to be unreliable for these modules (BlueZ
    frequently reports ServicesResolved while never publishing the GATT objects,
    and prefers BR/EDR for dual-mode records), whereas bleak performs the
    connect/resolve handshake correctly. Everything runs on a private asyncio
    loop in a background thread, mirroring the rest of this module.
    """

    # Known UART-style services, most specific first. 0xFFE0 is the classic
    # HM-10/JDY style module (which is what most DIY GNSS boards use); the
    # others cover Nordic UART and Microchip transparent UART. Characteristics
    # are auto-detected by their properties, so unlisted clones work too.
    UART_PROFILES = [
        {
            'name': 'HM-10/JDY (0xFFE0)',
            'service': '0000ffe0-0000-1000-8000-00805f9b34fb',
        },
        {
            'name': 'Nordic UART',
            'service': '6e400001-b5a3-f393-e0a9-e50e24dcca9e',
        },
        {
            'name': 'Microchip transparent UART',
            'service': '49535343-fe7d-4ae5-8fa9-9fafd205e455',
        },
    ]

    def __init__(self, dbus_client, mac_address, connect_timeout=30):
        self.dbus_client = dbus_client
        self.mac_address = str(mac_address).upper()
        self.connect_timeout = connect_timeout
        self.profile_name = None

        self._buffer = bytearray()
        self._buffer_lock = threading.Lock()
        self._data_event = threading.Event()
        self._closed = False

        self._client = None
        self._notify_uuid = None
        self._write_uuid = None
        self._write_needs_response = False

        self._loop = asyncio.new_event_loop()
        self._thread = threading.Thread(
            target=self._run_loop, daemon=True, name=f'BLE-{self.mac_address}'
        )
        self._thread.start()

    # ---- background asyncio plumbing -----------------------------------
    def _run_loop(self):
        asyncio.set_event_loop(self._loop)
        self._loop.run_forever()

    def _call(self, coro, timeout=None):
        future = asyncio.run_coroutine_threadsafe(coro, self._loop)
        return future.result(timeout=timeout)

    # ---- connection ----------------------------------------------------
    def connect(self):
        """Connect and subscribe. Returns (ok, message)."""
        try:
            from bleak import BleakClient, BleakScanner  # noqa: F401
        except ImportError:
            return False, (
                'The bleak package is required for BLE receivers but is not installed '
                '(pip install bleak inside the application virtualenv)'
            )

        try:
            # Three attempts, each up to ~20s scanning plus the connect timeout.
            return self._call(
                self._connect_async(), timeout=(self.connect_timeout + 25) * 3 + 10
            )
        except FuturesTimeoutError:
            return False, 'BLE connect timed out'
        except Exception as connect_error:
            return False, f'BLE connect failed: {connect_error}'

    async def _connect_async(self):
        from bleak import BleakClient, BleakScanner
        from bleak.exc import BleakError

        last_error = 'BLE connect failed'
        for attempt in range(1, 4):
            # Re-scan before every attempt: BLE modules advertise
            # intermittently, so a single lookup at the start would doom all
            # retries to the same stale (or missing) target.
            device = None
            try:
                device = await BleakScanner.find_device_by_address(
                    self.mac_address, timeout=20
                )
            except BleakError as scan_error:
                logger.warning(f'BLE scan error for {self.mac_address}: {scan_error}')

            if device is None:
                last_error = (
                    f'device {self.mac_address} is not advertising '
                    '(powered off, asleep, out of range, or already connected elsewhere)'
                )
                logger.warning(
                    f'BLE scan {attempt}/3 did not see {self.mac_address}'
                )
                # Still worth trying the raw address: BlueZ may already know it.
                target = self.mac_address
            else:
                target = device

            client = BleakClient(target, timeout=self.connect_timeout)
            try:
                await client.connect()
            except Exception as connect_error:
                last_error = str(connect_error)
                logger.warning(
                    f'BLE connect attempt {attempt}/3 failed for '
                    f'{self.mac_address}: {connect_error}'
                )
                await asyncio.sleep(2)
                continue

            if not client.is_connected:
                last_error = 'link dropped immediately after connecting'
                await asyncio.sleep(2)
                continue

            picked = self._pick_characteristics(client)
            if not picked:
                available = []
                for service in client.services:
                    for char in service.characteristics:
                        available.append(f"{char.uuid}[{'|'.join(char.properties)}]")
                logger.warning(
                    'No usable UART characteristics on %s. Available: %s',
                    self.mac_address, ', '.join(available) or '(none)',
                )
                try:
                    await client.disconnect()
                except Exception:
                    pass
                return False, (
                    'Connected over BLE, but no usable UART characteristics were found '
                    '(need one notify and one write characteristic).'
                )

            try:
                await client.start_notify(self._notify_uuid, self._on_notify)
            except Exception as notify_error:
                try:
                    await client.disconnect()
                except Exception:
                    pass
                return False, f'Could not subscribe to BLE notifications: {notify_error}'

            self._client = client
            return True, f'Connected over BLE ({self.profile_name})'

        return False, f'BLE connect failed: {last_error}'

    def _pick_characteristics(self, client):
        """Choose the notify/write pair, preferring a known UART service."""
        known_services = {p['service']: p['name'] for p in self.UART_PROFILES}

        candidates = []
        for service in client.services:
            service_uuid = str(service.uuid).lower()
            notify_char = None
            write_char = None
            for char in service.characteristics:
                props = set(char.properties)
                if not notify_char and ({'notify', 'indicate'} & props):
                    notify_char = char
                if not write_char and ({'write', 'write-without-response'} & props):
                    write_char = char
            if notify_char and write_char:
                candidates.append((service_uuid, notify_char, write_char))

        if not candidates:
            return False

        # Prefer a recognised UART service, otherwise take the first usable one.
        chosen = next(
            (c for c in candidates if c[0] in known_services), candidates[0]
        )
        service_uuid, notify_char, write_char = chosen

        self.profile_name = known_services.get(
            service_uuid, f'auto-detected ({service_uuid})'
        )
        self._notify_uuid = notify_char.uuid
        self._write_uuid = write_char.uuid
        self._write_needs_response = 'write' in set(write_char.properties)

        logger.info(
            'BLE UART on %s: service=%s notify=%s write=%s mtu=%s',
            self.mac_address, service_uuid, self._notify_uuid, self._write_uuid,
            getattr(client, 'mtu_size', 'unknown'),
        )
        return True

    def _on_notify(self, _characteristic, data):
        chunk = bytes(data or b'')
        if not chunk:
            return
        with self._buffer_lock:
            self._buffer.extend(chunk)
            # Guard against unbounded growth if nobody reads for a long time.
            if len(self._buffer) > 1_048_576:
                del self._buffer[:-524_288]
        self._data_event.set()

    # ---- file-like surface ---------------------------------------------
    @property
    def is_connected(self):
        """True while the BLE link is actually up (used to tell a dead link
        apart from a transient data-processing error)."""
        client = self._client
        if self._closed or client is None:
            return False
        try:
            return bool(client.is_connected)
        except Exception:
            return False

    @property
    def in_waiting(self):
        with self._buffer_lock:
            return len(self._buffer)

    def read(self, size=1024, timeout=1.0):
        """Return up to `size` buffered bytes, waiting up to `timeout` seconds."""
        if self._closed:
            return b''

        if not self.in_waiting:
            self._data_event.wait(timeout)
            self._data_event.clear()

        with self._buffer_lock:
            if not self._buffer:
                return b''
            chunk = bytes(self._buffer[:size])
            del self._buffer[:size]
            return chunk

    def write(self, payload):
        if self._closed or not self._client or not self._write_uuid:
            return 0
        data = bytes(payload)
        # Use the negotiated ATT MTU when the stack reports one: writing in
        # 20-byte pieces is only the pessimistic fallback, and a larger MTU
        # means far fewer BLE packets for the same payload (fewer chances to
        # lose one). 3 bytes of every ATT packet are protocol overhead.
        chunk_size = 20
        try:
            negotiated_mtu = int(getattr(self._client, 'mtu_size', 0) or 0)
            if negotiated_mtu > 23:
                chunk_size = max(20, min(negotiated_mtu - 3, 244))
        except (TypeError, ValueError):
            pass

        written = 0
        chunks = [data[i:i + chunk_size] for i in range(0, len(data), chunk_size)]
        for index, piece in enumerate(chunks):
            # A busy module can reject a write with a transient GATT error
            # ("Unlikely Error") while it is flushing its output buffer, so
            # retry briefly instead of treating the first failure as fatal.
            sent = False
            for attempt in range(3):
                try:
                    self._call(
                        self._client.write_gatt_char(
                            self._write_uuid, piece, response=self._write_needs_response
                        ),
                        timeout=5,
                    )
                    sent = True
                    break
                except Exception as write_error:
                    if attempt == 2 or not self.is_connected:
                        logger.warning(
                            f'BLE write failed for {self.mac_address}: {write_error}'
                        )
                        break
                    time.sleep(0.3)

            if not sent:
                break

            written += len(piece)
            if index + 1 < len(chunks):
                time.sleep(0.05)
        return written

    def flush(self):
        return None

    def close(self):
        if self._closed:
            return
        self._closed = True
        try:
            if self._client is not None:
                try:
                    if self._notify_uuid:
                        self._call(self._client.stop_notify(self._notify_uuid), timeout=5)
                except Exception:
                    pass
                try:
                    self._call(self._client.disconnect(), timeout=10)
                except Exception:
                    pass
        finally:
            self._client = None
            self._loop.call_soon_threadsafe(self._loop.stop)
            self._data_event.set()


class BluetoothManager:
    def __init__(self):
        self.connections = {}
        self.running = False
        self.threads = []
        self.lock = threading.Lock()
        self.command_locks = {}
        self.scan_results = []
        self.scan_lock = threading.Lock()
        self.device_files = {}
        self.app = None
        self.dbus_client = BlueZDBusClient()
        self.telemetry = {}
        self.telemetry_lock = threading.RLock()
        self.nmea_buffers = {}
        self.byte_history = {}
        # How often station counters are written to SQLite. Every write hits
        # the SD card, and at the old 5-second cadence that is ~17k writes a
        # day purely for statistics - a real wear problem on flash media.
        # 30 seconds keeps the dashboard responsive enough while cutting that
        # by 6x. Override with GNSS_CASTER_DB_FLUSH_SECONDS.
        try:
            self.db_flush_interval = max(
                5.0, float(os.environ.get('GNSS_CASTER_DB_FLUSH_SECONDS', '30'))
            )
        except (TypeError, ValueError):
            self.db_flush_interval = 30.0
        # mac -> (rssi, read_at). Rate-limits the privileged HCI query so that
        # polling a status page cannot flood the adapter that is streaming.
        self._live_rssi_cache = {}
        # station_id -> deque of (sequence, line) with recent receiver output,
        # so the web console never has to touch the live device handle.
        self.console_buffers = {}
        # station_id -> signature of the last startup sequence actually sent,
        # so reconnects do not re-flash an unchanged receiver.
        self._applied_command_signatures = {}
        # station_id -> last parsed VERSION tuple, so an unchanged reply does
        # not write to the database on every reconnect.
        self._reported_versions = {}
        # GNSS-derived clock, toggled from the web interface. Cached briefly so
        # the setting can be read on the hot NMEA path without a query per
        # sentence.
        self._time_sync_cache = (False, 0.0)
        self._time_sync_cache_seconds = 60.0
        self.gnss_time_sync_interval = 300.0   # do not hammer the clock
        self.gnss_time_sync_threshold = 5.0    # seconds of drift worth fixing
        self._last_clock_sync_at = 0.0
        # station_id -> frames_parsed at the previous health check, to spot a
        # station that is connected but no longer producing RTCM.
        self._last_frame_counts = {}
        # Base position history: one row a minute is enough to see whether the
        # antenna stayed put, without filling the card.
        self._last_position_sample_at = {}
        # Adapter recovery: how many "Host is down" failures in a row before
        # resetting the controller, and how long to wait between resets.
        self._connect_failure_streak = {}
        self._last_adapter_recovery_at = 0.0
        self._adapter_recovery_attempts = 0
        self._adapter_recovery_running = False
        self._adapter_recovery_state = {'status': 'idle', 'attempt': 0}
        self.adapter_recovery_after_failures = 5
        # Short enough that a second, deeper attempt happens while the station
        # is still down, long enough not to thrash the radio.
        self.adapter_recovery_cooldown = 240.0
        self.position_sample_interval = 60.0
        # How far the receiver's own position may sit from the configured base
        # coordinates before it is worth a warning.
        self.base_drift_alert_metres = 2.0
        self._console_sequence = 0
        self.live_rssi_cache_seconds = 30.0
        # Live RSSI is read over HCI from the established link. This was once
        # suspected of disturbing the RFCOMM stream, but 30 consecutive reads on
        # a streaming station showed no effect, so it is enabled by default.
        # The 30-second cache above keeps the query rate sane. Set
        # GNSS_CASTER_LIVE_RSSI=0 to disable it.
        self.live_rssi_enabled = str(
            os.environ.get('GNSS_CASTER_LIVE_RSSI', '1')
        ).strip().lower() in ('1', 'true', 'yes', 'on')
        self._last_gga_forward = {}  # station_id -> last GGA forward timestamp (Fix #9)

    def init_app(self, app):
        """Initialize manager with Flask app"""
        self.app = app

    def _get_command_lock(self, station_id):
        normalized_station_id = int(station_id)
        with self.lock:
            existing_lock = self.command_locks.get(normalized_station_id)
            if existing_lock is None:
                existing_lock = threading.Lock()
                self.command_locks[normalized_station_id] = existing_lock
            return existing_lock

    def _read_receiver_command_responses(self, station_id, after_sequence, timeout=0.5):
        """Collect a command reply from the console buffer.

        Reading the device directly would compete with the station loop for the
        same bytes and steal RTCM payload from the rovers - and for a socket
        transport there is no "bytes available" to poll anyway. The station loop
        already tees every readable line into the console buffer, so replies are
        picked up from there. NMEA sentences are filtered out: they are the data
        stream, not an answer to the command.
        """
        deadline = time.time() + max(0.1, float(timeout or 0.5))
        collected = []
        sequence = after_sequence

        while time.time() < deadline:
            sequence, lines = self.read_console_lines(station_id, after_sequence=sequence)
            for line in lines:
                text = str(line).strip()
                if not text:
                    continue
                # Drop NMEA sentences ($GNGGA, $GPGST, ...) - they are the data
                # stream. Do NOT drop everything starting with "$": Unicore
                # answers commands with "$command,<cmd>,response: OK", which is
                # exactly what we are here to capture.
                if re.match(r'^\$[A-Z]{5},', text):
                    continue

                # Binary RTCM shares the link and gets split on stray newlines,
                # so a "line" can be mostly unprintable bytes with the real
                # answer buried inside. Cut to the answer when one is present,
                # and drop the rest rather than storing mojibake.
                marker = max(text.find('$command,'), text.find('#VERSION,'))
                if marker > 0:
                    text = text[marker:]
                elif marker < 0:
                    # No recognisable answer in the line. Random RTCM bytes are
                    # often printable ASCII by chance, so "mostly printable" is
                    # not enough - require the shape of an actual reply.
                    if not re.match(r'^[#$A-Za-z][\x20-\x7e]*$', text):
                        continue
                    if not re.search(r'(?i)\b(ok|error|fail|invalid|unknown|response)\b', text):
                        continue

                collected.append(text[:256])
            if collected:
                break
            time.sleep(0.05)

        return sequence, collected

    @staticmethod
    def _build_station_snapshot(station):
        field_names = [
            'id',
            'name',
            'bt_mac',
            'channel',
            'connection_type',
            'gnss_port',
            'baudrate',
            'data_bits',
            'stop_bits',
            'parity',
            'data_type',
            'output_interval',
            'position_mode',
            'position_accuracy',
            'manual_lat',
            'manual_lon',
            'manual_alt',
            'operation_mode',
            'receiver_brand',
            'survey_duration_sec',
            'antenna_height',
            'add_antenna_height',
            'receiver_model',
            'firmware_version',
            'firmware_date',
            'receiver_serial',
            'antenna_type',
            'antenna_serial',
            'command_strategy',
            'startup_commands',
            'shutdown_commands',
            'status',
            'last_seen',
            'bytes_received',
            'bytes_sent',
        ]
        return SimpleNamespace(
            **{field_name: getattr(station, field_name, None) for field_name in field_names}
        )

    def _load_station_snapshot(self, station_id):
        if not self.app:
            return None

        try:
            with self.app.app_context():
                station = db.session.get(BaseStation, int(station_id))
                if not station:
                    return None
                return self._build_station_snapshot(station)
        except Exception as station_load_error:
            logger.error(
                f'Unable to load base station snapshot for {station_id}: {station_load_error}'
            )
            try:
                with self.app.app_context():
                    db.session.rollback()
            except Exception:
                pass
            return None

    def _update_connection_info(self, station_id, **updates):
        with self.lock:
            conn_info = self.connections.get(str(int(station_id)))
            if not conn_info:
                return
            conn_info.update(updates)

    def _increment_connection_counter(self, station_id, counter_name, step=1):
        """Atomically bump a numeric counter (e.g. reconnect_count) on conn_info."""
        with self.lock:
            conn_info = self.connections.get(str(int(station_id)))
            if not conn_info:
                return
            try:
                current_value = int(conn_info.get(counter_name, 0) or 0)
            except (TypeError, ValueError):
                current_value = 0
            conn_info[counter_name] = current_value + int(step)

    def _apply_station_database_updates(
        self,
        station_id,
        *,
        status=None,
        last_seen=None,
        bytes_received_delta=0,
        bytes_sent_delta=0,
    ):
        if not self.app:
            return False

        normalized_station_id = int(station_id)
        try:
            with self.app.app_context():
                station = db.session.get(BaseStation, normalized_station_id)
                if not station:
                    return False

                if status is not None:
                    station.status = str(status)

                if last_seen is not None:
                    station.last_seen = int(last_seen)

                if bytes_received_delta:
                    station.bytes_received = int(station.bytes_received or 0) + int(bytes_received_delta)

                if bytes_sent_delta:
                    station.bytes_sent = int(station.bytes_sent or 0) + int(bytes_sent_delta)

                db.session.commit()
                return True
        except Exception as station_update_error:
            logger.error(
                f'Unable to update base station {normalized_station_id}: {station_update_error}'
            )
            try:
                with self.app.app_context():
                    db.session.rollback()
            except Exception:
                pass
            return False

    def start(self):
        """Start Bluetooth connections for all base stations"""
        active_threads = [thread for thread in self.threads if thread.is_alive()]
        self.threads = active_threads
        if self.running and any(thread.name == 'BT-Main' for thread in active_threads):
            logger.info('Bluetooth manager is already running')
            return

        self.running = True
        logger.info('Starting Bluetooth manager (BlueZ D-Bus mode)')

        self._reset_bluetooth()

        monitor_thread = threading.Thread(
            target=self._monitor_connections,
            daemon=True,
            name='BT-Monitor'
        )
        monitor_thread.start()
        self.threads.append(monitor_thread)

        main_thread = threading.Thread(
            target=self._main_loop,
            daemon=True,
            name='BT-Main'
        )
        main_thread.start()
        self.threads.append(main_thread)

        logger.info('Bluetooth manager started')

    def _reset_bluetooth(self):
        """Prepare Bluetooth adapter without unnecessary daemon restarts"""
        try:
            rfkill_result = _run_privileged_helper(
                ['rfkill-unblock-bluetooth'],
                timeout=10,
            )
            if rfkill_result.returncode != 0:
                logger.warning(f'Unable to unblock Bluetooth: {rfkill_result.stderr or rfkill_result.stdout}')

            bluetooth_active = subprocess.run(
                ['systemctl', 'is-active', '--quiet', 'bluetooth'],
                capture_output=True,
                text=True,
                timeout=10,
            )
            if bluetooth_active.returncode != 0:
                start_result = _run_privileged_helper(
                    ['systemctl-start', 'bluetooth'],
                    timeout=20,
                )
                if start_result.returncode != 0:
                    raise RuntimeError(start_result.stderr or start_result.stdout or 'Unable to start bluetooth')
                time.sleep(2)
                logger.info('Bluetooth service was inactive and has been started')
            else:
                logger.info('Bluetooth service already active; skipping daemon restart')

            self.dbus_client.ensure_adapter_ready()

            adapter_alias = ''
            discoverable_enabled = True
            if self.app:
                try:
                    with self.app.app_context():
                        bt_name_setting = SystemSetting.query.filter_by(key='bluetooth_name').first()
                        bt_discoverable_setting = SystemSetting.query.filter_by(
                            key='bluetooth_discoverable'
                        ).first()
                        system_name_setting = SystemSetting.query.filter_by(key='system_name').first()

                        if bt_name_setting and bt_name_setting.value:
                            adapter_alias = str(bt_name_setting.value).strip()
                        elif system_name_setting and system_name_setting.value:
                            adapter_alias = str(system_name_setting.value).strip()

                        if bt_discoverable_setting and bt_discoverable_setting.value is not None:
                            discoverable_enabled = (
                                str(bt_discoverable_setting.value).strip().lower()
                                in ('1', 'true', 'yes', 'on')
                            )
                except Exception as settings_error:
                    logger.warning(f'Unable to read Bluetooth/system name from settings: {settings_error}')

            if not adapter_alias:
                adapter_alias = os.environ.get('BT_ADAPTER_ALIAS', '').strip()

            if not adapter_alias:
                adapter_alias = 'RPI-Caster-GNSS'

            if adapter_alias:
                self.dbus_client.set_adapter_alias(adapter_alias)
                logger.info(f'Bluetooth adapter alias set to "{adapter_alias}"')

            self.dbus_client.set_adapter_discoverable(discoverable_enabled)
            logger.info(f'Bluetooth discoverable mode set to {discoverable_enabled}')

            logger.info('Bluetooth adapter prepared and powered via D-Bus')

        except Exception as e:
            logger.error(f'Error resetting Bluetooth: {e}')

    def scan_devices(self, timeout=10):
        """Scan for nearby Bluetooth devices via BlueZ D-Bus"""
        logger.info(f'Starting Bluetooth scan via D-Bus (timeout: {timeout}s)')

        devices = []
        try:
            devices = self.dbus_client.scan_devices(timeout=timeout)
            logger.info(f'Bluetooth D-Bus scan found {len(devices)} devices')
        except Exception as e:
            logger.error(f'Error during D-Bus scan: {e}')

        with self.scan_lock:
            self.scan_results = devices

        return devices

    def get_scan_results(self):
        """Get latest scan results"""
        with self.scan_lock:
            return self.scan_results.copy()

    def _resolve_station_rssi(self, station):
        """Signal strength for a station, live where possible.

        Classic Bluetooth links can be measured directly through the HCI
        connection, which is what a connected receiver should show. BLE and
        disconnected devices fall back to the last scan sample; the caller
        renders "no recent scan" when neither is available.
        """
        connection_type = str(
            getattr(station, 'connection_type', 'bluetooth') or 'bluetooth'
        ).strip().lower()

        if connection_type not in ('bluetooth', 'ble'):
            return None

        mac_address = getattr(station, 'bt_mac', '')
        if not mac_address:
            return None

        station_id = str(getattr(station, 'id', '') or '')
        with self.lock:
            connection_info = self.connections.get(station_id) or {}
            is_connected = bool(connection_info.get('connected'))

        if is_connected and connection_type == 'bluetooth' and self.live_rssi_enabled:
            live_rssi = self.get_live_rssi_for_mac(mac_address)
            if live_rssi is not None:
                return {'rssi': live_rssi, 'age_seconds': 0, 'live': True}

        return self.get_cached_rssi_for_mac(mac_address)

    def get_live_rssi_for_mac(self, mac_address):
        """Signal strength of an established link, or None.

        BlueZ publishes RSSI over D-Bus only while scanning, so a connected
        receiver has none - which is why a working station used to display
        "no recent scan". hcitool reads it from the live HCI connection
        instead. Returns the value in dBm.

        Cached deliberately: the status endpoint is polled every few seconds by
        every open dashboard, and issuing a privileged HCI query that often on
        top of a live RFCOMM stream is a good way to disturb the very link we
        are measuring.
        """
        normalized_mac = str(mac_address or '').strip().upper()
        if not normalized_mac:
            return None

        now_ts = time.time()
        with self.lock:
            cached = self._live_rssi_cache.get(normalized_mac)
        if cached and (now_ts - cached[1]) < self.live_rssi_cache_seconds:
            return cached[0]

        try:
            result = _run_privileged_helper(['read-rssi', normalized_mac], timeout=5)
        except Exception as rssi_error:
            logger.debug(f'Live RSSI read failed for {normalized_mac}: {rssi_error}')
            return None

        value = None
        if result.returncode == 0:
            # Output looks like: "RSSI return value: -53"
            match = re.search(r'(-?\d+)', str(result.stdout or ''))
            if match:
                try:
                    value = int(match.group(1))
                except (TypeError, ValueError):
                    value = None

        with self.lock:
            self._live_rssi_cache[normalized_mac] = (value, now_ts)
        return value

    def get_cached_rssi_for_mac(self, mac_address):
        """Look up the most recent signal strength seen for a MAC address.

        BlueZ only reports RSSI while actively scanning (not for an already
        connected device), so this reads from the last completed scan rather
        than the live connection. Returns None when no scan has observed this
        device, the device had no RSSI in that scan, or the cached sample is
        older than 5 minutes (stale enough to be misleading on a detail page).
        """
        normalized_mac = str(mac_address or '').strip().upper()
        if not normalized_mac:
            return None

        with self.scan_lock:
            scan_snapshot = list(self.scan_results)

        for device in scan_snapshot:
            if str(device.get('mac', '')).strip().upper() != normalized_mac:
                continue

            rssi_value = device.get('rssi')
            if rssi_value is None:
                return None

            try:
                sample_age_seconds = max(
                    0,
                    int(time.time() - float(device.get('timestamp', time.time())))
                )
                if sample_age_seconds > 300:
                    return None

                return {
                    'rssi': int(rssi_value),
                    'age_seconds': sample_age_seconds,
                }
            except (TypeError, ValueError):
                return None

        return None

    def test_connection(self, mac_address, channel=1, timeout=10):
        """Test Bluetooth connection using BlueZ D-Bus + RFCOMM"""
        logger.info(f'Testing D-Bus connection to {mac_address}:{channel}')

        try:
            success, message = self.dbus_client.connect_device(
                mac_address,
                timeout=max(timeout, 10),
                scan_timeout=max(timeout, 8),
            )

            if not success:
                return False, message

            rfcomm_result = self._create_rfcomm_connection(mac_address, channel)

            try:
                self.dbus_client.disconnect_device(mac_address)
            except Exception:
                pass

            if rfcomm_result:
                return True, 'Connection successful (BlueZ D-Bus + RFCOMM)'

            return False, (
                f'Bluetooth link is up, but no serial (SPP) service answered on channel {channel}. '
                'Check the channel number - GNSS receivers commonly use 1, but some use 2 or 6. '
                'You can list the advertised channels on the Pi with: sdptool browse ' + str(mac_address)
            )

        except Exception as e:
            return False, str(e)

    def _create_rfcomm_connection(self, mac_address, channel):
        """Create RFCOMM connection for data transfer"""
        try:
            bind_result = _run_privileged_helper(
                ['rfcomm-bind', str(channel), mac_address, str(channel)],
                timeout=10,
            )

            if bind_result.returncode == 0:
                time.sleep(1)
                if os.path.exists(f'/dev/rfcomm{channel}'):
                    _run_privileged_helper(['rfcomm-release', str(channel)], timeout=5)
                    return True
                logger.warning(
                    f'rfcomm-bind reported success but /dev/rfcomm{channel} did not appear'
                )
            else:
                # Surface the real reason (wrong channel, device refusing the
                # connection, adapter busy) instead of a bare False.
                logger.warning(
                    'rfcomm-bind failed for %s channel %s (rc=%s): %s',
                    mac_address, channel, bind_result.returncode,
                    (bind_result.stderr or '').strip() or '(no stderr)'
                )

            return False

        except Exception as e:
            logger.error(f'RFCOMM connection error: {e}')
            return False

    def _main_loop(self):
        """Main loop to manage base station connections"""
        while self.running:
            try:
                with self.app.app_context():
                    base_station_ids = [
                        int(row[0]) for row in db.session.query(BaseStation.id).all()
                    ]

                for station_id in base_station_ids:
                    with self.lock:
                        conn_info = self.connections.get(str(station_id))

                    if (
                        not conn_info
                        or not conn_info.get('thread', None)
                        or not conn_info['thread'].is_alive()
                    ):
                        self._start_station_connection(station_id)

                time.sleep(5)

            except Exception as e:
                logger.error(f'Error in Bluetooth main loop: {e}')
                time.sleep(10)

    def _start_station_connection(self, station_id):
        """Start connection thread for a base station"""
        station = self._load_station_snapshot(station_id)
        if not station:
            return

        connection_type = str(getattr(station, 'connection_type', 'bluetooth') or 'bluetooth').lower()
        endpoint = (
            station.bt_mac
            if connection_type in ('bluetooth', 'ble')
            else getattr(station, 'gnss_port', '')
        )

        thread = threading.Thread(
            target=self._station_loop,
            args=(int(station.id),),
            daemon=True,
            name=f'BT-Station-{station.id}'
        )

        with self.lock:
            self.connections[str(station.id)] = {
                'thread': thread,
                'retry_event': threading.Event(),
                'station_id': int(station.id),
                'station_name': station.name,
                'bt_mac': station.bt_mac,
                'channel': station.channel,
                'connection_type': connection_type,
                'gnss_port': getattr(station, 'gnss_port', ''),
                'baudrate': getattr(station, 'baudrate', 115200),
                'last_attempt': time.time(),
                'connected': False,
                'error_count': 0,
                'reconnect_count': 0,
                'last_error': None,
                'position_mode': str(getattr(station, 'position_mode', '') or '').lower(),
            }

        thread.start()

        logger.info(
            f'Started connection thread for station {station.name} '
            f'({connection_type}: {endpoint})'
        )

    def request_station_connection(self, station_id):
        """Wake the station's own transport worker without opening another link."""
        with self.lock:
            if not self.running:
                return False, 'Base station connection manager is stopped', 'stopped'
            info = self.connections.get(str(int(station_id)), {})
            if info.get('connected'):
                return True, 'Base station is already connected', 'connected'
            retry_event = info.get('retry_event')
            if retry_event is not None:
                retry_event.set()
        # If the worker has not started (or has exited), _main_loop starts it.
        # Do not race that loop by creating a second worker from a web request.
        return True, 'Connection attempt requested. Waiting for the receiver.', 'connecting'

    def _wait_for_station_retry(self, station_id, timeout):
        with self.lock:
            info = self.connections.get(str(int(station_id)), {})
            retry_event = info.get('retry_event')
        if retry_event is None:
            time.sleep(timeout)
        else:
            retry_event.wait(timeout)
            retry_event.clear()

    def _station_loop(self, station_id):
        """Main loop for base station connection using configured transport"""
        normalized_station_id = int(station_id)

        while self.running:
            connection_success = False
            transport = 'bluetooth'
            rfcomm_device = None
            serial_device = None
            ble_device = None
            station = None
            pending_bytes_received = 0
            pending_bytes_sent = 0
            pending_last_seen = 0
            last_db_flush_at = time.time()

            def flush_pending_station_stats(force=False):
                nonlocal pending_bytes_received
                nonlocal pending_bytes_sent
                nonlocal pending_last_seen
                nonlocal last_db_flush_at

                pending_bytes_sent += stream_manager.take_sent_bytes(normalized_station_id)
                if (
                    pending_bytes_received <= 0
                    and pending_bytes_sent <= 0
                    and pending_last_seen <= 0
                ):
                    return True

                now_ts = time.time()
                if not force and (now_ts - last_db_flush_at) < self.db_flush_interval:
                    return False

                if self._apply_station_database_updates(
                    normalized_station_id,
                    last_seen=pending_last_seen or None,
                    bytes_received_delta=pending_bytes_received,
                    bytes_sent_delta=pending_bytes_sent,
                ):
                    pending_bytes_received = 0
                    pending_bytes_sent = 0
                    pending_last_seen = 0
                    last_db_flush_at = now_ts
                    return True

                return False

            try:
                station = self._load_station_snapshot(normalized_station_id)
                if not station:
                    logger.info(
                        f'Base station {normalized_station_id} no longer exists, stopping connection thread'
                    )
                    with self.lock:
                        self.connections.pop(str(normalized_station_id), None)
                    return

                connection_type = str(
                    getattr(station, 'connection_type', 'bluetooth') or 'bluetooth'
                ).strip().lower()
                if connection_type in ('usb', 'usb_serial'):
                    connection_type = 'serial'
                if connection_type in ('ble', 'bluetooth_le', 'bluetooth-le'):
                    connection_type = 'ble'
                if connection_type == 'bluetooth':
                    transport = 'bluetooth'
                elif connection_type == 'ble':
                    transport = 'ble'
                else:
                    transport = 'serial'
                self._update_connection_info(
                    normalized_station_id,
                    station_name=station.name,
                    bt_mac=station.bt_mac,
                    channel=station.channel,
                    connection_type=connection_type,
                    gnss_port=getattr(station, 'gnss_port', ''),
                    baudrate=getattr(station, 'baudrate', 115200),
                    last_attempt=time.time(),
                )

                if transport == 'bluetooth':
                    logger.info(f'Connecting to {station.name} at {station.bt_mac}:{station.channel}')

                    # Neither pairing nor a D-Bus connect is required for a
                    # Serial Port Profile link: the RFCOMM socket below performs
                    # the baseband connection on its own, exactly like a phone
                    # app does. Doing them first was actively harmful - BlueZ
                    # records these dual-mode receivers as LE devices and the
                    # pairing attempt then fails over LE, taking the whole
                    # connection attempt down with it.

                    rfcomm_channel = int(getattr(station, 'channel', 1) or 1)
                    rfcomm_device = RFCOMMSerialConnection(station.bt_mac, rfcomm_channel)
                    rfcomm_ok, rfcomm_message = rfcomm_device.connect()
                    if not rfcomm_ok:
                        try:
                            rfcomm_device.close()
                        except Exception:
                            pass
                        rfcomm_device = None
                        raise Exception(rfcomm_message)

                    logger.info(
                        f'RFCOMM connection established for {station.name}: {rfcomm_message}'
                    )
                elif transport == 'ble':
                    # Bluetooth Low Energy receivers expose their stream over a
                    # GATT UART service instead of RFCOMM; classic pairing is
                    # not required and often not supported at all.
                    logger.info(f'Connecting to {station.name} at {station.bt_mac} over BLE')

                    ble_device = BLESerialConnection(self.dbus_client, station.bt_mac)
                    ble_success, ble_message = ble_device.connect()
                    if not ble_success:
                        try:
                            ble_device.close()
                        except Exception:
                            pass
                        ble_device = None
                        raise Exception(f'BLE connect failed: {ble_message}')

                    logger.info(f'BLE connection established for {station.name}: {ble_message}')
                else:
                    if serial is None:
                        raise Exception('pyserial is not installed, USB/serial mode is unavailable')

                    serial_port = str(getattr(station, 'gnss_port', '') or '').strip()
                    if not serial_port:
                        raise Exception('GNSS serial port is not configured')

                    baudrate = int(getattr(station, 'baudrate', 115200) or 115200)
                    data_bits = int(getattr(station, 'data_bits', 8) or 8)
                    stop_bits = int(getattr(station, 'stop_bits', 1) or 1)
                    parity = str(getattr(station, 'parity', 'N') or 'N').strip().upper()

                    bytesize_map = {
                        7: serial.SEVENBITS,
                        8: serial.EIGHTBITS,
                    }
                    stopbits_map = {
                        1: serial.STOPBITS_ONE,
                        2: serial.STOPBITS_TWO,
                    }
                    parity_map = {
                        'N': serial.PARITY_NONE,
                        'E': serial.PARITY_EVEN,
                        'O': serial.PARITY_ODD,
                    }

                    if data_bits not in bytesize_map:
                        raise Exception('Unsupported serial data bits value')
                    if stop_bits not in stopbits_map:
                        raise Exception('Unsupported serial stop bits value')
                    if parity not in parity_map:
                        raise Exception('Unsupported serial parity value')

                    serial_device = serial.Serial(
                        port=serial_port,
                        baudrate=baudrate,
                        bytesize=bytesize_map[data_bits],
                        stopbits=stopbits_map[stop_bits],
                        parity=parity_map[parity],
                        timeout=1,
                    )
                    logger.info(
                        f'Serial connection established for {station.name} '
                        f'({serial_port} @ {baudrate})'
                    )

                if transport == 'bluetooth':
                    command_device = rfcomm_device
                elif transport == 'ble':
                    command_device = ble_device
                else:
                    command_device = serial_device
                with self.lock:
                    self.device_files[normalized_station_id] = command_device

                # Only push the startup sequence when the configuration has
                # actually changed. It ends with saveconfig, which writes the
                # receiver's flash, and re-runs "mode base" - doing that on
                # every reconnect wears the module and makes it drop the link
                # (the receiver closing the socket is what shows up in the log
                # as "No data received"). A reconnect to an unchanged, already
                # configured receiver needs no commands at all.
                # Ask the receiver what it is. VERSION is read-only - no flash
                # write, no mode change - so unlike the startup sequence it is
                # safe to issue on every connection.
                try:
                    if command_device is not None:
                        command_device.write(b'VERSION\r\n')
                except Exception as version_error:
                    logger.debug(f'VERSION query failed for {station.name}: {version_error}')

                config_signature = self._receiver_config_signature(station)
                with self.lock:
                    previous_signature = self._applied_command_signatures.get(
                        normalized_station_id
                    )
                # NB: do not try to infer "configuration was lost" from a null
                # position. A receiver reports 0,0 whenever it has no fix -
                # indoors, cold start, poor sky view - and re-applying on that
                # basis produced a loop that re-flashed the receiver every few
                # seconds. Firmware changes are detected separately, and the
                # operator always has Apply Config.
                if previous_signature == config_signature:
                    logger.info(
                        f'Receiver configuration for {station.name} is unchanged; '
                        'skipping the startup command sequence'
                    )
                else:
                    self._dispatch_receiver_commands_async(
                        station,
                        command_device,
                        phase='startup',
                    )
                    with self.lock:
                        self._applied_command_signatures[normalized_station_id] = (
                            config_signature
                        )

                self._apply_station_database_updates(
                    normalized_station_id,
                    status='connected',
                    last_seen=int(time.time()),
                )
                self._update_connection_info(
                    normalized_station_id,
                    connected=True,
                    last_success=time.time(),
                    error_count=0,
                    last_error=None,
                )

                connection_success = True
                with self.lock:
                    retry_event = self.connections.get(str(normalized_station_id), {}).get('retry_event')
                    if retry_event is not None:
                        retry_event.clear()
                    # A working link means recovery is no longer in progress.
                    self._adapter_recovery_attempts = 0
                    self._connect_failure_streak[normalized_station_id] = 0
                    if self._adapter_recovery_state.get('status') != 'idle':
                        self._adapter_recovery_state = {
                            'status': 'link_restored', 'attempt': 0,
                            'station_id': normalized_station_id,
                            'updated_at': int(time.time()),
                        }
                notify.send(
                    self.app,
                    f'\U0001f7e2 Base "{station.name}" is online.',
                    event='notify_station_up',
                    event_key=f'station-up-{normalized_station_id}',
                    cooldown=300.0,
                )

                # Discard anything left over from a previous session: a partial
                # frame glued to the start of the new stream would fail CRC.
                stream_manager.reset_stream_buffer(normalized_station_id)

                # Warm the RTCM filter cache once, here, where an application
                # context is cheap - so the per-chunk broadcast path below can
                # run without one.
                try:
                    with self.app.app_context():
                        stream_manager.warm_filter_cache()
                except Exception as warm_error:
                    logger.warning(f'Could not warm the RTCM filter cache: {warm_error}')

                try:
                    with self.app.app_context():
                        if transport == 'bluetooth':
                            endpoint_text = f'{station.bt_mac} via RFCOMM{station.channel}'
                        else:
                            endpoint_text = (
                                f'{getattr(station, "gnss_port", "")} '
                                f'@ {getattr(station, "baudrate", 115200)}'
                            )

                        log_entry = LogEntry(
                            level='INFO',
                            module='bluetooth' if transport == 'bluetooth' else 'serial',
                            message=(
                                f'Connected to base station {station.name} '
                                f'({endpoint_text})'
                            ),
                            timestamp=int(time.time()),
                        )
                        db.session.add(log_entry)
                        db.session.commit()
                except Exception as e:
                    logger.error(f'Error logging connection: {e}')

                consecutive_read_errors = 0

                while self.running and connection_success:
                    try:
                        if transport == 'bluetooth':
                            ready, _, _ = select.select([rfcomm_device], [], [], 1.0)
                            if not ready:
                                continue
                            data = rfcomm_device.read(1024)
                            if not data:
                                logger.warning(
                                    f'No data received from {station.name}, connection may be lost'
                                )
                                break
                        elif transport == 'ble':
                            # BLE data arrives via notifications; read() blocks
                            # up to a second and returns b'' when idle, which is
                            # normal for a receiver between messages. Silence is
                            # only a problem once the link itself is gone.
                            data = ble_device.read(1024, timeout=1.0)
                            if not data:
                                if not ble_device.is_connected:
                                    logger.warning(
                                        f'BLE link to {station.name} dropped, reconnecting'
                                    )
                                    break
                                continue
                        else:
                            data = serial_device.read(1024)
                            if not data:
                                continue

                        self._update_station_telemetry(normalized_station_id, data)

                        # No application context here on purpose. This runs for
                        # every chunk read from the receiver - roughly three
                        # times a second - and creating a Flask context (and
                        # with it a SQLAlchemy session) that often is pure
                        # overhead on a Pi, and competes for the database with
                        # the monitor thread. The filter cache is warmed when
                        # the station connects, so the broadcast path needs no
                        # database access at all.
                        stream_manager.broadcast_stream(
                            normalized_station_id,
                            data,
                        )

                        pending_bytes_received += len(data)
                        pending_last_seen = int(time.time())
                        flush_pending_station_stats(force=False)

                        if len(data) > 100:
                            logger.debug(f'Received {len(data)} bytes from {station.name}')

                    except Exception as e:
                        # Distinguish a dead link from a bad packet: tearing the
                        # session down because one chunk failed to parse causes
                        # a reconnect loop while the radio link is perfectly
                        # healthy. Only give up when the transport itself is
                        # gone.
                        transport_alive = True
                        if transport == 'ble':
                            transport_alive = bool(
                                ble_device
                                and not ble_device._closed
                                and ble_device.is_connected
                            )

                        if transport_alive:
                            consecutive_read_errors += 1
                            logger.warning(
                                f'Error processing data from {station.name} '
                                f'({consecutive_read_errors} in a row): {e}'
                            )
                            if consecutive_read_errors < 10:
                                time.sleep(0.2)
                                continue
                            logger.error(
                                f'Too many consecutive data errors for {station.name}, '
                                'reconnecting'
                            )
                        else:
                            logger.error(f'Error receiving data from {station.name}: {e}')
                        break
                    else:
                        consecutive_read_errors = 0

            except Exception as e:
                flush_pending_station_stats(force=True)
                error_msg = str(e)
                station_name = station.name if station else f'Station {normalized_station_id}'
                logger.error(f'Connection error for {station_name}: {error_msg}')
                self._maybe_recover_bluetooth(normalized_station_id, error_msg)
                notify.send(
                    self.app,
                    self._friendly_station_error(station_name, error_msg),
                    event='notify_station_error',
                    event_key=f'station-unavailable-{normalized_station_id}',
                    cooldown=900.0,
                )

                self._apply_station_database_updates(normalized_station_id, status='error')

                with self.lock:
                    conn_info = self.connections.get(str(normalized_station_id), {})
                    conn_info['connected'] = False
                    conn_info['last_error'] = error_msg
                    conn_info['last_attempt'] = time.time()
                    conn_info['error_count'] = conn_info.get('error_count', 0) + 1

            finally:
                flush_pending_station_stats(force=True)
                if transport == 'bluetooth':
                    command_device = rfcomm_device
                elif transport == 'ble':
                    command_device = ble_device
                else:
                    command_device = serial_device
                with self.lock:
                    current_device = self.device_files.get(normalized_station_id)
                    if current_device is command_device:
                        self.device_files.pop(normalized_station_id, None)

                if command_device and station and connection_success and not self.running:
                    try:
                        with self._get_command_lock(normalized_station_id):
                            command_results = self._send_receiver_commands(
                                station,
                                command_device,
                                phase='shutdown',
                            )
                        if command_results:
                            logger.info(
                                f'Sent {len(command_results)} shutdown receiver commands to {station.name}'
                            )
                    except Exception as shutdown_command_error:
                        logger.warning(
                            f'Unable to send shutdown receiver commands to {station.name}: '
                            f'{shutdown_command_error}'
                        )

                if rfcomm_device:
                    try:
                        rfcomm_device.close()
                    except Exception:
                        pass

                if ble_device:
                    try:
                        ble_device.close()
                    except Exception:
                        pass

                if serial_device:
                    try:
                        serial_device.close()
                    except Exception:
                        pass

                if transport == 'bluetooth' and station:
                    try:
                        _run_privileged_helper(['rfcomm-release', str(station.channel)], timeout=5)
                    except Exception:
                        pass

                    try:
                        self.dbus_client.disconnect_device(station.bt_mac)
                    except Exception:
                        pass

                if connection_success and station:
                    logger.warning(f'Lost connection to {station.name}, will retry in 5 seconds')
                    notify.send(
                        self.app,
                        f'\U0001f534 Base "{station.name}" went offline. Trying to reconnect...',
                        event='notify_station_down',
                        event_key=f'station-unavailable-{normalized_station_id}',
                        cooldown=900.0,
                    )

                    self._apply_station_database_updates(
                        normalized_station_id,
                        status='disconnected',
                    )
                    self._increment_connection_counter(normalized_station_id, 'reconnect_count')
                    self._update_connection_info(
                        normalized_station_id,
                        connected=False,
                    )

                    try:
                        with self.app.app_context():
                            log_entry = LogEntry(
                                level='WARNING',
                                module='bluetooth' if transport == 'bluetooth' else 'serial',
                                message=f'Lost connection to base station {station.name}',
                                timestamp=int(time.time()),
                            )
                            db.session.add(log_entry)
                            db.session.commit()
                    except Exception as e:
                        logger.error(f'Error logging disconnection: {e}')

            error_count = 0
            with self.lock:
                if str(normalized_station_id) in self.connections:
                    error_count = self.connections[str(normalized_station_id)].get('error_count', 0)
                else:
                    return

            wait_time = min(5 + (error_count * 2), 30)
            self._wait_for_station_retry(normalized_station_id, wait_time)

    def _ensure_device_paired(self, mac_address):
        """Ensure device is paired and trusted via D-Bus"""
        try:
            success, message = self.dbus_client.pair_and_trust(
                mac_address,
                timeout=30,
                scan_timeout=10,
            )
            if not success:
                logger.warning(f'Pair/trust warning for {mac_address}: {message}')
        except Exception as e:
            logger.error(f'Error ensuring device is paired: {e}')

    @staticmethod
    def _safe_int(raw_value, default_value=None):
        try:
            if raw_value is None or raw_value == '':
                return default_value
            return int(raw_value)
        except (TypeError, ValueError):
            return default_value

    @staticmethod
    def _safe_float(raw_value, default_value=None):
        try:
            if raw_value is None or raw_value == '':
                return default_value
            return float(raw_value)
        except (TypeError, ValueError):
            return default_value

    @staticmethod
    def _format_nmea_time(raw_value):
        value = str(raw_value or '').strip()
        if len(value) < 6:
            return ''
        return f'{value[0:2]}:{value[2:4]}:{value[4:6]}'

    @staticmethod
    def _parse_nmea_coordinate(raw_value, hemisphere):
        value = str(raw_value or '').strip()
        direction = str(hemisphere or '').strip().upper()
        if not value or direction not in ('N', 'S', 'E', 'W'):
            return None

        degree_digits = 2 if direction in ('N', 'S') else 3
        if len(value) <= degree_digits:
            return None

        try:
            degrees = float(value[:degree_digits])
            minutes = float(value[degree_digits:])
            decimal_value = degrees + (minutes / 60.0)
            if direction in ('S', 'W'):
                decimal_value *= -1.0
            return decimal_value
        except (TypeError, ValueError):
            return None

    @staticmethod
    def _describe_fix_quality(code):
        # NMEA 0183 GGA field 6. The previous table was missing several valid
        # values (notably 3 and 7), so a receiver reporting them showed as
        # "Unknown" even though it had a perfectly good fix.
        return {
            0: 'No Fix',
            1: 'GPS Fix',
            2: 'DGPS',
            3: 'PPS Fix',
            4: 'RTK Fixed',
            5: 'RTK Float',
            6: 'Estimated',
            7: 'Manual Input',
            8: 'Simulation',
            9: 'SBAS/WAAS',
        }.get(code, f'Unknown ({code})' if code is not None else 'Unknown')

    @staticmethod
    def _describe_fix_type(code):
        return {
            1: 'No Fix',
            2: '2D',
            3: '3D',
        }.get(code, 'Unknown')

    @staticmethod
    def _verify_nmea_checksum(sentence):
        text = str(sentence or '').strip()
        if not text.startswith('$') or '*' not in text:
            return False

        body, checksum_text = text[1:].split('*', 1)
        checksum_text = checksum_text[:2]
        if len(checksum_text) != 2:
            return False

        checksum_value = 0
        for character in body:
            checksum_value ^= ord(character)

        return checksum_text.upper() == f'{checksum_value:02X}'

    def _get_station_telemetry_entry(self, station_id):
        normalized_station_id = int(station_id)
        with self.telemetry_lock:
            entry = self.telemetry.get(normalized_station_id)
            if entry is None:
                entry = {
                    'last_data_at': 0.0,
                    'last_nmea_at': 0.0,
                    'data_rate_bps': 0.0,
                    'has_nmea': False,
                    'utc_time': '',
                    'fix_quality_code': None,
                    'fix_quality': 'Unknown',
                    'fix_type_code': None,
                    'fix_type': 'Unknown',
                    'satellites_used': None,
                    'satellites_visible': None,
                    'satellites_visible_by_talker': {},
                    'hdop': None,
                    'vdop': None,
                    'pdop': None,
                    'latitude': None,
                    'longitude': None,
                    'altitude_m': None,
                    'speed_kmh': None,
                    'last_sentence_types': [],
                    'rate_history': [],
                    'rate_history_last_sample_at': 0.0,
                }
                self.telemetry[normalized_station_id] = entry

            if normalized_station_id not in self.nmea_buffers:
                self.nmea_buffers[normalized_station_id] = ''

            if normalized_station_id not in self.byte_history:
                self.byte_history[normalized_station_id] = deque()

            return entry

    def _update_station_data_rate(self, station_id, byte_count, timestamp_value):
        history = self.byte_history.setdefault(int(station_id), deque())
        history.append((float(timestamp_value), int(byte_count)))

        cutoff = float(timestamp_value) - 10.0
        while history and history[0][0] < cutoff:
            history.popleft()

        total_bytes = sum(item[1] for item in history)
        if len(history) > 1:
            duration = max(1.0, history[-1][0] - history[0][0])
        else:
            duration = 1.0

        return float(total_bytes) / float(duration)

    def _sample_rate_history(self, entry, now_ts, sample_interval=2.0, max_samples=60):
        """Append a coarse-grained data-rate sample for the detail-page sparkline.

        Telemetry updates can arrive many times per second; sampling on a
        fixed interval keeps the history compact (~2 minutes of trend at the
        default settings) while callers must already hold telemetry_lock.
        """
        last_sample_at = float(entry.get('rate_history_last_sample_at') or 0.0)
        if last_sample_at and (now_ts - last_sample_at) < sample_interval:
            return

        rate_history = entry.setdefault('rate_history', [])
        rate_history.append({
            't': round(now_ts, 1),
            'r': round(float(entry.get('data_rate_bps') or 0.0), 1),
        })

        overflow = len(rate_history) - max_samples
        if overflow > 0:
            del rate_history[:overflow]

        entry['rate_history_last_sample_at'] = now_ts

    def _remember_sentence_type(self, entry, sentence_type):
        sentence = str(sentence_type or '').upper()
        if not sentence:
            return

        sentence_types = list(entry.get('last_sentence_types') or [])
        if sentence in sentence_types:
            sentence_types.remove(sentence)
        sentence_types.append(sentence)
        entry['last_sentence_types'] = sentence_types[-5:]

    def _apply_nmea_sentence(self, station_id, sentence):
        if not self._verify_nmea_checksum(sentence):
            return

        body = sentence[1:].split('*', 1)[0]
        fields = body.split(',')
        if not fields:
            return

        message_id = str(fields[0] or '').upper()
        # The talker + sentence identifier is always 5 alphanumeric characters
        # (e.g. GNGGA, GPGST). Binary RTCM payload regularly contains a 0x24
        # ('$') byte, and without this check those bytes were parsed as NMEA -
        # which is where the garbage sentence types like 'T' or 'I"' came from.
        if len(message_id) != 5 or not message_id.isalnum():
            return

        sentence_type = message_id[-3:]
        now_ts = time.time()

        with self.telemetry_lock:
            entry = self._get_station_telemetry_entry(station_id)
            entry['has_nmea'] = True
            entry['last_nmea_at'] = now_ts
            self._remember_sentence_type(entry, sentence_type)

            if sentence_type == 'GGA':
                entry['utc_time'] = self._format_nmea_time(fields[1] if len(fields) > 1 else '')
                latitude = self._parse_nmea_coordinate(
                    fields[2] if len(fields) > 2 else '',
                    fields[3] if len(fields) > 3 else '',
                )
                longitude = self._parse_nmea_coordinate(
                    fields[4] if len(fields) > 4 else '',
                    fields[5] if len(fields) > 5 else '',
                )
                if latitude is not None:
                    entry['latitude'] = latitude
                if longitude is not None:
                    entry['longitude'] = longitude

                fix_quality_code = self._safe_int(fields[6] if len(fields) > 6 else '', None)
                if fix_quality_code is not None:
                    entry['fix_quality_code'] = fix_quality_code
                    entry['fix_quality'] = self._describe_fix_quality(fix_quality_code)

                satellites_used = self._safe_int(fields[7] if len(fields) > 7 else '', None)
                if satellites_used is not None:
                    entry['satellites_used'] = satellites_used

                hdop_value = self._safe_float(fields[8] if len(fields) > 8 else '', None)
                if hdop_value is not None:
                    entry['hdop'] = hdop_value

                altitude_value = self._safe_float(fields[9] if len(fields) > 9 else '', None)
                if altitude_value is not None:
                    entry['altitude_m'] = altitude_value

            elif sentence_type == 'GSA':
                fix_type_code = self._safe_int(fields[2] if len(fields) > 2 else '', None)
                if fix_type_code is not None:
                    entry['fix_type_code'] = fix_type_code
                    entry['fix_type'] = self._describe_fix_type(fix_type_code)

                # GSA is sent once per constellation, so its PRN count covers
                # only that constellation. GGA field 7 already carries the total
                # across all systems, so only fall back to counting PRNs when no
                # GGA total has been seen - otherwise a 4-satellite GLONASS GSA
                # would overwrite a perfectly good "28 used" from GGA.
                prn_values = [value for value in fields[3:15] if str(value or '').strip()]
                if prn_values and entry.get('satellites_used') is None:
                    entry['satellites_used'] = len(prn_values)

                pdop_value = self._safe_float(fields[15] if len(fields) > 15 else '', None)
                hdop_value = self._safe_float(fields[16] if len(fields) > 16 else '', None)
                vdop_value = self._safe_float(fields[17] if len(fields) > 17 else '', None)
                if pdop_value is not None:
                    entry['pdop'] = pdop_value
                if hdop_value is not None:
                    entry['hdop'] = hdop_value
                if vdop_value is not None:
                    entry['vdop'] = vdop_value

            elif sentence_type == 'GSV':
                # GSV reports satellites in view *per constellation* (GPGSV for
                # GPS, GLGSV for GLONASS, GAGSV for Galileo, GBGSV for BeiDou),
                # each split across several messages. Keeping only the latest
                # value showed one constellation's count - typically 1 or 2 -
                # instead of the total, so track them per talker and sum.
                satellites_visible = self._safe_int(fields[3] if len(fields) > 3 else '', None)
                if satellites_visible is not None:
                    talker = message_id[:2]
                    per_talker = entry.get('satellites_visible_by_talker')
                    if not isinstance(per_talker, dict):
                        per_talker = {}
                    per_talker[talker] = satellites_visible
                    entry['satellites_visible_by_talker'] = per_talker
                    entry['satellites_visible'] = sum(per_talker.values())

            elif sentence_type == 'RMC':
                entry['utc_time'] = self._format_nmea_time(fields[1] if len(fields) > 1 else '')
                # RMC is the only sentence we request that carries a date, so it
                # is what makes GNSS-derived time possible at all.
                self._maybe_sync_clock_from_gnss(
                    fields[1] if len(fields) > 1 else '',
                    fields[9] if len(fields) > 9 else '',
                    fields[2] if len(fields) > 2 else '',
                )
                if len(fields) > 2 and fields[2] == 'A':
                    latitude = self._parse_nmea_coordinate(
                        fields[3] if len(fields) > 3 else '',
                        fields[4] if len(fields) > 4 else '',
                    )
                    longitude = self._parse_nmea_coordinate(
                        fields[5] if len(fields) > 5 else '',
                        fields[6] if len(fields) > 6 else '',
                    )
                    if latitude is not None:
                        entry['latitude'] = latitude
                    if longitude is not None:
                        entry['longitude'] = longitude

                speed_knots = self._safe_float(fields[7] if len(fields) > 7 else '', None)
                if speed_knots is not None:
                    entry['speed_kmh'] = speed_knots * 1.852

    def _update_station_telemetry(self, station_id, data):
        normalized_station_id = int(station_id or 0)
        if normalized_station_id <= 0:
            return

        now_ts = time.time()

        with self.telemetry_lock:
            entry = self._get_station_telemetry_entry(normalized_station_id)
            entry['last_data_at'] = now_ts
            entry['data_rate_bps'] = self._update_station_data_rate(
                normalized_station_id,
                len(data),
                now_ts,
            )
            self._sample_rate_history(entry, now_ts)

            text_chunk = data.decode('ascii', errors='ignore')
            if not text_chunk:
                return

            buffer_text = self.nmea_buffers.get(normalized_station_id, '') + text_chunk
            if len(buffer_text) > 4096:
                buffer_text = buffer_text[-4096:]

            lines = buffer_text.split('\n')
            self.nmea_buffers[normalized_station_id] = lines[-1][-512:] if lines else ''
            candidate_lines = lines[:-1]

        for raw_line in candidate_lines:
            line = raw_line.strip()
            if not line:
                continue
            # Tee every readable line into the console buffer. The receiver
            # console used to read the device object directly, which stole
            # bytes from the RTCM stream feeding the rovers; it now consumes
            # this copy instead.
            self._append_console_line(normalized_station_id, line)
            if line.startswith('#VERSION,'):
                self._record_receiver_version(normalized_station_id, line)
            if '$' in line and not line.startswith('$'):
                line = line[line.find('$'):]
            if not line.startswith('$'):
                continue
            self._apply_nmea_sentence(normalized_station_id, line)

    @property
    def gnss_time_sync_enabled(self):
        """Whether to take the host clock from the receiver (a stored setting)."""
        cached_value, cached_at = self._time_sync_cache
        now_ts = time.time()
        if now_ts - cached_at < self._time_sync_cache_seconds:
            return cached_value

        enabled = False
        try:
            if self.app:
                from app.db.models import SystemSetting, db

                with self.app.app_context():
                    row = SystemSetting.query.filter_by(key='gnss_time_sync').first()
                    enabled = str(row.value if row else '').strip().lower() in (
                        '1', 'true', 'yes', 'on'
                    )
                    db.session.remove()
        except Exception:
            enabled = cached_value

        self._time_sync_cache = (enabled, now_ts)
        return enabled

    def _maybe_sync_clock_from_gnss(self, raw_time, raw_date, status):
        """Set the host clock from GNSS time when asked to.

        A Raspberry Pi has no battery-backed clock: away from the internet it
        boots with whatever time it saved last, which makes every log entry,
        command record and backup name wrong. The receiver knows UTC to the
        microsecond, so on a field deployment it is the better source. Off by
        default - a host with working NTP should not have its clock touched.
        """
        if not self.gnss_time_sync_enabled:
            return
        if str(status or '').strip().upper() != 'A':
            return  # navigation data not valid yet

        raw_time = str(raw_time or '').strip()
        raw_date = str(raw_date or '').strip()
        if len(raw_time) < 6 or len(raw_date) != 6:
            return

        now_ts = time.time()
        if now_ts - self._last_clock_sync_at < self.gnss_time_sync_interval:
            return

        try:
            day = int(raw_date[0:2])
            month = int(raw_date[2:4])
            year = 2000 + int(raw_date[4:6])
            hour = int(raw_time[0:2])
            minute = int(raw_time[2:4])
            second = int(float(raw_time[4:]))
            gnss_moment = datetime(year, month, day, hour, minute, second, tzinfo=timezone.utc)
        except (TypeError, ValueError):
            return

        drift = abs(gnss_moment.timestamp() - now_ts)
        if drift < self.gnss_time_sync_threshold:
            self._last_clock_sync_at = now_ts
            return

        self._last_clock_sync_at = now_ts
        stamp = gnss_moment.strftime('%Y-%m-%d %H:%M:%S')
        try:
            result = _run_privileged_helper(['set-system-clock', stamp], timeout=10)
            if result.returncode == 0:
                logger.warning(
                    f'System clock was {drift:.0f}s off; set to {stamp} UTC from GNSS'
                )
            else:
                logger.warning(
                    f'Could not set the system clock: {(result.stderr or "").strip()[:120]}'
                )
        except Exception as clock_error:
            logger.warning(f'Clock synchronisation failed: {clock_error}')

    def _record_receiver_version(self, station_id, line):
        """Parse a Unicore VERSION reply and store what it tells us.

        The reply looks like:
          #VERSION,98,GPS,FINE,...;UM980,R4.10Build13504,HRPT00-S10C-P,
          2310415000001-MD22A...,ff33c876188bc52e,2024/04/03*b6028917

        Everything after the semicolon is the interesting part: model,
        firmware build, hardware id, serial and build date.
        """
        try:
            payload = line.split(';', 1)[1].split('*', 1)[0]
        except IndexError:
            return

        fields = [part.strip() for part in payload.split(',')]
        if len(fields) < 2:
            return

        model = fields[0][:64]
        firmware = fields[1][:64]
        serial = fields[3][:64] if len(fields) > 3 else ''
        build_date = ''
        for field in reversed(fields):
            if re.fullmatch(r'\d{4}/\d{2}/\d{2}', field):
                build_date = field
                break

        with self.lock:
            previous = self._reported_versions.get(station_id)
        current = (model, firmware, build_date, serial)
        if previous == current:
            return
        with self.lock:
            self._reported_versions[station_id] = current
            # A firmware change wipes the receiver's saved configuration, so the
            # startup sequence must be pushed again even though our settings did
            # not change. Forgetting the applied signature forces that.
            if previous is not None and previous[1] != firmware:
                self._applied_command_signatures.pop(station_id, None)
                logger.warning(
                    f'Station {station_id} firmware changed '
                    f'({previous[1]} -> {firmware}); receiver configuration will be re-applied'
                )

        logger.info(
            f'Receiver on station {station_id}: {model} firmware {firmware} '
            f'({build_date or "date unknown"})'
        )
        if not self.app:
            return
        try:
            with self.app.app_context():
                station = db.session.get(BaseStation, int(station_id))
                if station is None:
                    return
                station.receiver_model = model
                station.firmware_version = firmware
                station.firmware_date = build_date
                station.receiver_serial = serial
                db.session.commit()
                db.session.remove()
        except Exception as store_error:
            logger.warning(f'Could not store receiver version: {store_error}')

    def _append_console_line(self, station_id, line):
        """Store a line of receiver output for the web console."""
        try:
            normalized_station_id = int(station_id)
        except (TypeError, ValueError):
            return
        with self.lock:
            queue = self.console_buffers.get(normalized_station_id)
            if queue is None:
                queue = deque(maxlen=500)
                self.console_buffers[normalized_station_id] = queue
            self._console_sequence += 1
            queue.append((self._console_sequence, str(line)[:512]))

    def read_console_lines(self, station_id, after_sequence=0, limit=200):
        """Lines newer than after_sequence: (sequence, [lines])."""
        try:
            normalized_station_id = int(station_id)
        except (TypeError, ValueError):
            return after_sequence, []
        with self.lock:
            queue = self.console_buffers.get(normalized_station_id)
            if not queue:
                return after_sequence, []
            pending = [item for item in queue if item[0] > after_sequence]
        if not pending:
            return after_sequence, []
        pending = pending[-limit:]
        return pending[-1][0], [text for _, text in pending]

    def _get_station_telemetry_snapshot(self, station_id):
        now_ts = time.time()
        normalized_station_id = int(station_id)

        with self.telemetry_lock:
            raw_entry = self.telemetry.get(normalized_station_id)
            if raw_entry is None:
                entry = {}
            else:
                entry = dict(raw_entry)
                entry['rate_history'] = list(raw_entry.get('rate_history') or [])

        if not entry:
            return {
                'available': False,
                'has_nmea': False,
                'data_rate_bps': 0.0,
                'last_data_at': 0.0,
                'last_nmea_at': 0.0,
                'last_sentence_types': [],
                'rate_history': [],
            }

        last_data_at = float(entry.get('last_data_at') or 0.0)
        if last_data_at <= 0 or (now_ts - last_data_at) > 5.0:
            entry['data_rate_bps'] = 0.0

        entry['available'] = True
        return entry

    @staticmethod
    def _format_receiver_decimal(value, precision):
        try:
            formatted = f'{float(value):.{precision}f}'
            formatted = formatted.rstrip('0').rstrip('.')
            return formatted or '0'
        except (TypeError, ValueError):
            return '0'

    def _get_enabled_startup_rtcm_message_types(self):
        default_enabled = set(get_default_enabled_rtcm_message_types())
        managed_types = list(get_receiver_startup_message_types())

        if not self.app:
            return default_enabled

        try:
            with self.app.app_context():
                settings = RTCMSetting.query.filter(
                    RTCMSetting.msg_type.in_(managed_types)
                ).all()
        except Exception as settings_error:
            logger.warning(
                f'Unable to read global RTCM settings for receiver defaults: {settings_error}'
            )
            return default_enabled

        if not settings:
            return default_enabled

        return {int(setting.msg_type) for setting in settings if bool(setting.enabled)}

    def get_receiver_command_defaults(self, station):
        return {
            'startup': '\n'.join(self._build_default_receiver_commands(station, phase='startup')),
            'shutdown': '\n'.join(self._build_default_receiver_commands(station, phase='shutdown')),
        }

    def _build_default_receiver_commands(self, station, phase='startup'):
        output_interval = max(1, int(getattr(station, 'output_interval', 1) or 1))
        operation_mode = str(getattr(station, 'operation_mode', 'base') or 'base').strip().lower()
        position_mode = str(getattr(station, 'position_mode', 'auto') or 'auto').strip().lower()
        receiver_brand = str(getattr(station, 'receiver_brand', 'comnav') or 'comnav').strip().lower()
        survey_duration_sec = max(15, min(300, int(getattr(station, 'survey_duration_sec', 30) or 30)))

        # Unicore UM980 (DIY-GNSS-MINI) uses the same NovAtel-style ASCII command
        # dialect as ComNav (mode base / rtcm10xx / unlog / saveconfig), so it
        # shares the generated-command path below. Treated as an explicit brand
        # for UI clarity while reusing the identical command generation.
        if receiver_brand in ('unicore', 'um980'):
            receiver_brand = 'comnav'

        if receiver_brand == 'ublox':
            # u-blox configuration is not ASCII command compatible with the
            # ComNav/NavX-style pipeline. Keep generated commands empty so the
            # user must choose a dedicated backend strategy or expert mode.
            return []

        if receiver_brand == 'generic_nmea':
            if phase == 'shutdown' or operation_mode == 'rover':
                return [
                    'gngga 1',
                    'gngsa 2',
                    'gngsv 2',
                    'gpgst 1',
                ]
            return [
                'gngga 1',
                'gngsa 2',
                'gngsv 2',
                'gpgst 1',
            ]

        if phase == 'shutdown':
            return [
                'mode rover survey',
                'gngga 1',
                'gngsa 2',
                'gngsv 2',
                'gpgst 1',
                'saveconfig',
            ]

        if operation_mode == 'rover':
            return [
                'mode rover survey',
                'gngga 1',
                'gngsa 2',
                'gngsv 2',
                'gpgst 1',
                'saveconfig',
            ]

        if position_mode == 'manual':
            # "mode base" carries a single height and the receiver treats it as
            # its antenna phase centre - there is no separate antenna-height
            # command. Whether the operator's altitude already includes the
            # antenna or refers to the ground mark depends on how the point was
            # surveyed, so this is a switch rather than a hard rule. With it on,
            # only the antenna height changes when the tripod changes; the mark
            # height stays put.
            try:
                base_altitude = float(getattr(station, 'manual_alt', 0.0) or 0.0)
            except (TypeError, ValueError):
                base_altitude = 0.0

            if self._is_true(getattr(station, 'add_antenna_height', False)):
                try:
                    base_altitude += float(getattr(station, 'antenna_height', 0.0) or 0.0)
                except (TypeError, ValueError):
                    pass

            mode_command = (
                'mode base '
                f'{self._format_receiver_decimal(getattr(station, "manual_lat", 0.0), 8)} '
                f'{self._format_receiver_decimal(getattr(station, "manual_lon", 0.0), 8)} '
                f'{self._format_receiver_decimal(base_altitude, 3)}'
            )
        else:
            mode_command = f'mode base time {survey_duration_sec}'

        enabled_rtcm_types = self._get_enabled_startup_rtcm_message_types()
        rtcm_commands = build_receiver_rtcm_commands(
            enabled_message_types=enabled_rtcm_types,
            output_interval=output_interval,
        )

        # NMEA output is only used to populate the telemetry panel; RTCM is what
        # rovers actually need. A BLE UART module (HM-10 class) tops out around
        # 1-3 KB/s, and asking for the full NMEA set on top of the RTCM stream
        # overruns it - the link then drops mid-stream. Keep GGA (position) and
        # drop the chatty ones on that transport.
        connection_type = str(
            getattr(station, 'connection_type', 'bluetooth') or 'bluetooth'
        ).strip().lower()

        if connection_type == 'ble':
            nmea_commands = ['gngga 1']
        else:
            nmea_commands = ['gngga 1', 'gngsa 2', 'gngsv 2', 'gpgst 1']

        # RMC carries the date, which GGA does not, so it is only worth its
        # bandwidth when the host is taking its clock from the receiver.
        if self.gnss_time_sync_enabled:
            nmea_commands.append('gnrmc 1')

        return [
            'unlog com1',
            'unlog com2',
            'unlog com3',
            mode_command,
            *rtcm_commands,
            *nmea_commands,
            'saveconfig',
        ]

    def _get_receiver_commands(self, station, phase='startup'):
        command_strategy = str(
            getattr(station, 'command_strategy', 'generated') or 'generated'
        ).strip().lower()
        if command_strategy not in ('generated', 'overrides', 'replace'):
            command_strategy = 'generated'

        raw_commands = getattr(
            station,
            'startup_commands' if phase == 'startup' else 'shutdown_commands',
            '',
        )
        normalized = str(raw_commands or '').replace('\r\n', '\n').replace('\r', '\n')
        commands = []
        for command in normalized.split('\n'):
            cleaned = command.strip()
            if not cleaned or cleaned.startswith('#'):
                continue
            commands.append(cleaned)

        generated_commands = self._build_default_receiver_commands(station, phase=phase)

        if command_strategy == 'replace':
            # An explicitly empty list means "send nothing": the receiver is
            # already configured and re-sending a startup burst on every
            # reconnect is what floods fragile BLE links.
            return commands

        if command_strategy == 'overrides':
            return generated_commands + commands

        return generated_commands

    def _write_receiver_command_lines(self, station, device, commands, phase='manual'):
        if not device or not hasattr(device, 'write'):
            return []

        station_id = int(getattr(station, 'id', 0) or 0)
        command_results = []
        log_entries = []  # batch CommandLog writes
        # Start reading replies from whatever the console buffer holds now, so
        # earlier output is not mistaken for an answer.
        response_sequence, _ = self.read_console_lines(station_id, after_sequence=0)

        for command in commands:
            command = str(command or '').strip()
            if not command or command.startswith('#'):
                continue

            payload = f'{command}\r\n'.encode('ascii', errors='ignore')
            if not payload:
                continue

            written = device.write(payload)
            if hasattr(device, 'flush'):
                device.flush()

            # A BLE write returns 0 when the link has gone away. Continuing to
            # push the remaining commands is pointless (and used to be reported
            # as success), so stop and let the station loop reconnect.
            if written == 0 and payload:
                logger.warning(
                    f'Stopping {phase} command sequence for {station.name}: '
                    f'the link dropped while sending "{command}"'
                )
                break

            # Pacing depends on the transport. A BLE module has a tiny input
            # buffer and drops the link when flooded, so it needs real spacing.
            # Classic RFCOMM has orders of magnitude more headroom - using the
            # BLE delay there made a 16-command sequence take ~22 seconds and
            # left the UI waiting on a stale status.
            if isinstance(device, BLESerialConnection):
                time.sleep(0.6)
            else:
                time.sleep(0.12)

            response_sequence, responses = self._read_receiver_command_responses(
                station_id, response_sequence, timeout=0.35
            )
            combined_response = '\n'.join(responses).strip()
            command_results.append({
                'command': command,
                'responses': responses,
                'response_text': combined_response,
                'has_response': bool(responses),
            })
            log_entries.append({'command': command, 'response': combined_response})
            logger.info(f'Sent {phase} receiver command to {station.name}: {command}')
            if combined_response:
                logger.info(
                    f'Receiver response for {station.name} after {phase} command {command}: {combined_response}'
                )

        # Persist command history to DB in background — don't block the response
        if log_entries and self.app and station_id:
            _phase = phase
            _sid   = station_id
            _app   = self.app

            def _persist():
                try:
                    with _app.app_context():
                        for entry in log_entries:
                            db.session.add(CommandLog(
                                station_id=_sid,
                                phase=_phase,
                                command=entry['command'],
                                response=entry['response'],
                            ))
                        db.session.commit()
                except Exception as cl_err:
                    logger.debug(f'CommandLog persist failed: {cl_err}')

            import threading as _threading
            _threading.Thread(target=_persist, daemon=True,
                              name=f'BT-CmdLog-{station_id}').start()

        return command_results

    def _send_receiver_commands(self, station, device, phase='startup'):
        commands = self._get_receiver_commands(station, phase=phase)
        if not commands:
            return []

        return self._write_receiver_command_lines(
            station,
            device,
            commands,
            phase=phase,
        )

    @staticmethod
    def _is_true(value):
        return str(value).strip().lower() in ('1', 'true', 'yes', 'on')

    def _receiver_config_signature(self, station):
        """Fingerprint of everything that affects the startup command list.

        When this is unchanged the receiver is already configured the way we
        want it, so a reconnect can skip re-sending (and re-flashing) it.
        """
        try:
            commands = self._get_receiver_commands(station, phase='startup')
        except Exception:
            # If the list cannot be built, never claim it is unchanged.
            return None
        return '\n'.join(str(command) for command in commands)

    def _dispatch_receiver_commands_async(self, station, device, phase='startup'):
        station_id = int(getattr(station, 'id', 0) or 0)
        station_name = str(getattr(station, 'name', f'Station {station_id}') or f'Station {station_id}')

        def _runner():
            try:
                with self._get_command_lock(station_id):
                    command_results = self._send_receiver_commands(station, device, phase=phase)
                if command_results:
                    logger.info(
                        f'Sent {len(command_results)} {phase} receiver commands to {station_name}'
                    )
            except Exception as command_error:
                logger.warning(
                    f'Unable to send {phase} receiver commands to {station_name}: {command_error}'
                )

        command_thread = threading.Thread(
            target=_runner,
            daemon=True,
            name=f'BT-Cmd-{station_id}-{phase}'
        )
        command_thread.start()
        return command_thread

    def apply_receiver_config_to_station(self, station_id):
        normalized_station_id = int(station_id)
        # An explicit "Apply Config" always pushes the sequence, so forget any
        # cached signature: the operator asked for it deliberately.
        with self.lock:
            self._applied_command_signatures.pop(normalized_station_id, None)
        with self.lock:
            device = self.device_files.get(normalized_station_id)
            conn_info = dict(self.connections.get(str(normalized_station_id), {}) or {})

        if not device or not conn_info.get('connected'):
            return False, 'Base station has no active receiver connection', []

        station = self._load_station_snapshot(normalized_station_id)
        if not station:
            return False, 'Base station not found', []

        try:
            with self._get_command_lock(normalized_station_id):
                command_results = self._send_receiver_commands(station, device, phase='startup')
            return True, f'Applied {len(command_results)} startup command(s)', command_results
        except Exception as apply_error:
            logger.error(
                f'Unable to apply receiver config to base station {normalized_station_id}: {apply_error}'
            )
            return False, str(apply_error), []

    def send_receiver_commands_to_station(self, station_id, commands, phase='manual-test'):
        normalized_station_id = int(station_id)
        normalized_commands = []
        for command in commands or []:
            cleaned = str(command or '').strip()
            if cleaned and not cleaned.startswith('#'):
                normalized_commands.append(cleaned)

        if not normalized_commands:
            return False, 'No receiver commands to send', 0

        with self.lock:
            device = self.device_files.get(normalized_station_id)
            conn_info = dict(self.connections.get(str(normalized_station_id), {}) or {})

        if not device or not conn_info.get('connected'):
            return False, 'Base station has no active receiver connection', 0

        station = self._load_station_snapshot(normalized_station_id)
        if not station:
            return False, 'Base station not found', 0

        try:
            with self._get_command_lock(normalized_station_id):
                command_results = self._write_receiver_command_lines(
                    station,
                    device,
                    normalized_commands,
                    phase=phase,
                )
            sent_count = len(command_results)
            return True, f'Sent {sent_count} receiver command(s)', sent_count, command_results
        except Exception as send_error:
            logger.error(
                f'Unable to send manual receiver commands to base station '
                f'{normalized_station_id}: {send_error}'
            )
            return False, str(send_error), 0, []

    def forward_gga_to_station(self, station_id, gga_sentence):
        """Forward a rover's NMEA GGA sentence to the base receiver (Fix #9).

        Network-RTK / VRS receivers need the rover's approximate position (sent
        as a standard $GxGGA sentence) to compute an interpolated correction
        stream. NTRIP clients push GGA back up the same TCP connection; the
        NTRIP server hands it here so we can write it to the physical receiver.

        This is intentionally lightweight and best-effort:
          • It reuses the per-station command lock so it never interleaves with
            a startup/shutdown command batch mid-write.
          • It does NOT read a response (GGA input is fire-and-forget).
          • It rate-limits to at most one GGA per second per station to avoid
            flooding the receiver if a rover misbehaves.
          • It silently no-ops when the station has no live device or the
            receiver isn't in a VRS/network position mode.
        """
        normalized_station_id = int(station_id)
        sentence = str(gga_sentence or '').strip()

        # Basic validation: must look like a GGA sentence.
        if not sentence.startswith('$') or 'GGA' not in sentence[:7]:
            return False

        # Per-station rate limit (1 GGA/sec).
        now_ts = time.time()
        with self.lock:
            last_gga = self._last_gga_forward.get(normalized_station_id, 0.0)
            if (now_ts - last_gga) < 1.0:
                return False
            self._last_gga_forward[normalized_station_id] = now_ts
            device = self.device_files.get(normalized_station_id)
            conn_info = dict(self.connections.get(str(normalized_station_id), {}) or {})

        if not device or not hasattr(device, 'write') or not conn_info.get('connected'):
            return False

        # Only forward when the receiver is configured for a network/VRS
        # position mode – forwarding GGA to a fixed base is pointless and could
        # confuse some firmware.
        position_mode = str(conn_info.get('position_mode', '') or '').lower()
        if position_mode and position_mode not in ('vrs', 'network', 'rover', 'auto'):
            return False

        payload = sentence
        if not payload.endswith('\r\n'):
            payload += '\r\n'
        payload_bytes = payload.encode('ascii', errors='ignore')

        try:
            with self._get_command_lock(normalized_station_id):
                device.write(payload_bytes)
                if hasattr(device, 'flush'):
                    device.flush()
            logger.debug(
                f"Forwarded rover GGA to station {normalized_station_id}: {sentence[:60]}"
            )
            return True
        except Exception as gga_error:
            logger.debug(
                f"Failed to forward GGA to station {normalized_station_id}: {gga_error}"
            )
            return False
    
    @staticmethod
    def _friendly_station_error(station_name, error_message):
        """Say what happened and what to do, not what the socket returned.

        The raw text is written for someone reading a log; the notification is
        read on a phone, often by whoever is standing next to the tripod.
        """
        lowered = str(error_message or '').lower()

        if 'host is down' in lowered or 'not found' in lowered:
            advice = 'The receiver is not responding. Check it is powered on and in range.'
        elif 'timed out' in lowered or 'timeout' in lowered:
            advice = 'The receiver stopped answering. It may be out of range.'
        elif 'busy' in lowered or 'in progress' in lowered:
            advice = 'The receiver is busy - another device may be connected to it.'
        elif 'no usable uart' in lowered or 'characteristic' in lowered:
            advice = 'Connected, but this receiver does not expose a data channel.'
        else:
            advice = 'Connection failed.'

        return f'\u26a0\ufe0f Base "{station_name}": {advice}'

    def _maybe_recover_bluetooth(self, station_id, error_message):
        """Serialize limited controller recovery, preserving working links."""
        # Only the failure mode this actually addresses.
        if 'host is down' not in str(error_message or '').lower():
            with self.lock:
                self._connect_failure_streak[station_id] = 0
            return

        now_ts = time.monotonic()
        with self.lock:
            streak = self._connect_failure_streak.get(station_id, 0) + 1
            self._connect_failure_streak[station_id] = streak
            if streak < self.adapter_recovery_after_failures:
                return
            # A missing receiver must not reset the shared adapter underneath
            # another connected receiver. Reserve the attempt in the same lock
            # as the cooldown check so concurrent failures cannot both reset it.
            if self._adapter_recovery_running or any(
                    info.get('connected') for info in self.connections.values()):
                return
            if (self._last_adapter_recovery_at and
                    now_ts - self._last_adapter_recovery_at < self.adapter_recovery_cooldown):
                return
            self._adapter_recovery_running = True
            self._last_adapter_recovery_at = now_ts
            self._connect_failure_streak[station_id] = 0
            self._adapter_recovery_attempts += 1
            attempt = self._adapter_recovery_attempts
            self._adapter_recovery_state = {
                'status': 'resetting', 'attempt': attempt,
                'station_id': station_id, 'updated_at': int(time.time()),
            }

        if attempt <= 1:
            command = ['recover-bluetooth']
            description = 'resetting the Bluetooth adapter'
        else:
            command = ['recover-bluetooth-deep']
            description = 'power-cycling the Bluetooth radio while preserving pairing keys'

        logger.warning(f'{streak} consecutive "Host is down" failures; {description}')
        try:
            result = _run_privileged_helper(command, timeout=60)
            if result.returncode == 0:
                with self.lock:
                    if self._adapter_recovery_state.get('status') == 'resetting':
                        self._adapter_recovery_state['status'] = 'waiting_for_connection'
                logger.warning(f'Bluetooth reset completed (attempt {attempt}); '
                               'waiting for receiver connection and fresh RTCM')
            else:
                with self.lock:
                    self._adapter_recovery_state['status'] = 'failed'
                logger.error(
                    f'Bluetooth recovery failed: {(result.stderr or "").strip()[:160]}'
                )
        except Exception as recovery_error:
            with self.lock:
                self._adapter_recovery_state['status'] = 'failed'
            logger.error(f'Bluetooth recovery could not run: {recovery_error}')
        finally:
            with self.lock:
                self._adapter_recovery_running = False
                self._adapter_recovery_state['updated_at'] = int(time.time())

    def _record_position_sample(self, station_id, telemetry, offset_m=None):
        """Append one row to the base position history."""
        if not self.app:
            return

        now_ts = time.time()
        with self.lock:
            last_at = self._last_position_sample_at.get(station_id, 0)
            if now_ts - last_at < self.position_sample_interval:
                return
            self._last_position_sample_at[station_id] = now_ts

        try:
            from app.db.models import PositionSample

            with self.app.app_context():
                db.session.add(PositionSample(
                    station_id=int(station_id),
                    ts=int(now_ts),
                    latitude=telemetry.get('latitude'),
                    longitude=telemetry.get('longitude'),
                    altitude=telemetry.get('altitude_m'),
                    offset_m=offset_m,
                    satellites=telemetry.get('satellites_used'),
                    hdop=telemetry.get('hdop'),
                    fix_quality=str(telemetry.get('fix_quality') or '')[:32],
                ))
                db.session.commit()
                db.session.remove()
        except Exception as sample_error:
            logger.debug(f'Could not store a position sample: {sample_error}')

    def get_readiness(self):
        """Is the system actually ready to survey, and if not, why?

        Answers in one place the question an operator asks on site, which
        otherwise means reading half a dozen separate fields: link, data flow,
        RTCM production, base position, fix quality and satellite count. Each
        failure is reported as a plain sentence, not a status code.
        """
        report = {'ready': False, 'stations': [], 'issues': []}
        now_ts = time.time()

        try:
            from app.db.models import BaseStation, MountPoint, db
        except Exception:
            report['issues'].append('Database unavailable')
            return report

        try:
            with self.app.app_context():
                # BaseStation has no is_active column - every configured station
                # is meant to be running.
                stations = BaseStation.query.all()
                mountpoints = {
                    mount.base_id
                    for mount in MountPoint.query.filter_by(is_active=True).all()
                }
                station_rows = [
                    {
                        'id': station.id,
                        'name': station.name,
                        'position_mode': str(getattr(station, 'position_mode', '') or ''),
                        'manual_lat': float(getattr(station, 'manual_lat', 0) or 0),
                        'manual_lon': float(getattr(station, 'manual_lon', 0) or 0),
                        'has_mountpoint': station.id in mountpoints,
                    }
                    for station in stations
                ]
                db.session.remove()
        except Exception as query_error:
            report['issues'].append(f'Could not read stations: {query_error}')
            return report

        if not station_rows:
            report['issues'].append('No active base station is configured')
            return report

        for row in station_rows:
            station_id = int(row['id'])
            issues = []

            with self.lock:
                info = dict(self.connections.get(str(station_id)) or {})
            with self.telemetry_lock:
                telemetry = dict(self.telemetry.get(station_id) or {})

            if not info.get('connected'):
                issues.append('receiver is not connected')
            else:
                last_data = float(telemetry.get('last_data_at') or 0)
                if not last_data or (now_ts - last_data) > 30:
                    issues.append('no data from the receiver in the last 30 s')

                stats = stream_manager.get_stats(station_id) or {}
                if int(stats.get('frames_parsed', 0) or 0) <= 0:
                    issues.append('no RTCM produced - try Apply Config')

                fix_code = telemetry.get('fix_quality_code')
                if fix_code is not None and int(fix_code) == 0:
                    issues.append('receiver has no fix')

                satellites = telemetry.get('satellites_used')
                if satellites is not None and int(satellites) < 5:
                    issues.append(f'only {int(satellites)} satellites in use')

            if row['position_mode'] == 'manual' and not (row['manual_lat'] and row['manual_lon']):
                issues.append('manual position selected but no coordinates set')

            if not row['has_mountpoint']:
                issues.append('no active mountpoint - rovers cannot connect')

            report['stations'].append({
                'id': station_id,
                'name': row['name'],
                'ready': not issues,
                'issues': issues,
                'satellites': telemetry.get('satellites_used'),
                'hdop': telemetry.get('hdop'),
                'fix': telemetry.get('fix_quality'),
                'rovers': stream_manager.get_client_count(station_id),
            })
            report['issues'].extend(f"{row['name']}: {issue}" for issue in issues)

        report['ready'] = all(entry['ready'] for entry in report['stations'])
        return report

    def _check_station_health(self):
        """Alert on problems a connected station can still have.

        Being connected is not the same as working. Two failures are silent
        otherwise and both ruin a survey:

        * the link is up and bytes arrive, but no RTCM is produced - this is
          what a receiver that lost its base configuration looks like;
        * the receiver's own position has drifted away from the coordinates it
          is broadcasting, which means the tripod was moved or knocked.
        """
        now_ts = time.time()

        with self.lock:
            connections = {
                station_id: dict(info)
                for station_id, info in self.connections.items()
            }

        for station_id, info in connections.items():
            if not info.get('connected'):
                continue

            try:
                numeric_id = int(station_id)
            except (TypeError, ValueError):
                continue

            # Only judge a station that has been up long enough to settle.
            last_success = float(info.get('last_success') or 0)
            if not last_success or (now_ts - last_success) < 120:
                continue

            station_name = str(info.get('station_name') or f'Station {numeric_id}')

            # --- 1. Data arriving but no RTCM produced -----------------------
            stats = stream_manager.get_stats(numeric_id) or {}
            frames = int(stats.get('frames_parsed', 0) or 0)
            with self.lock:
                previous_frames = self._last_frame_counts.get(numeric_id)
                self._last_frame_counts[numeric_id] = frames

            if previous_frames is not None and frames == previous_frames:
                notify.send(
                    self.app,
                    f'\u26a0\ufe0f "{station_name}" is connected but has produced no '
                    f'RTCM for the last minute. The receiver may have lost its base '
                    f'configuration - try Apply Config.',
                    event='notify_station_error',
                    event_key=f'no-rtcm-{numeric_id}',
                    cooldown=1800.0,
                )
                logger.warning(f'{station_name}: connected but no RTCM frames are being produced')

            # --- 2. Receiver position drifting from the configured one -------
            with self.telemetry_lock:
                telemetry = dict(self.telemetry.get(numeric_id) or {})

            reported_lat = telemetry.get('latitude')
            reported_lon = telemetry.get('longitude')
            if reported_lat and reported_lon:
                station = self._load_station_snapshot(numeric_id)
                position_mode = str(getattr(station, 'position_mode', '') or '').lower()
                if station is not None and position_mode == 'manual':
                    try:
                        configured_lat = float(getattr(station, 'manual_lat', 0) or 0)
                        configured_lon = float(getattr(station, 'manual_lon', 0) or 0)
                    except (TypeError, ValueError):
                        configured_lat = configured_lon = 0.0

                    if configured_lat and configured_lon:
                        # Rough metres: 1 degree of latitude ~ 111320 m, and
                        # longitude shrinks with the cosine of the latitude.
                        delta_north = (float(reported_lat) - configured_lat) * 111320.0
                        delta_east = (
                            (float(reported_lon) - configured_lon)
                            * 111320.0
                            * math.cos(math.radians(configured_lat))
                        )
                        offset_m = math.hypot(delta_north, delta_east)
                        self._record_position_sample(
                            numeric_id, telemetry, offset_m,
                        )
                        if offset_m > self.base_drift_alert_metres:
                            notify.send(
                                self.app,
                                f'\u26a0\ufe0f "{station_name}" reports a position '
                                f'{offset_m:.1f} m away from its configured coordinates. '
                                f'Has the antenna been moved?',
                                event='notify_station_error',
                                event_key=f'drift-{numeric_id}',
                                cooldown=3600.0,
                            )
                            logger.warning(
                                f'{station_name}: reported position is {offset_m:.1f} m '
                                'from the configured base coordinates'
                            )

    def _monitor_connections(self):
        """Monitor connection status and log statistics"""
        while self.running:
            try:
                try:
                    self._check_station_health()
                except Exception as health_error:
                    logger.debug(f'Station health check failed: {health_error}')

                connected_count = 0
                total_count = 0
                error_stations = []

                with self.lock:
                    for _, conn_info in self.connections.items():
                        if conn_info.get('connected', False):
                            connected_count += 1
                        else:
                            if conn_info.get('error_count', 0) > 0:
                                station_name = str(
                                    conn_info.get('station_name')
                                    or f"Station {conn_info.get('station_id', 'unknown')}"
                                ).strip()
                                if station_name:
                                    error_stations.append(station_name)
                        total_count += 1

                if total_count > 0:
                    status_msg = f'Station connections: {connected_count}/{total_count} connected'
                    if error_stations:
                        # Something is wrong - worth a permanent record.
                        status_msg += f" (Errors: {', '.join(error_stations)})"
                        logger.warning(status_msg)
                    else:
                        # All good: heartbeat only, so a healthy system does not
                        # write a line to the SD card every single minute.
                        logger.debug(status_msg)

                time.sleep(60)

            except Exception as e:
                logger.error(f'Error in connection monitor: {e}')
                time.sleep(30)

    def stop(self):
        """Stop all Bluetooth connections"""
        logger.info('Stopping Bluetooth manager')
        self.running = False

        try:
            for channel in range(1, 31):
                _run_privileged_helper(['rfcomm-release', str(channel)], timeout=2)
        except Exception:
            pass

        for thread in self.threads:
            if thread.is_alive():
                thread.join(timeout=5)

        self.threads = [thread for thread in self.threads if thread.is_alive()]

        logger.info('Bluetooth manager stopped')

    def get_status(self):
        """Get current connection status"""
        status = {
            'total_stations': 0,
            'connected': 0,
            'disconnected': 0,
            'in_error': 0,
            'stations': [],
        }

        with self.lock:
            connections_snapshot = {
                key: dict(value) for key, value in self.connections.items()
            }

        station_map = {}
        if self.app:
            try:
                with self.app.app_context():
                    for station in BaseStation.query.order_by(BaseStation.id.asc()).all():
                        station_map[int(station.id)] = self._build_station_snapshot(station)
            except Exception as station_load_error:
                logger.error(f'Unable to load base stations for status snapshot: {station_load_error}')

        for conn_info in connections_snapshot.values():
            fallback_station_id = self._safe_int(conn_info.get('station_id'), None)
            if fallback_station_id is None or fallback_station_id in station_map:
                continue

            station_map[fallback_station_id] = SimpleNamespace(
                id=fallback_station_id,
                name=str(conn_info.get('station_name') or f'Station {fallback_station_id}'),
                bt_mac=str(conn_info.get('bt_mac') or ''),
                channel=self._safe_int(conn_info.get('channel'), 1),
                connection_type=str(conn_info.get('connection_type') or 'bluetooth'),
                gnss_port=str(conn_info.get('gnss_port') or ''),
                baudrate=self._safe_int(conn_info.get('baudrate'), 115200),
                status='unknown',
                bytes_received=0,
                bytes_sent=0,
            )

        for station_id in sorted(station_map.keys()):
            station = station_map[station_id]
            conn_info = connections_snapshot.get(str(station_id), {})

            station_status = {
                'id': station.id,
                'name': station.name,
                'bt_mac': station.bt_mac,
                'channel': station.channel,
                'connection_type': getattr(station, 'connection_type', 'bluetooth'),
                'gnss_port': getattr(station, 'gnss_port', ''),
                'baudrate': getattr(station, 'baudrate', 115200),
                'connected': conn_info.get('connected', False),
                'last_attempt': conn_info.get('last_attempt'),
                'last_success': conn_info.get('last_success'),
                'last_error': conn_info.get('last_error'),
                'error_count': conn_info.get('error_count', 0),
                'reconnect_count': conn_info.get('reconnect_count', 0),
                'status': station.status,
                'bytes_received': station.bytes_received,
                'bytes_sent': station.bytes_sent,
                'rover_clients': stream_manager.get_client_count(station.id),
                # Configuration fields: the station detail page reads these from
                # here, and without them it silently fell back to defaults (a
                # station saved as 'unicore' displayed as 'comnav').
                'data_type': getattr(station, 'data_type', 'RTCM3'),
                'output_interval': getattr(station, 'output_interval', 1),
                'operation_mode': getattr(station, 'operation_mode', 'base'),
                'position_mode': getattr(station, 'position_mode', 'auto'),
                'receiver_brand': getattr(station, 'receiver_brand', 'comnav'),
                'survey_duration_sec': getattr(station, 'survey_duration_sec', 30),
                'command_strategy': getattr(station, 'command_strategy', 'generated'),
                'antenna_height': getattr(station, 'antenna_height', 0),
                'add_antenna_height': bool(getattr(station, 'add_antenna_height', False)),
                'receiver_model': getattr(station, 'receiver_model', '') or '',
                'firmware_version': getattr(station, 'firmware_version', '') or '',
                'firmware_date': getattr(station, 'firmware_date', '') or '',
                'receiver_serial': getattr(station, 'receiver_serial', '') or '',
                'antenna_type': getattr(station, 'antenna_type', ''),
                'manual_lat': getattr(station, 'manual_lat', 0),
                'manual_lon': getattr(station, 'manual_lon', 0),
                'manual_alt': getattr(station, 'manual_alt', 0),
                'last_seen': getattr(station, 'last_seen', None),
                'created_at': getattr(station, 'created_at', None),
                'telemetry': self._get_station_telemetry_snapshot(station.id),
                'stream': stream_manager.get_stats(station.id),
                # Prefer the live link measurement; fall back to the last scan
                # sample when the device is not currently connected.
                'rssi': self._resolve_station_rssi(station),
            }
            status['stations'].append(station_status)

            if conn_info.get('connected'):
                status['connected'] += 1
            elif conn_info.get('error_count', 0) > 0 or station.status == 'error':
                status['in_error'] += 1
            else:
                status['disconnected'] += 1

            status['total_stations'] += 1

        return status


# Global instance
bluetooth_manager = BluetoothManager()
