        except (TypeError, ValueError):
            app.config['SESSION_TIMEOUT'] = 3600
        app.config['DEBUG'] = bool(server_config.get('debug', False))
        legacy_host = str(server_config.get('host', '0.0.0.0') or '0.0.0.0').strip()
