        ).strip()

        logging.getLogger().setLevel(
            getattr(logging, app.config['LOG_LEVEL'], logging.INFO)
        )
        
        logger.debug(f"Database URI: {app.config['SQLALCHEMY_DATABASE_URI']}")

        # SQLite tuning to avoid writer-vs-reader stalls that cause nginx to
        # reset upstream connections (browser sees "Failed to fetch") even
        # though the write actually committed.
        app.config['SQLALCHEMY_ENGINE_OPTIONS'] = {
            'pool_pre_ping': True,
            'pool_recycle': 300,
            'connect_args': {
                'timeout': 30,
