                        return jsonify({'error': 'Mountpoint name must be 1-64 characters: letters, digits, "_" or "-"'}), 400
                    data['name'] = mp_name
                    # Check if name already exists (excluding current mountpoint)
                    existing = MountPoint.query.filter(MountPoint.name == data['name'], MountPoint.id != id).first()
                    if existing:
