        @app.route('/api/tokens/create', methods=['POST'])
        @login_required
        def api_create_token():
            """Create an API token. Returns the plaintext token ONCE."""
            role_error = _require_admin_role()
            if role_error:
                return role_error
            try:
                data = request.json or {}
                name = str(data.get('name', '')).strip()
                if not name or len(name) > 64:
                    return jsonify({'error': 'Token name is required (max 64 chars)'}), 400

                scope = str(data.get('scope', 'read')).strip().lower()
                if scope not in ('read', 'full'):
                    scope = 'read'

                expires_days = data.get('expires_days')
                expires = 0
                if expires_days:
                    try:
                        days = int(expires_days)
                        if days > 0:
                            expires = int(time.time()) + days * 86400
                    except (TypeError, ValueError):
                        pass

                # Generate a URL-safe token; store only its hash.
                raw_token = 'gnss_' + secrets.token_urlsafe(32)
                token_hash = _hash_token(raw_token)

                try:
                    author = getattr(current_user, 'username', '') or ''
                except Exception:
                    author = ''

                token_row = ApiToken(
                    name=name,
                    token_hash=token_hash,
                    token_prefix=raw_token[:8],
                    scope=scope,
                    created_by=author,
                    expires=expires,
                    is_active=True,
                )
                db.session.add(token_row)
                db.session.commit()

                return jsonify({
                    'message': 'Token created. Copy it now — it will not be shown again.',
                    'token': raw_token,
                    'id': token_row.id,
                    'name': name,
                    'scope': scope,
                }), 201
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error creating API token: {e}")
                return jsonify({'error': str(e)}), 500

