                'backup_codes_remaining': len(stored),
            })

        @app.route('/api/2fa/setup', methods=['POST'])
        @login_required
        def api_2fa_setup():
            """Begin 2FA setup: generate a fresh secret and provisioning URI.

            Pending enrollment is separate from the active credential. Existing
            2FA must be disabled through the password-protected endpoint first.
            """
            try:
                import pyotp
            except Exception:
                return jsonify({'error': '2FA support is not installed on the server (pyotp missing)'}), 500
            try:
                secret = pyotp.random_base32()
                changed = Admin.query.filter_by(
                    id=current_user.id, totp_enabled=False
                ).update({
                    'totp_pending_secret': secret,
                    'totp_pending_expires': int(time.time()) + 600,
                })
                if changed != 1:
                    db.session.rollback()
                    return jsonify({'error': '2FA is already enabled. Disable it with your password before setting it up again.'}), 409
                db.session.commit()

                issuer = 'GNSS-Caster'
                uri = pyotp.TOTP(secret).provisioning_uri(
                    name=str(current_user.username), issuer_name=issuer
                )

                # Build a QR code PNG data-URI (server-side, no external service
                # so the secret never leaves this host).
                qr_data_uri = ''
                try:
                    import qrcode
                    import io as _io
                    import base64 as _b64
                    img = qrcode.make(uri)
                    buf = _io.BytesIO()
                    # Do NOT pass format=: when Pillow is absent (it is not a
                    # dependency), qrcode falls back to the pure-python
                    # PyPNGImage backend whose save() takes no "format"
                    # argument, so passing it raised TypeError and silently
                    # disabled the QR code. Both backends emit PNG by default.
                    img.save(buf)
                    qr_data_uri = 'data:image/png;base64,' + _b64.b64encode(buf.getvalue()).decode()
                except Exception as qr_err:
                    logger.warning(f"QR generation unavailable: {qr_err}")

                return jsonify({
                    'secret': secret,
                    'provisioning_uri': uri,
                    'qr_data_uri': qr_data_uri,
                    'issuer': issuer,
                    'account': str(current_user.username),
                })
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error setting up 2FA: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/2fa/enable', methods=['POST'])
        @login_required
        def api_2fa_enable():
            """Confirm 2FA setup with a valid code; returns one-time backup codes."""
            try:
                import pyotp
            except Exception:
                return jsonify({'error': '2FA support is not installed on the server'}), 500
            try:
                data = request.json or {}
                code = str(data.get('code', '')).strip()
                if current_user.totp_enabled:
                    return jsonify({'error': '2FA is already enabled'}), 409
                secret = str(current_user.totp_pending_secret or '')
                expires = int(current_user.totp_pending_expires or 0)
                if not secret or expires <= int(time.time()):
                    return jsonify({'error': '2FA setup expired or was not started. Start setup again.'}), 400

                if not pyotp.TOTP(secret).verify(code, valid_window=1):
                    return jsonify({'error': 'Invalid code — check your authenticator app clock'}), 400

                # Generate 10 one-time backup codes; store hashed, return plaintext once.
                plain_codes = []
                hashed_codes = []
                for _ in range(10):
                    raw = secrets.token_hex(4)  # 8 hex chars
                    plain_codes.append(raw)
                    hashed_codes.append(bcrypt.generate_password_hash(raw).decode())

                # Consume this enrollment only once, even with concurrent requests.
                changed = Admin.query.filter_by(
                    id=current_user.id, totp_enabled=False,
                    totp_pending_secret=secret,
                ).filter(Admin.totp_pending_expires > int(time.time())).update({
                    'totp_secret': secret,
                    'totp_enabled': True,
                    'totp_backup_codes': json.dumps(hashed_codes),
                    'totp_pending_secret': '',
                    'totp_pending_expires': 0,
                })
                if changed != 1:
                    db.session.rollback()
                    return jsonify({'error': '2FA setup changed or expired. Refresh and try again.'}), 409
                db.session.commit()

                logger.info(f"2FA enabled for admin {current_user.username}")
                return jsonify({
                    'message': '2FA enabled successfully',
                    'backup_codes': plain_codes,
                })
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error enabling 2FA: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/2fa/disable', methods=['POST'])
        @login_required
        def api_2fa_disable():
            """Disable 2FA for the current admin (requires current password)."""
            try:
                data = request.json or {}
                password = str(data.get('password', ''))
                if not bcrypt.check_password_hash(current_user.password, password):
                    return jsonify({'error': 'Incorrect password'}), 403

                current_user.totp_enabled = False
                current_user.totp_secret = ''
                current_user.totp_backup_codes = ''
                current_user.totp_pending_secret = ''
                current_user.totp_pending_expires = 0
                db.session.commit()
                logger.info(f"2FA disabled for admin {current_user.username}")
                return jsonify({'message': '2FA disabled'})
            except Exception as e:
                db.session.rollback()
