        @app.route('/api/base_stations/<int:id>/stream')
        @login_required
        def api_base_station_stream(id):
            """
            Server-Sent Events: streams raw receiver output to the browser console.
            Events: data: <line>  |  event: error  |  event: ping
            """
            import select as _select, time as _time

            BaseStation.query.get_or_404(id)  # 404 if unknown station

            def _generate():
                from app.bluetooth.core import bluetooth_manager
                yield ': gnss-caster receiver stream\n\n'
                deadline_ping = _time.monotonic() + 15.0
                station_id = int(id)
                # Read from the console buffer the station loop fills, never
                # from the device itself: two readers on one handle meant the
                # console consumed RTCM bytes that were meant for the rovers.
                sequence = 0
                idle_since = _time.monotonic()

                while True:
                    try:
                        sequence, lines = bluetooth_manager.read_console_lines(
                            station_id, after_sequence=sequence
                        )
                    except Exception as read_err:
                        yield f'event: error\ndata: Read error: {read_err}\n\n'
                        break

                    if lines:
                        idle_since = _time.monotonic()
                        for text in lines:
                            yield f'data: {text}\n\n'
                    else:
                        _time.sleep(0.2)
                        # Only complain once the station has genuinely gone
                        # away, not on a momentary gap between sentences.
                        if _time.monotonic() - idle_since > 20.0:
                            with bluetooth_manager.lock:
                                still_connected = station_id in bluetooth_manager.device_files
                            if not still_connected:
                                yield 'event: error\ndata: Station not connected — no active receiver device\n\n'
                                break
                            idle_since = _time.monotonic()

                    now = _time.monotonic()
                    if now >= deadline_ping:
                        yield 'event: ping\ndata: ping\n\n'
                        deadline_ping = now + 15.0

            from flask import stream_with_context, Response
            return Response(
                stream_with_context(_generate()),
                mimetype='text/event-stream',
                headers={
                    'Cache-Control': 'no-cache',
                    # 'X-Accel-Buffering: no' stops nginx buffering the stream.
                    # Do NOT set 'Connection' here: PEP 3333 forbids hop-by-hop
                    # headers in a WSGI response, and waitress rejects the whole
                    # response with an AssertionError - which surfaced as
                    # "Stream error" in the receiver console.
                    'X-Accel-Buffering': 'no',
                },
            )

        @app.route('/api/events/dashboard')
        @login_required
        def api_events_dashboard():
            """Server-Sent Events feed of dashboard status (Fix #18).

            Pushes a combined bluetooth + NTRIP snapshot every few seconds so
            the dashboard can update live instead of polling on fixed timers.
            The stream self-terminates after a bounded lifetime so waitress
            worker threads are always eventually released; the browser simply
            reconnects (EventSource does this automatically).

            Event types:
              event: snapshot  data: {<combined status json>}
              event: ping      data: ping
            """
            import time as _time
            import json as _json

            # Bound the connection lifetime (browser auto-reconnects).
            max_lifetime_s = 300
            snapshot_interval_s = 3.0
            ping_interval_s = 20.0

            def _build_snapshot():
                from app.bluetooth.core import bluetooth_manager
                from app.ntrip.core import ntrip_server
                snap = {'ts': int(_time.time())}
                try:
                    snap['bluetooth'] = bluetooth_manager.get_status()
                except Exception as bt_err:
                    snap['bluetooth'] = {'error': str(bt_err)}
                try:
                    snap['ntrip'] = ntrip_server.get_status()
                except Exception as ntrip_err:
                    snap['ntrip'] = {'error': str(ntrip_err)}
                return snap

            def _generate():
                yield ': gnss-caster dashboard stream\n\n'
                started = _time.monotonic()
                last_snapshot = 0.0
                last_ping = _time.monotonic()

                while True:
                    now = _time.monotonic()

                    if (now - started) >= max_lifetime_s:
                        # Ask the client to reconnect and end cleanly.
                        yield 'event: reconnect\ndata: lifetime\n\n'
                        break

                    if (now - last_snapshot) >= snapshot_interval_s:
                        try:
                            payload = _json.dumps(_build_snapshot(), default=str)
                            yield f'event: snapshot\ndata: {payload}\n\n'
                        except Exception as snap_err:
                            yield f'event: error\ndata: {snap_err}\n\n'
                        last_snapshot = now
                        last_ping = now

                    if (now - last_ping) >= ping_interval_s:
                        yield 'event: ping\ndata: ping\n\n'
                        last_ping = now

                    _time.sleep(0.5)

            from flask import stream_with_context, Response
            return Response(
                stream_with_context(_generate()),
                mimetype='text/event-stream',
                headers={
                    'Cache-Control': 'no-cache',
                    # 'X-Accel-Buffering: no' stops nginx buffering the stream.
                    # Do NOT set 'Connection' here: PEP 3333 forbids hop-by-hop
                    # headers in a WSGI response, and waitress rejects the whole
                    # response with an AssertionError - which surfaced as
                    # "Stream error" in the receiver console.
                    'X-Accel-Buffering': 'no',
                },
            )

